INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4f9d6f8e59fd6c38', 'lane_lexicon', 're_lane_b5d26a16a44b9da7', 'sec_lane_cd408680e6ab618b', 'طيو', 'e4.raw', 14, 2, 'definition', 'en', 'أَطْمَى ذ [ More, and most, vehement ]: see the verse cited above.', 'derived_from_raw_tei', 1883);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a653840881180e13', 'lane_lexicon', 're_lane_b5d26a16a44b9da7', 'sec_lane_77e0410a5af20231', 'طيو', 'e3.raw', 13, 2, 'definition', 'en', 'مَآءٌ طَامٍ ذ Water rising high, and filling its channel. (S.) And بَحْرٌ طَامٍ A [ high or] copious sea. (TA.)', 'derived_from_raw_tei', 1883);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_86b66e08859c98a4', 'lane_lexicon', 're_lane_b5d26a16a44b9da7', 'sec_lane_b3f72770d4f04b0b', 'طيو', 'e1.raw', 11, 2, 'definition', 'en', '1 طَيَا ذ , aor. يَطْيُو , inf. n. طُيُوٌّ ; and طَيَى , aor. يَطْمِى , (S, K,) inf. n. طُمِىٌّ , (S,) thus in the M [as well as in the S], or طَمْىٌ , thus in the K and in the book of ISk; (TA;) said of water, (S, K,) It became high, (K,) or it rose high, and filled the channel in which it flowed. (S.) [See also طَمَّ .] -b2- And, both verbs, said of a plant, It became tall. (K.) -b3- Also, (K, TA,) said of the sea, and of a river, and of a well, (TA,) It became full: (K, TA:) so says Lth. (TA.) -b4- And طَمَتْ بِزَوْجِهَا (tropical:) She (a woman) exalted herself with her husband; syn. اِرْتَفَعَتْ بِهِ ; (S, TA;) from طَمَا or طَمَى said of water: (S:) or she grinned at her husband. (Z, TA.) -b5- طَمَتْ بِهِ هِمَّتُهُ , aor. طَيُوَ and طَيِوَ as above, (assumed tropical:) His ambition elevated him. (K, * TA.) -b6- And طَمَا بِهِ said of anxiety, and of grief, and of fear, (assumed tropical:) [ طَمَايَةٌ ذ is said by Golius, as on the authority of Z, to signify Solicitude, and fear: but probably, I think, from his having found طَيَايَةٌ هَمٌّ وَخَوْفٌ erroneously written for طَمَا بِهِ هَمٌّ وَخَوْفٌ , meaning “ fear became vehement in him. ”]', 'derived_from_raw_tei', 1883);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f29ea5d83664e2ae', 'lane_lexicon', 're_lane_b6af0b8735e070a3', 'sec_lane_eb15e78d77ad1bcd', 'سيرج', 'e1.raw', 11, 2, 'definition', 'en', 'Q. 1 سَمْرَجَةٌ ذ [inf. n. of سَمْرَجَ ] The collecting of the [ tax called ] خَرَاج : (Ibn-''Abbád, O:) [and the giving, or paying, thereof: for] one says, سَمْرِجْ لَهُ , meaning Give thou to him [ the tax so called ]. (ISh, O, K. [It seems to be intentionally indicated in the O and K, by what immediately precedes the explanation of this phrase, which explanation is أَعْطِهِ , that الخَرَاجَ is to be understood after it.])', 'derived_from_raw_tei', 1426);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_05d2ca97720f8a86', 'lane_lexicon', 're_lane_b6af0b8735e070a3', 'sec_lane_f7641d8884048b84', 'سيرج', 'e2.raw', 12, 2, 'definition', 'en', 'سمرج ذ [written without any syll. signs, and therefore probably سَمْرَجْ ,] sing. of سَمَارِجُ , (TA,) which signifies Even, or plain, places [or tracts ] of land. (T, * Ibn-''Abbád, O, TA. *)', 'derived_from_raw_tei', 1426);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6d53c2125ff121cf', 'lane_lexicon', 're_lane_b6af0b8735e070a3', 'sec_lane_7d4a41db7fde7a65', 'سيرج', 'e4.raw', 14, 2, 'definition', 'en', 'سَمَرَّجَةٌ ذ : see the next preceding parapraph.', 'derived_from_raw_tei', 1426);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d38d1cd7e6cc7146', 'lane_lexicon', 're_lane_b6af0b8735e070a3', 'sec_lane_87efb319580a74b2', 'سيرج', 'e3.raw', 13, 2, 'definition', 'en', 'سَمَرَّجٌ ذ and , (S, O, K,) each a Pers. word arabicized, (S, O,) [or rather a compound of the Pers. سِهْ “ three ” and the Arabic مَرَّهْ for مَرَّة “ a time, ”] The levying of the [ tax called ] خَرَاج at three several times [or instalments ]: (S, O, K:) or the name of the day on which payment of the خَرَاج is received; (K;) thus the former word is expl. by ISh; (O;) the day of the collecting of the خراج ; (Ibn-''Abbád, ISd, O, TA;) a day when the foreigners, or Persians, ( العَجَم ) levy the خراج at three several times [or instalments ]: also mentioned as written with ش . (TA.)', 'derived_from_raw_tei', 1426);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_069fc73920bbfaee', 'lane_lexicon', 're_lane_b7bc336c4d1c2554', 'sec_lane_2048f9d85ba6ccb7', 'ذي', 'e2.raw', 12, 2, 'definition', 'en', 'ذَيَّةَ وَ ذَيَّةَ ذ : see art. ذيت .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_541946774ccd6631', 'lane_lexicon', 're_lane_b7bc336c4d1c2554', 'sec_lane_88b7e0bcb6aab91e', 'ذي', 'e1.raw', 11, 2, 'definition', 'en', 'ذى ذ fem. of ذَا : see art. ذا .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4ccb1c45d5e2a17a', 'lane_lexicon', 're_lane_b7c343c98b5bbd41', 'sec_lane_432089a17cb99471', 'ذان', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَأَنَهُ ذ , [aor. ذَأََ ,] inf. n. ذَأْنٌ , [app. from ذُؤْنُونٌ , q. v.,] He held his state, or condition, to be contemptible and weak. (TA.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0fb8aeb01a86a0e6', 'lane_lexicon', 're_lane_b7c343c98b5bbd41', 'sec_lane_9745da96a9685db9', 'ذان', 'e3.raw', 13, 2, 'definition', 'en', 'R. Q. 2 خَرَجُوا يَتَدَأْنَنُونَ ذ (S, so in both of my copies, and K and TK, but [erroneously] written in the TT as from the M يتذأْنون , and in some copies of the K يَتَذَآئَنُونَ , or يَتَذَآءَنُونَ , [the verb being evidently a denominative from ذُؤْنُونٌ like تَجَلْبَبَ from جِلْبَابٌ ,]) They went forth (S, M, K) to take, (S,) or to seek and take, (M,) or to gather, (K,) the kind of plant called ذُؤْنُون (S, M, K.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ff43d0b4b02fc76d', 'lane_lexicon', 're_lane_b7c343c98b5bbd41', 'sec_lane_b3296ddd8da9277d', 'ذان', 'e2.raw', 12, 2, 'definition', 'en', 'R. Q. 1 ذَأْنَنَتِ الأَرْضُ ذ The land produced the kind of plant called ذُؤْنُون . (IAar, M.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dca5533c837ba453', 'lane_lexicon', 're_lane_b800243ba0d9d097', 'sec_lane_405bf0aeb6e07e2a', 'ذمل', 'e3.raw', 13, 2, 'definition', 'en', 'نَاقَةٌ ذَمُولٌ ذ [ A she-camel that is accustomed to go the pace above mentioned ]: (M, K:) pl. ذُمُلٌ , (M, and so in my MS. copy of the K,) or ذُمْلٌ . (TA: in the CK ذُمَّل .)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6acdf5809d241e40', 'lane_lexicon', 're_lane_b800243ba0d9d097', 'sec_lane_61e1ff4fe7c357db', 'ذمل', 'e5.raw', 15, 2, 'definition', 'en', 'نَاقَةٌ ذَامِلَةٌ ذ [ A she-camel going the pace above mentioned ]: pl. ذَوَامِلُ . (T.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c9630d82814a73cd', 'lane_lexicon', 're_lane_b800243ba0d9d097', 'sec_lane_daa6fd6d49195453', 'ذمل', 'e2.raw', 12, 2, 'definition', 'en', '2 ذَمَّلْتُهُ ذ , inf. n. تَذْمِيلٌ , I urged him, or made him, (namely, a camel, TA,) to go the pace above mentioned. (K.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_483926cc06fcea31', 'lane_lexicon', 're_lane_b800243ba0d9d097', 'sec_lane_f5469efecf9db546', 'ذمل', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَمَلَ ذ , (S, M, K,) or ذَمَلَتْ , (T,) aor. ذَمُلَ (T, S, M, K) and ذَمِلَ , (S, M, K,) inf. n. ذَمِيلٌ (T, S, M, K) and ذَمْلٌ and ذُمُولٌ and ذَمَلَانٌ , (M, K,) said of a camel, (T, S,) He, or she, went a gentle pace: (T, M, K:) or went a pace above that which is termed العَنَقُ , (S, M, K,) and above that which is termed التَّزَيُّدُ : [for] A''Obeyd says, when the pace rises a little above that which is termed العَنَقُ , it is termed التَّزَيُّدُ ; and when it rises above this, it is termed الذَّمِيلُ ; and then, الرَّسِيمُ : As says that no camel goes the pace termed الذَّمِيل for a day and a night except the مَهْرِى . (S.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_81e578a8c0804df8', 'lane_lexicon', 're_lane_b800243ba0d9d097', 'sec_lane_945df9d09522e496', 'ذمل', 'e4.raw', 14, 2, 'definition', 'en', 'ذَمِيلَةٌ ذ Fatigued, or jaded; (IAar, T, K;) applied to a she-camel. (IAar, TA.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_899f009d369bae0c', 'lane_lexicon', 're_lane_bb239bd7ac1ab565', 'sec_lane_531983ed056e5beb', 'كبا', 'e1.raw', 11, 2, 'definition', 'en', 'كَبَا ذ : said of a horse: see above, art. حَنَذَ , p. 656 b. -b2- See also a phrase voce سَلَّةٌ . -b3- كَبَا He fell upon his face: (K, TA:) or so كَبَا لِوَجْهِهِ : S, TA:) and كَباَ also signifies عَثَرَ [ he stumbled, or tripped ]. (TA.)', 'derived_from_raw_tei', 2998);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d6b48b25e17a26b9', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_18206c43b9931c1d', 'ذرق', 'e8.raw', 18, 2, 'definition', 'en', 'لَبَنٌ مُذَرَّقٌ ذ Milk mixed with water: (AZ, S, K:) [like مُذَلَّقٌ .]', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a4181f669fac3440', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_4fe67d39efea1eaf', 'ذرق', 'e7.raw', 17, 2, 'definition', 'en', 'ذُرَاقٌ ذ : see ذَرْقٌ .', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4c7310adf680fb19', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_599c896e179db262', 'ذرق', 'e4.raw', 14, 2, 'definition', 'en', '5 تَذَرَّقَتْ ذ She applied لَبَن مُذَرَّق as a collyrium to her eyes; as also , of the measure اِفْتَعَلَتْ : [so accord, to the copies of the K: but] in the “ Nawádir el-Aaráb ” it is said, المَرْأَةُ بَالكُحْلِ signifies the woman applied collyrium to her eyes. (TA.)', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4360490dd3323309', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_cb932b82d04f515a', 'ذرق', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَرَقَ ذ , aor. ذَرُقَ and ذَرِقَ , (S, Mgh, Msb, K,) inf. n. ذَرْقٌ , (Mgh, Msb,) said of a bird, (S, Mgh, Msb, K,) It muted, or dunged; (JK, Mgh, Msb;) [like زَرَقَ ;] as also , (Zj, JK, Msb, K,) inf. n. إِذْرَاقٌ : (JK:) it is also, sometimes, (assumed tropical:) said of a man: (S, * TA:) and the latter is sometimes (tropical:) said of a beast of prey, and [particularly] of a fox. (TA.) -b2- [Hence,] one says, مَتَى تَذْرُوقٌ عَلَى النَّاسِ (tropical:) When wilt thou behave in a lightwitted, or foolish, manner towards men? or utter foul, or obscene, language against them? (TA.) And هٰذَا كَلَامٌ يَذْرَقُ عَلَيْهِ (assumed tropical:) This is speech, or language, that is deemed foul. (TA.) And لَأَذْرُقَنَّكَ إِنْ لَمْ تُرَبِّعْ is a phrase meaning a threat. (TA. [But how it should be rendered, unless it be said by a woman to her husband, (see رَبَّعَ لِٱمْرَأَتِهِ ,) and لاذرقنّك be for لَأَذْرُقَنَّ عَلَيْكَ , I know not.]) -A2- ذَرِقَ المَالُ , [in 4 أَذْرَقَ see the first sentence above. -A2- اذرقت الأَرْضُ The land produced [ the herb called ] ذُرَق . (S, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_04bbb6685a9583c9', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_e56a392e0a1c854b', 'ذرق', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرَقَ ذ , aor. ذَرُقَ and ذَرِقَ , (S, Mgh, Msb, K,) inf. n. ذَرْقٌ , (Mgh, Msb,) said of a bird, (S, Mgh, Msb, K,) It muted, or dunged; (JK, Mgh, Msb;) [like زَرَقَ ;] as also , (Zj, JK, Msb, K,) inf. n. إِذْرَاقٌ : (JK:) it is also, sometimes, (assumed tropical:) said of a man: (S, * TA:) and the latter is sometimes (tropical:) said of a beast of prey, and [particularly] of a fox. (TA.) -b2- [Hence,] one says, مَتَى تَذْرُوقٌ عَلَى النَّاسِ (tropical:) When wilt thou behave in a lightwitted, or foolish, manner towards men? or utter foul, or obscene, language against them? (TA.) And هٰذَا كَلَامٌ يَذْرَقُ عَلَيْهِ (assumed tropical:) This is speech, or language, that is deemed foul. (TA.) And لَأَذْرُقَنَّكَ إِنْ لَمْ تُرَبِّعْ is a phrase meaning a threat. (TA. [But how it should be rendered, unless it be said by a woman to her husband, (see رَبَّعَ لِٱمْرَأَتِهِ ,) and لاذرقنّك be for لَأَذْرُقَنَّ عَلَيْكَ , I know not.]) -A2- ذَرِقَ المَالُ , [in 4 أَذْرَقَ see the first sentence above. -A2- اذرقت الأَرْضُ The land produced [ the herb called ] ذُرَق . (S, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3332d9c9665c73ab', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_fc154d14feff46b4', 'ذرق', 'e3.raw', 13, 2, 'definition', 'en', '5 تَذَرَّقَتْ ذ She applied لَبَن مُذَرَّق as a collyrium to her eyes; as also , of the measure اِفْتَعَلَتْ : [so accord, to the copies of the K: but] in the “ Nawádir el-Aaráb ” it is said, المَرْأَةُ بَالكُحْلِ signifies the woman applied collyrium to her eyes. (TA.)', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_92c7a0de4b6cb936', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_7582bac0d4d4274e', 'ذرق', 'e6.raw', 16, 2, 'definition', 'en', 'ذُرَقٌ ذ A certain plant, resembling فِسْفِسَة ; (JK;) a certain herb, (TA,) i. q. حَنْدَقُوقٌ [the herb lotus, melilot, sweet trefoil, or bird''s-foot-trefoil: so in the present day]: (JK, IDrd, S, K:) it has a slight and sweet odour, and grows in [ plains such as are called ] قِيعَان , and in places where water collects and stagnates; and sheep, or goats, suffer from eating it, and sometimes become distended in their bellies: (AHn, TA:) n. un. with ة . (AHn, JK, TA.)', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5ac592626c3498fa', 'lane_lexicon', 're_lane_bba0a220536ece05', 'sec_lane_76e3cfff1b55edc6', 'ذرق', 'e5.raw', 15, 2, 'definition', 'en', 'ذَرْقٌ ذ Dung (JK, S, Mgh) of a bird; (S, Mgh;) as also : (AZ, TA:) [or] of the bustard ( حُبَارَى ) and the like: (JK:) the former word an inf. n. used as a subst. in this sense. (Mgh.)', 'derived_from_raw_tei', 964);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c2c83c43e5af4769', 'lane_lexicon', 're_lane_bf04a79bde65ada4', 'sec_lane_1c72bf75ca4dd4f9', 'سمعر', 'e1.raw', 11, 2, 'definition', 'en', 'مُسْمَقِرٌّ ذ : see art. سقر .', 'derived_from_raw_tei', 1430);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d0d37d42a633bcba', 'lane_lexicon', 're_lane_c505efac3d2b8790', 'sec_lane_2344b9ee4f73f0b4', 'ذون', 'e3.raw', 13, 2, 'definition', 'en', 'ذُونُونٌ ذ A certain plant: a dial. var. of ذُؤْنُونٌ , with ء : [see the latter in art. ذأن :] pl. ذَوَانِينُ : mentioned by Az, on the authority of Ks. (TA.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b5e4bf8f7c8a4485', 'lane_lexicon', 're_lane_c505efac3d2b8790', 'sec_lane_5048d7d5310f7e9c', 'ذون', 'e2.raw', 12, 2, 'definition', 'en', 'ذَانٌ ذ (S, K) and ذَيْنٌ , (TA,) [the latter belonging to art. ذين ,] A vice, fault, defect, or the like; (S, K;) syn. with ذَابٌ [and ذَيْبٌ ] and ذَامٌ and ذَيْمٌ ; (S, TA;) as heard by ISk from AA. (S.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eeb9f6d18f0f0c39', 'lane_lexicon', 're_lane_c505efac3d2b8790', 'sec_lane_ff94ff465c0bf2ad', 'ذون', 'e1.raw', 11, 2, 'definition', 'en', '5 تذوّن ذ He was, or became, in a state of richness, wealth, or competence, and ease and plenty. (IAar, K. [In the CK, النّعْمَةُ is here, as in many other instances, erroneously put for النَّعْمَةُ .]) [See also تدوّن . Perhaps both are correct, as dial. vars.]', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a682710837348fa3', 'lane_lexicon', 're_lane_c8c0df68a34945f9', 'sec_lane_2864c02a605814ff', 'ذهل', 'e3.raw', 13, 2, 'definition', 'en', 'ذَهْلٌ ذ : see what next follows.', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dccbac98f68987ee', 'lane_lexicon', 're_lane_c8c0df68a34945f9', 'sec_lane_299873b17ab22ff0', 'ذهل', 'e6.raw', 16, 2, 'definition', 'en', 'ذَاهِلٌ ذ [act. part. n. of 1. -b2- And] A man who cares not for ornament and the anointing of himself. (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1552dfd5363dc116', 'lane_lexicon', 're_lane_c8c0df68a34945f9', 'sec_lane_4186a858fdff6e53', 'ذهل', 'e4.raw', 14, 2, 'definition', 'en', 'جَآءَ بَعْدَ ذُهْلٍ مِنَ اللَّيْلِ ذ , (S, K, *) and , (S, K,) He came after a short portion, or a period, ( سَاعَة , K, or هَدْء , S,) of the night: (S, K:) so called because sleep causes men to forget ( يُذْهِلُ النَّاسَ ) therein: (Ham p. 4:) or a large portion; such as the third, or the half: so says IDrd; but he doubts its correctness; and ISd holds it to be preferably with د . (TA.) -A2- ذُهْلٌ also signifies The tree [or plant ] بَشَام [q. v.]. (JK, Sgh, K.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4a04cadb01d0b14f', 'lane_lexicon', 're_lane_c8c0df68a34945f9', 'sec_lane_8cfb8478adff845d', 'ذهل', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَهَلَ عَنْهُ ذ , (JK, S, Msb, K,) aor. ذَهَلَ , (S, K,) inf. n. ذَهْلٌ , (JK, S,) or ذُهُولٌ , (Msb,) or both; (K;) and ذَهِلَ , (S, Msb,) aor. ذَهَلَ , (Msb,) inf. n. ذُهُولٌ ; (S;) He forgot it, or neglected it; (S;) he was, or became, unmindful of it; (S, Msb:) or he neglected it intentionally; (JK, T, M, K, * TA; عَلَى عَهْدٍ in the K being a mistake for على عَمْدٍ , as in the [JK and T and] M; TA;) or in consequence of his being diverted by something: (T, K:) or he forgot it, or dismissed it from his mind, intentionally, and became diverted from it: (Z, Msb:) ذُهُولٌ is the neglecting a thing, dismissing it from the mind: (Ham p. 31:) or the quitting a thing, with confusion, or perplexity, or alienation of mind, such as arises from fear &c.: (Ksh and Bd in xxii. 2:) or the being diverted from one''s constant companion, or familiar, so as to forget him; and being content to relinquish him: (K;) or diversion that occasions grief and forgetfulness. (Er-Rághib, TA.) Hence, in the Kur [xxii. 2], يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّا أَرْضَعَتٌ [ 4 أَذْهَلَنِى عَنْهُ ذ , (JK, * S, Msb, TA,) inf. n. إِذْهَالٌ , (TA,) It (a thing, JK, S, TA,) or he, (a man, Msb,) caused me to forget it, or neglect it; (S;) or to be unmindful of it; (S, Msb;) or to neglect it intentionally: (JK:) [like أَذَهَنَنِى عنه :] and sometimes one says ; (Msb, TA;) [like ذَهَنَنى ;] but this is rare; or, rather, unknown. (TA.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f5d1ca1f47feed02', 'lane_lexicon', 're_lane_c8c0df68a34945f9', 'sec_lane_9db2bdeffbe67c63', 'ذهل', 'e5.raw', 15, 2, 'definition', 'en', 'ذُهْلُولٌ ذ A horse fleet, or swift: (K:) or light, or active: and so a man: pl. ذَهَالِيلُ . (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_67144e4b6fd23302', 'lane_lexicon', 're_lane_cff6682f04de15e1', 'sec_lane_3092c41bc3abaacc', 'ذيع', 'e3.raw', 13, 2, 'definition', 'en', 'مِذْيَاعٌ ذ [ A babbler of secrets &c.; ] one who will not keep, or conceal, a secret: (S, K:) or one who is unable to conceal his information, news, or tidings: an epithet of an intensive form: (TA:) pl. مَذَايِيعُ . (S.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a4d825ff68fc9674', 'lane_lexicon', 're_lane_cff6682f04de15e1', 'sec_lane_3e7b3bde77cae035', 'ذيع', 'e2.raw', 12, 2, 'definition', 'en', '4 اذاعهُ ذ , (S, Msb, K,) and اذاع بِهِ , (Zj, K,) as in the Kur iv. 85, (Zj,) inf. n. إِذَاعَةٌ , (TA in art. ذوع ,) He spread, published, divulged, revealed, made known, or disclosed, it; (Zj, S, Msb, * K;) and (so Zj, but in the K, “ or, ”) proclaimed it among the people; (Zj, K;) namely, information, news, or tidings, (S,) or discourse, (Msb,) or a secret. (K.) -b2- Hence, app., (TA in art. ذوع ,) اذاع القَوْمُ (S, K,) and اذاعت الإِبِلُ , (K,) مَا فِى الحوض , (S,) or بِمَا فى الحوض , (K,) (tropical:) The people, or company of men, and the camels, drank what was in the watering-trough, or tank, (S, K, TA,) all of it. (S.) -b3- And hence, app., (TA,) اذاع بِهِ signifies also (tropical:) He took it away; namely, another''s property, (K,) and anything. (TA.) -b4- Accord. to the K, the medial radical letter is both و and ى ; but correctly it is ى : (TA in the present art. and in art. ذوع :) so accord. to AZ and J and Z. (TA in art. ذوع .)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f03666029c738c3e', 'lane_lexicon', 're_lane_cff6682f04de15e1', 'sec_lane_6d3486e92ae5291d', 'ذيع', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَاعَ ذ , aor. يَذِيعُ , inf. n. ذَيْعٌ and ذُيُوعٌ (S, Msb, K) and ذَيْعُوعَةٌ and ذَيَعَانٌ , (S, K,) It (information, news, or tidings, S, K, or discourse, Msb, and a thing, TA) became spread, published, or divulged; (S, Msb, K, TA;) became revealed, made known, or disclosed. (Msb.) -b2- You say also, ذَاعَ الجَوْرُ (assumed tropical:) Injustice, or tyranny, spread. (TA.) -b3- And ذَاعَ الجَرَبُ فِى الجِلْدِ (tropical:) The mange, or scab, became general, and spread, in the skin. (TA.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_73ce7d17f849b993', 'lane_lexicon', 're_lane_d1dbf66e811f5ce9', 'sec_lane_cd68e73a0e49638b', 'ذات', 'e1.raw', 11, 2, 'definition', 'en', 'ذَاتُ ذ ; dual. ذَوَاتَا ; pl. ذَوَاتٌ : see art. ذو .', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2ec02ec320bddcec', 'lane_lexicon', 're_lane_d1dbf66e811f5ce9', 'sec_lane_8abdf90c86e3a793', 'ذات', 'e2.raw', 12, 2, 'definition', 'en', 'ذَاتِىٌّ ذ : and ذَاتِيَّةٌ : see art. ذو .', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bde25b55cfd11cb5', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_00f3a9732c7832bf', 'قعسس', 'e3.raw', 13, 2, 'definition', 'en', '1 قَعِسَ ذ , aor. قَعَسَ , (TK,) inf. n. قَعَسٌ , (S, A, K,) He (a man, TK) had a protruding, or protuberant, breast, or chest, and a hollow, or receding, back; قَعَسٌ being the contr. of حَدَبٌ . (S, A, K, TK.) [And in like manner,] قَعَسٌ in a bow is A bending outwards of its inner side, in its middle, and a bending inwards of its outer side. (TA.) -b2- See also 6, in two places. -A2- قَعَسَ الشَّىْءَ , [aor. قَعَسَ ,] inf. n. قَعْسٌ , He bent the thing; as also . (TA.)', 'derived_from_raw_tei', 2548);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eb1a011bc16ea7c6', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_24d058a2394ceb78', 'قعسس', 'e6.raw', 16, 2, 'definition', 'en', 'R. Q. 3 إِقْعَنْسَسَ ذ : see 6, in five places.', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_98af1c6ea922f0f4', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_45e7a4b77159924e', 'قعسس', 'e7.raw', 17, 2, 'definition', 'en', 'قَعِسٌ ذ : see أَقْعَسُ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_61f099d8240f079a', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_5a810eaf6e196b86', 'قعسس', 'e1.raw', 11, 2, 'definition', 'en', '1 قَعِسَ ذ , aor. قَعَسَ , (TK,) inf. n. قَعَسٌ , (S, A, K,) He (a man, TK) had a protruding, or protuberant, breast, or chest, and a hollow, or receding, back; قَعَسٌ being the contr. of حَدَبٌ . (S, A, K, TK.) [And in like manner,] قَعَسٌ in a bow is A bending outwards of its inner side, in its middle, and a bending inwards of its outer side. (TA.) -b2- See also 6, in two places. -A2- قَعَسَ الشَّىْءَ , [aor. قَعَسَ ,] inf. n. قَعْسٌ , He bent the thing; as also . (TA.)', 'derived_from_raw_tei', 2548);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_45acfaccd165de52', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_d2042cb816ad9110', 'قعسس', 'e9.raw', 19, 2, 'definition', 'en', 'قُعَيْسِسٌ ذ : see مُقْعَنْسِسٌ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_33148e77bd56ee47', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_d6cfaea7bf3ffbbd', 'قعسس', 'e2.raw', 12, 2, 'definition', 'en', '1 قَعِسَ ذ , aor. قَعَسَ , (TK,) inf. n. قَعَسٌ , (S, A, K,) He (a man, TK) had a protruding, or protuberant, breast, or chest, and a hollow, or receding, back; قَعَسٌ being the contr. of حَدَبٌ . (S, A, K, TK.) [And in like manner,] قَعَسٌ in a bow is A bending outwards of its inner side, in its middle, and a bending inwards of its outer side. (TA.) -b2- See also 6, in two places. -A2- قَعَسَ الشَّىْءَ , [aor. قَعَسَ ,] inf. n. قَعْسٌ , He bent the thing; as also . (TA.)', 'derived_from_raw_tei', 2548);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cf89669fbee596fc', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_f8f4cbddada3d9e9', 'قعسس', 'e10.raw', 20, 2, 'definition', 'en', 'قُعَيْسِيسٌ ذ : see مُقْعَنْسِسٌ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8dbc444406e7b7e1', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_fcadad8e27dfa521', 'قعسس', 'e8.raw', 18, 2, 'definition', 'en', 'قُعَيْسٌ ذ : see مُقْعَنْسِسٌ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_12e85f0b9c79adce', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_a352a416c68effe6', 'قعسس', 'e11.raw', 21, 2, 'definition', 'en', 'قُعَيْنِسٌ ذ : see مُقْعَنْسِسٌ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_edf420e4037adf22', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_b01d02ad19aa42b4', 'قعسس', 'e4.raw', 14, 2, 'definition', 'en', '6 تقاعس ذ He made his [meaning his own] breast, or chest, to stick out. (A.) -b2- He drew back, and became refractory, and made himself like him who has a hollow, or receding, back, and a protruding, or protuberant, breast, or chest. (Har, p. 17.) -b3- (assumed tropical:) He drew back; held back; or hung back. (S, K.) You say, تقاعس عَنِ الأَمْرِ (tropical:) He drew back, held back, or hung back, from the thing, or affair, and would not go forward in it; (S, TA;) as also , inf. n. قَعَسٌ ; and : (TA:) in some copies of the S, instead of تقاعس , in this phrase, we find . (TA.) And [in like manner,] (assumed tropical:) He drew back; he receded, or went backwards. (S, K.) When a man draws water without a pulley, pulling the rope at the head of the well, his back pains him, and it is said to him, Q. Q. 2 تَقَعْوَسَ ذ : see 6.', 'derived_from_raw_tei', 2548);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d5fed19e9c91a50d', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_c562071f24f0bb88', 'قعسس', 'e12.raw', 22, 2, 'definition', 'en', 'أَقْعَسُ ذ Having a protruding, or protuberant, breast, or chest, and a hollow, or receding, back; (S, A, K;) as also (S, K) and : (S:) [or the last rather signifies making his breast, or chest, to stick out: see its verb:] fem. of the first, قَعْسَآءُ ; (K;) applied to a woman [&c.]: and pl. قُعْسٌ : the dim. of the first is أُقَيْعِسُ . (TA.) [See أَجْنَأُ and أَفْزَرُ .] -b2- Applied to a horse, Having the صَهْوَة [or place of the saddle ], (K,) or the spine in that part, (S,) depressed, and the قَطَاة [or part next behind ] elevated; (S, K;) [i. e., saddle-backed. ] -b3- Applied to a camel, Having the head and neck and back inclining: (K:) or having the head and neck inclining towards the back: (S:) the latter is the right explanation. (TA.) Hence the saying, اِبْنُ خَمْسٍ عَشَآءُ خَلِفَاتٍ قُعْسٍ , meaning, The tarrying of the moon five nights old until it sets is like the tarrying during the evening feed of pregnant cam مُقْعَنْسِسٌ ذ (assumed tropical:) Drawing back; holding back; or hanging back: [see its verb:] (TA:) or strong; powerful; mighty: (S, K, TA:) also anything drawing in his head upon his neck, like him who refrains, or defends himself, from a thing: a camel that resists being led: anything that resists, or withstands: might, or power, that resists, or withstands, injury. (TA.) [See also أَقْعَسُ .] The pl. is مَقَاعِسُ and مَقَاعِيسُ ; (S, K;) the addition of the ى being in this case optional. (S.) The dim. is مُقَيْعِسٌ , or مُقَيْعِيسٌ , (Sb, S, K,) or قُعَيْسِسٌ and قُعَيْسِيسٌ , (TA,) or قُعَيْنِسٌ , (S, TA,) or قُعَيْسٌ : (TA: and so in some copies of the K:) Mbr objected to the first and second of these, as not agreeable with analogy; and preferred the third and fourth, or, accord. to the S, the fifth, or, as some say, the last. (TA.)', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_443d834414cc7f68', 'lane_lexicon', 're_lane_d1de6a4fee10736d', 'sec_lane_c5adcb76db1de665', 'قعسس', 'e14.raw', 24, 2, 'definition', 'en', 'مُتَقَاعِسٌ ذ : see أَقْعَسُ .', 'derived_from_raw_tei', 2549);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dae62b668e124dd8', 'lane_lexicon', 're_lane_d3bd03512a16f467', 'sec_lane_4e4ff81d174fcea7', 'ذيا', 'e3.raw', 13, 2, 'definition', 'en', '2 ذيّأ ذ , (T, S, K,) inf. n. تَذْيْىْءٌ , (K,) He cooked flesh-meat thoroughly, so that it fell off from the bone. (T, S, K.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b6e2106074f4da90', 'lane_lexicon', 're_lane_d3bd03512a16f467', 'sec_lane_d4373c9689467f41', 'ذيا', 'e1.raw', 11, 2, 'definition', 'en', 'ذَيَّا ذ , and ذَيَّاكَ , and ذَيَّالِكَ : see the two sentences next before the last in art. ذا .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8d1fe707dbe90def', 'lane_lexicon', 're_lane_d3bd03512a16f467', 'sec_lane_657459d60e4c3beb', 'ذيا', 'e2.raw', 12, 2, 'definition', 'en', 'ذَيَّآءَ وَ ذَيَّآءَ ذ : see art. ذيت .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_aa5afdd196097d67', 'lane_lexicon', 're_lane_d3bd03512a16f467', 'sec_lane_77b92665c7365c67', 'ذيا', 'e4.raw', 14, 2, 'definition', 'en', '5 تذيّأ ذ , said of flesh, or flesh-meat, (T, S, M, K,) It became separated from the bone by reason of corruption, (T, M, K,) or in consequence of cooking, (T,) or by slaughter, (M, K,) or from some other cause: (TA:) or became thoroughly cooked, so that it fell off from the bone. (S.) It (a wound, As, S, M, K,) became dissundered, or ragged, and corrupt, or putrid: (As, S, M, K:) and so said of other things: (K:) thus تَذَيَّأَتْ said of a قِرْبَة [or water-skin], (M, * TA,) and of a مَزَادَة [or leathern water-bag]. (TA.) -b2- It (the face) became swollen. (K.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bb5637b598f0ece6', 'lane_lexicon', 're_lane_daf23de7147146f3', 'sec_lane_97388eadcc7b7be2', 'ذيف', 'e1.raw', 11, 2, 'definition', 'en', 'ذِيفَانٌ ذ and ذَيْفَانٌ (S, M, K) and ذَيَفَانٌ (M, K) Deadly poison: (S, M, K:) or poison that takes effect; or that remains fixed, and collects: (M:) a dial. var. of ذِئْفَانٌ &c., (K,) and ذُوفَانٌ . (M.) And the second of these words, Death: so in the saying, سَقَاهُ ٱللّٰهُ كَأْسَ الذَّيْفَانِ [ May God give him to drink the cup of death ]; as mentioned by Lh. (M.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a62b1cca0cdebed0', 'lane_lexicon', 're_lane_dc5f67ec430d0979', 'sec_lane_d06d04bb7e4d8c6c', 'غنو', 'e1.raw', 11, 2, 'definition', 'en', 'غُنْوَةٌ ذ : see the art. here following.', 'derived_from_raw_tei', 2301);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0442b813e69eb5dc', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_36842e03c7a701b2', 'ذيل', 'e6.raw', 16, 2, 'definition', 'en', 'ذَيْلٌ ذ The latter, or kinder, or the last, or kindmost, part of anything. (M, K.) Accord. to MF, this is the proper signification, and the other significations here following are tropical. (TA.) [But in my opinion, the word in each of the next two senses, or at least in the former of them; if not strictly proper, is what is termed حَقِيقَةٌ عُرْفِيَّةٌ , i. e. a word so much used in a tropical sense as to be, in that sense, conventionally regarded as proper.] -b2- [ A skirt, or lower extremity, of a garment, reaching nearly, or quite, to the ground, or that is dragged upon the ground, when made to hang down: ] the extremity, of a garment, that is next the ground, and so if not touching it [ as well as if touching it ]; an inf. n. used in this sense: (Msb:) or the part of a waist-wrapper ( إِزَار ), and of a garment [of any kind], that is dragged [ upon the ground ], (M, K,) when it is made to hang down: (M:) or the part, of an إِزَار , and of a [garment of the kind called] رِدَآء , that is made to hang down, and touches the ground: and the part, of any kind of garment worn by a woman, that the wearer drags upon the ground behind her: (Lth, T:) or the parts, all round, of a woman''s garment, that fall upon the ground: ذَيَّالٌ ذ : see ذَائِلٌ , in three places. -b2- Also That behaves proudly, conceitedly, or vainly, and walks with an elegant and a proud and self-conceited gait. (TA.) Applied to a horse, That carries himself in an elegant and a proud and self-conceited manner, in his step, and in curvetting, or raising his fore legs together and putting them down together, and kneading with his hind legs, or in prancing, as though he dragged along the ذَيْل [or pendent portion ] of his tail. (M.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c4e82565c7cdbe2c', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_4329065674a81c59', 'ذيل', 'e4.raw', 14, 2, 'definition', 'en', '5 تذيّلت الدَّابَّةُ ذ The beast moved about its tail. (M.) -b2- And hence, (M,) تذيّل He (a man, TA) walked with an elegant and a proud and self-conceited gait, (M, K,) [app., dragging his ذَيْل (or skirt ), like ذَالَ .] -b3- [It occurs in the M and L, in art. رأد : said of a branch, or twig, app. as meaning It inclined limberly from side to side: but in the K, I there find in its place تذبّل .] -b4- See also 1.', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2021b7946f0be2b1', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_440a965f43d39564', 'ذيل', 'e10.raw', 20, 2, 'definition', 'en', 'مُذْيِلٌ ذ [so in my MS. copy of the K, as in the M, but in other copies of the K مُذَيَّلٌ ,] and [in the CK مُتَذَيَّلٌ ] i. q. مُتَبَذِّلٌ [One who performs his own work; or who is careless of himself or his honour or reputation ]. (M, K.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fff0ee134011d478', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_f5ab87dcb3e271c8', 'ذيل', 'e11.raw', 21, 2, 'definition', 'en', 'مُذَيَّلٌ ذ A garment, (T,) of the kind called مُلَآء , (T, S,) or رِدَآء , (K,) Long (T, S, K) in the ذَيْل [or skirt ]. (S, K.) So in a verse of Imra-el- Keys, of which the latter hemistich is cited voce دُوَارٌ . (T, TA.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4980b6897304fd25', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_6365b6ddf52f106b', 'ذيل', 'e8.raw', 18, 2, 'definition', 'en', 'ذَائِلٌ ذ , applied to a horse, Having a ذَيْل , (T, K,) i. e. tail: (T:) and having a long ذَيْل : (T, K:) or the former word has the latter signification; (IKt, T, M;) it means having a long tail: (S:) and ↓ the latter word, tall, and having a long ذَيْل , (M, K,) and that carries himself in an elegant and a proud and self-conceited manner, in his step; (K;) and is applied in the same sense to a wild bull: (M:) or the former word signifies short, and having a long tail; and its fem. is with ة : (T:) or when a horse is of this description, they say الذَّنَبِ , mentioning the ذَنَب . (T, S.) -b2- Also, applied to a دِرْع , (S, M, K,) [i. e. a coat of mail, as is shown in the S and TA,] Long (S, M, K) in the ذَيْل [or shirt ]; (S;) and so ذَائِلَةٌ and . (M, K. [In the CK, the last word is erroneously written مَذَالَةٌ .]) -b3- And حَلْقَةٌ ذَائِلَةٌ and مُذَالٌ ذ ; fem. with ة : see the latter in the next preceding paragraph, in two places. -b2- The fem. also means (assumed tropical:) A female slave: (T, S, M:) because she is held in low, or mean, estimation, while she carries herself in an elegant and a proud and selfconceited manner: so in the prov., أَخِيلُ مِنْ مُذَالَةٍ [ More proud and self-conceited than a female slave ]. (S, K.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c294c2b77a06d260', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_82dbb556bb2a7744', 'ذيل', 'e13.raw', 23, 2, 'definition', 'en', 'مُتَذَيِّلٌ ذ : see مُذِيلٌ .', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_99987ddecb089619', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_8cc9344a9a73fcfb', 'ذيل', 'e3.raw', 13, 2, 'definition', 'en', '4 أَذْيَلَ ذ : see 1, second sentence. -A2- اذال ثَوْبَهُ : see 2. -b2- اذالت قِنَاعَهَا She (a woman) let down her head-covering. (T, S, K. *) -b3- اذالهُ , (T, S, M, Msb, K,) inf. n. إِذَالَةٌ , (S, * M, Msb,) He lowered him; abased him; rendered him vile, mean, contemptible, or ignominious; or held him in low, or mean, estimation; (T, S, M, Msb, K;) and did not tend him, or take care of him, well; (M, K;) namely, his horse, (T, S, M,) and his young man, or slave; (S;) or it is said of the owner of a thing. (Msb.) It is said in a trad., (S, M,) of the Prophet, (M,) نَهَى عَنْ إِذَالَةِ الخَيْلِ , (S, M,) i. e. [ He forbade ] the using of horses for mean work, and burdens. (S, TA.) -b4- And أَذْلْتُهَا I rendered her lean; or emaciated her; namely, a woman, and a camel. (TA.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d899817269f93e21', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_a84ca81b752e8846', 'ذيل', 'e12.raw', 22, 2, 'definition', 'en', 'أَرْضٌ مُتَذَيَّلَةٌ ذ A land upon which has fallen a weak and small quantity ( لَطْخٌ ضَعِيفٌ ) of rain. (Sgh, K.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d9d02df183217c47', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_ae1e9012abf3789e', 'ذيل', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَالَ ذ , aor. يَذِيلُ , inf. n. ذَيْلٌ , It (a garment) was long, so that it touched the ground. (Msb.) -b2- He, or it, had a ذَيْل ; [app. said of a horse &c., as meaning he had a long tail, or a pendent portion to his tail; and probably of a garment, as meaning it had a skirt, or lower extremity, reaching nearly, or quite, to the ground, or dragged upon the ground, when made to hang down; and perhaps of a man, as meaning he had a ذيل to his garment; ] as also . (M, K.) -b3- And, said of a man, (M, Msb, K,) aor. as above, (M, Msb,) and so the inf. n., (M,) He walked with an elegant and a proud and self-conceited gait, dragging his ذَيْل [or skirt, or the lower extremity of his garment ]; (M, K;) and in like manner ذَالَتْ is said of a she-camel: (M:) or he dragged his أَذْيَال [or skirts, or the lower extremities of his garment or garments ], by reason of pride and self-conceit: (Msb:) or ذَالَتْ , (T, S,) فِى مِشْيَتِهَا , said of a girl, or young woman, (T,) o 2 ذيّل ثَوْبَهُ ذ , inf. n. تَذْيِيلٌ , [ He made his garment to have a ذَيْل , i. e. shirt, or lower extremity, reaching nearly, or quite, to the ground, or such as to be dragged upon the ground; or] he made his garment long: (T:) and ثَوْبَهُ he made his garment to have a long ذَيْل . (T, TA.) -b2- [Hence, ذَيَّلْتُ كِتَابَهُ (assumed tropical:) I added an appendix to his writing, or book; like ذَنَّبْتُهُ . And hence, the inf. n. تَذْيِيلٌ is used to signify (assumed tropical:) An appendix; like تَذْنِيبٌ ; as also .] -A2- ذَيَّلْتُ ذَالًا [ I wrote a ذ ]. (IB, TA on the letter ا .) [See also 2 in art. ذول .]', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d016a6790c169669', 'lane_lexicon', 're_lane_de1fa96a58f10f0a', 'sec_lane_bce0ced108a25f92', 'ذيل', 'e5.raw', 15, 2, 'definition', 'en', '5 تذيّلت الدَّابَّةُ ذ The beast moved about its tail. (M.) -b2- And hence, (M,) تذيّل He (a man, TA) walked with an elegant and a proud and self-conceited gait, (M, K,) [app., dragging his ذَيْل (or skirt ), like ذَالَ .] -b3- [It occurs in the M and L, in art. رأد : said of a branch, or twig, app. as meaning It inclined limberly from side to side: but in the K, I there find in its place تذبّل .] -b4- See also 1.', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5bc0f7bec55012af', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_0095f7550d8ea5fb', 'ذبر', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَبَرَ ذ , (T, S, M, A, K,) aor. ذَبُرَ (T, S, M, K) and ذَبِرَ , (S, M, K,) inf. n. ذَبْرٌ ; (M, A, K;) and , (M, A,) inf. n. تَذْبِيرٌ ; (K;) He wrote (A ''Obeyd, T, S, M, A, K) a writing, or a book; (A ''Obeyd, T, S, M, A;) like زَبَرَ : (A ''Obeyd, T, S:) or both signify, (M,) or the former signifies also, (K,) he pointed, or dotted, (M, K,) it: (M:) or (M, but in the K “ and, ”) he read it, or recited it, (IAar, T, M, K, *) with a low, or faint, voice; (M, K;) or easily; (M, A, each in relation to both verbs;) or quickly: (K:) all of the dial. of Hudheyl. (M.) You say, مَا أَحْسَنَ مَا يَذْبُرُ الشِّعْرَ How well he recites poetry, or the poetry, (K, TA,) without halting, or hesitating, therein! (TA.) And مَا أَحْسَنَ مَا الكِتَابَ How well he reads, or recites, the book, or the writing, without pausing therein! (A.) -b2- And ذَبَرَ , (IAar, Th, T, M, K,) aor. ذَبُرَ , inf. n. 2 ذَبَّرَ see 1, in two places.', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f39044abf795ecea', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_0c22c663b8f80ed2', 'ذبر', 'e8.raw', 18, 2, 'definition', 'en', 'مَذْبُورٌ ذ : see ذَبْرٌ .', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_41ee9cadb7ba61ce', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_3d6c47db0d6e7bc1', 'ذبر', 'e4.raw', 14, 2, 'definition', 'en', 'ذَبِرٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2e4cce260f2e53e8', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_5639755b56435beb', 'ذبر', 'e7.raw', 17, 2, 'definition', 'en', 'مُذَبَّرٌ ذ A garment, or piece of cloth, figured with marks resembling writing, or otherwise; syn. مُنَمْنَمٌ : (M, K:) of the dial. of El-Yemen. (M.)', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f7e00c039c1ebcb8', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_d3daa2b7aa994a66', 'ذبر', 'e3.raw', 13, 2, 'definition', 'en', 'ذَبْرٌ ذ A writing, (As, T, K,) in the dial. of Himyer, written upon عُسُب [or leafless palmsticks, or the lower portions of palm-sticks, upon which no leaves have grown ]: (K:) and i. q. صَحِيفَةٌ [ a piece of paper, or skin, upon which something is written; or a writing, or book ]: (K:) pl. ذِبَارٌ (As, T, K.) -b2- كِتَابٌ ذَبْرٌ , (M, A,) or , like كَتِفٌ , (K,) A writing, or book, easy to be read: (A, K:) or ذَبْرٌ in this phrase is an inf. n. used in the place of the pass. part. n. [which signifies written; or pointed; or read, or recited, with a low, or faint, voice, or easily, &c.]. (M.) -A2- Also A mountain; in the Abyssinian language: so accord. to one reading, but accord. to another reading دَبْرٌ , in a trad. cited in art. دبر . (TA.)', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_53520d2fa87cb2c0', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_d48feb520796052d', 'ذبر', 'e6.raw', 16, 2, 'definition', 'en', 'مِذْبَرٌ ذ A reed-pen; like مِزْبَرٌ . (TA.)', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8543d7340f6c7994', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_d64621f3b25ca440', 'ذبر', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَبَرَ ذ , (T, S, M, A, K,) aor. ذَبُرَ (T, S, M, K) and ذَبِرَ , (S, M, K,) inf. n. ذَبْرٌ ; (M, A, K;) and , (M, A,) inf. n. تَذْبِيرٌ ; (K;) He wrote (A ''Obeyd, T, S, M, A, K) a writing, or a book; (A ''Obeyd, T, S, M, A;) like زَبَرَ : (A ''Obeyd, T, S:) or both signify, (M,) or the former signifies also, (K,) he pointed, or dotted, (M, K,) it: (M:) or (M, but in the K “ and, ”) he read it, or recited it, (IAar, T, M, K, *) with a low, or faint, voice; (M, K;) or easily; (M, A, each in relation to both verbs;) or quickly: (K:) all of the dial. of Hudheyl. (M.) You say, مَا أَحْسَنَ مَا يَذْبُرُ الشِّعْرَ How well he recites poetry, or the poetry, (K, TA,) without halting, or hesitating, therein! (TA.) And مَا أَحْسَنَ مَا الكِتَابَ How well he reads, or recites, the book, or the writing, without pausing therein! (A.) -b2- And ذَبَرَ , (IAar, Th, T, M, K,) aor. ذَبُرَ , inf. n. 2 ذَبَّرَ see 1, in two places.', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e26293f9a40b2dbb', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_e8b921b6dc2b10c2', 'ذبر', 'e5.raw', 15, 2, 'definition', 'en', 'ذَابِرٌ ذ Knowing, or learning, well, soundly, or thoroughly, a matter of science or knowledge. (IAar, T, K.)', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_21a0a86165c0a56c', 'lane_lexicon', 're_lane_e33c85df49638ed2', 'sec_lane_f0d91f20e645dfdc', 'ذبر', 'e9.raw', 19, 2, 'definition', 'en', 'مُذَابِرٌ ذ , occurring in a trad., is explained by IAth as meaning Going away; if it be not a mistranscription [for مُدَابِرٌ , which seems to be probably the case]. (TA.)', 'derived_from_raw_tei', 955);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0f093e39b66019a7', 'lane_lexicon', 're_lane_e5fc2d16b7fc0948', 'sec_lane_3e8529a78acc52e7', 'غمه', 'e3.raw', 13, 2, 'definition', 'en', 'غَمًا ذ ; dual غَمَوَانِ : see غَمًى in art. غمى .', 'derived_from_raw_tei', 2298);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bd7d72ddf5df1187', 'lane_lexicon', 're_lane_e5fc2d16b7fc0948', 'sec_lane_5a9abd748eef6b51', 'غمه', 'e2.raw', 12, 2, 'definition', 'en', 'غَمَا ذ in the phrase غَمَا وَٱللّٰهِ , i. q. أَمَا [expl. in art. اما ]; (K, TA;) as also with ع . (TA.)', 'derived_from_raw_tei', 2298);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2a8035be49731d9c', 'lane_lexicon', 're_lane_e5fc2d16b7fc0948', 'sec_lane_f5ce2ef1c6c0da80', 'غمه', 'e1.raw', 11, 2, 'definition', 'en', '1 غَمَا البَيْتَ ذ , aor. يَغْمُوهُ , inf. n. غَمْوٌ : see 1 in art. غمى .', 'derived_from_raw_tei', 2298);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c2fe8330c29cbdf2', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_0114385547787ad9', 'ذار', 'e5.raw', 15, 2, 'definition', 'en', 'ذِئَارٌ ذ Fresh camels'' or similar dung, ( بَعَر ,) mixed with dust, or earth, with which a she-camel''s teats are smeared, that she may not be sucked. (M, * K, * TA.) [See also art. ذير .]', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a52edf604fb4775e', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_03b728d0ab981222', 'ذار', 'e3.raw', 13, 2, 'definition', 'en', '4 أَذْأَرَهُ عَلَيْهِ ذ He made him angry with him. (M, K. *) A ''Obeyd has transposed, and then changed, one of its letters, saying أَذْرَانِى , which is a mistake. (M.) -b2- اذأرهُ , (inf. n. إِذْآرٌ , AZ, S,) He excited him to animosity; (AZ, T, S;) incited him; (AZ, S, M, K;) emboldened him; (K;) بِصَاحِبِهِ [ against his companion ]. (AZ, S, M.) -b3- اذأرهُ إِلَى شَىْءٍ , (M, K, *) and اذأرهُ شَيْئًا , (TA,) He constrained or compelled or necessitated him to have recourse to, or to do, a thing. (M, K, * TA.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9876747095416fab', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_2aa6a18c539af520', 'ذار', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَئِرَ عَلَيْهِ ذ , (S, * K, * TA,) aor. ذَأََ , (K,) inf. n. ذَأَرٌ , (M,) He was angry with him: (M, * K, * TA:) he was enraged against him, namely his enemy, and prepared to spring upon him. (Lth.) -b2- He became emboldened against him. (S * K, * TA.) -b3- ذَئِرَ , aor. ذَأََ , He became contracted in his bosom, and evil in his disposition. (Ibn-Es-Seed.) -b4- He was frightened, or terrified; he feared, or was afraid. (M, K.) -b5- He was disdainful, or averse [from a person or thing]; or he disdained, or scorned: (K:) he became affected with aversion and disapprobation: ''Obeyd Ibn-El-Abras says, ذَئِرُوا لِقَتْلَى عَامِرٍ وَتَغَضَّبُوا meaning They became affected with aversion and disapprobation on account of the slain of ''Ámir [ and became angry ]: (T, S:) or, as some say, were disdainful, or averse, thereat. (T.) -b6- ذَئِرَهُ , (aor. ذَأََ , TA,) He disliked, or hated, it, and turned away, or back, from it. (S, K.) 3 ذَآءَرَتْ ذ : see 1. -b2- Also She (a camel) was averse from her young one when she brought it forth. (TA.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_29cc19f764479994', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_4d9ddad7c3adf97f', 'ذار', 'e7.raw', 17, 2, 'definition', 'en', 'مُذَائِرٌ ذ : see ذَائِرٌ . -b2- Also, [without ة ,] A she-camel averse from her young one when she has just brought it forth: (A ''Obeyd, S, K:) or that makes a show of affection with her nose [ by smelling her young one ] ( تَرْأَمُ بِأَنْفِهَا ), and has not true love: (S, M, K:) or evil in disposition. (M.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5078780235a98751', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_f376ce7b1d3fd1a8', 'ذار', 'e6.raw', 16, 2, 'definition', 'en', 'ذَائِرٌ ذ Angry; (IAar, T, K;) as also . (K.) -b2- Contracted in the bosom, and evil in disposition. (Ibn-Es-Seed.) -b3- Disdaining, or averse [from a person or thing]: disdainful; scornful. (IAar, T.) -b4- A woman disobedient to her husband, and hating him; (S, K;) averse from him; and emboldened against him; (S;) as also , and : (K:) [all without ذَائِرٌ :] and in a similar sense ذَائِرٌ is applied to a man. (S, * TA.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_801a77010f6f47a8', 'lane_lexicon', 're_lane_ebd4a63ba2d9718b', 'sec_lane_adcf4c4c5ec8c425', 'ذار', 'e4.raw', 14, 2, 'definition', 'en', 'ذَئِرٌ ذ : see ذَائِرٌ , in two places. -b2- إِنَّ شُؤُونَكَ لَذَئِرَةٌ (S, K *) Verily thy tears are accompanied by a breathing, or sighing, ( تَنَفُّس ,) like that of the angry. (K.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_566f63fd0cda0af6', 'lane_lexicon', 're_lane_ec411e38e4a8409f', 'sec_lane_22ec68ccde85e18a', 'ذول', 'e2.raw', 12, 2, 'definition', 'en', 'ذَالٌ ذ A certain letter of the alphabet, (Lth, ISd, K,) [ ذ ,] pronounced with the voice, [not with the breath only,] and always a radical, not a substitute for another letter, nor augmentative; (ISd, TA;) its place of utterance is at the roots of the teeth, near the place of utterance of ت [or ث ]; and it may be masc. and fem.; (B, TA;) [but generally it is fem.; and therefore] the dim. is : (K:) the pl. is أَذْوَالٌ and ذَالَاتٌ . (TA.) -A2- Also The comb of a cock. (Kh, TA.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5c1afbed176e50fa', 'lane_lexicon', 're_lane_ec411e38e4a8409f', 'sec_lane_cd5c8c52d9554b36', 'ذول', 'e4.raw', 14, 2, 'definition', 'en', 'ذُوَيْلَةٌ ذ : see ذَالٌ , above.', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6f5201df976d87d4', 'lane_lexicon', 're_lane_ec411e38e4a8409f', 'sec_lane_803d4bbbbc7a58d5', 'ذول', 'e1.raw', 11, 2, 'definition', 'en', '2 ذَوَّلْتُ ذَالًا ذ I wrote a ذ ; (Az, Sgh, K;) or ذَالًا حَسَنَةٌ [ a beautiful ذ ]. (B, TA.) [See also 2 in art. ذيل .]', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bcf02cb4ce810c60', 'lane_lexicon', 're_lane_ec411e38e4a8409f', 'sec_lane_bf08f32b2d80db85', 'ذول', 'e3.raw', 13, 2, 'definition', 'en', 'ذَوِيلٌ ذ , explained by IDrd as signifying What is dry, of plants &c., and so in the K, is said by ISd to be correctly دَوِيلٌ [q. v.]. (TA.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f8955b31eb0d678e', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_0cf2b1e9a14ccf22', 'ذرح', 'e16.raw', 26, 2, 'definition', 'en', 'ذُرْنُوحٌ ذ and ذَرْنُوحٌ and ذُرْنُوحَةٌ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7e49ed4402d02059', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_12fce62f40e10363', 'ذرح', 'e11.raw', 21, 2, 'definition', 'en', 'ذُرَّحٌ ذ : see what next follows.', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0956e65c93a6a8f0', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_15ccf559bfb4bd26', 'ذرح', 'e15.raw', 25, 2, 'definition', 'en', 'ذِرِّيحٌ ذ and ذِرِّيحَةٌ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3474ca01f7f32c4a', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_1bcad7a8279cd6a6', 'ذرح', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرَحَ الطَّعَامَ ذ : see 2. -A2- ذَرَحَ الشَّىْءَ فِى الرِّيحِ He winnowed the thing; syn. ذَرَّاهُ . (Kr, K.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6c94fb2e872d95e1', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_27f3a9fb22fb90f5', 'ذرح', 'e21.raw', 31, 2, 'definition', 'en', 'طَعَامٌ مَذْرُوحٌ ذ Food into which cantharides ( ذَرَارِيح ) have been put. (TA.)', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_206cd1de4a729ac3', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_2eeb2225fefccff6', 'ذرح', 'e19.raw', 29, 2, 'definition', 'en', 'ذُرَيْرِحٌ ذ dim. of ذُرَحْرَحٌ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e80a9219a73a5496', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_42c844091327ccbf', 'ذرح', 'e6.raw', 16, 2, 'definition', 'en', 'ذُرَاحٌ ذ and أِبُو ذُرَاحٍ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b818591e4fced646', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_4558128d83dd3580', 'ذرح', 'e8.raw', 18, 2, 'definition', 'en', 'ذَرِيحٌ ذ [a coll. gen. n.] i. q. هِضَابٌ [i. e. Hills; or mountains spreading over the surface of the ground; &c.]: n. un. with ة . (S, K.)', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f9d019d23dc8babf', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_4993047da4279493', 'ذرح', 'e2.raw', 12, 2, 'definition', 'en', '2 ذرّح الطَّعَامَ ذ , (S, K,) inf. n. تَذْرِيحٌ ; (S;) and , aor. ذَرِحَ ; (K;) He put ذَرَارِيح [or cantharides ] into the food. (S, K.) -b2- ذرّحه فِى المَآءِ , inf. n. as above, He put a small quantity of it, namely, saffron, &c., into the water. (S.) -b3- And ذرّح , [or ذرّح لَبَنَهُ , (see ذَرَاحٌ , below,)] He poured water into his milk, in order that it might become much in quantity. (TA.) -b4- تَذْرِيحٌ also signifies The smearing with clay a new [water-vessel of skin such as is called] إِدَاوَاة , in order that its odour may become good. (AA, K. *)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a3d7ae6e9be313ca', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_539c30385e8c0d73', 'ذرح', 'e4.raw', 14, 2, 'definition', 'en', 'ذُرَحٌ ذ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a3f553a8495feb48', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_ce75ac9ba931482d', 'ذرح', 'e18.raw', 28, 2, 'definition', 'en', 'ذُرَحْرَحٌ ذ and ذُرُحْرُحٌ and ذرّحرح and أَبُو ذرحرحٍ and أَبُو ذرحرحةَ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_76df70b3e0c82158', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_db75ea77fe49f42f', 'ذرح', 'e3.raw', 13, 2, 'definition', 'en', 'ذَرَحٌ ذ A certain tree, of which camels'' saddles are made. (K, TA.) [Forskål mentions, in his “ Flora Aeg. Ar., ” p. xcvi. a fabrile wood of an uncertain kind, of which spears, or lances, are made, called درح (thus with the unpointed د ), brought from the region of San''à.]', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cc482b2a73469329', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_f055b59a4eda80a4', 'ذرح', 'e9.raw', 19, 2, 'definition', 'en', 'ذَرِيحَةٌ ذ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b242a9798e49d500', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_6ef6c87650ceec71', 'ذرح', 'e5.raw', 15, 2, 'definition', 'en', 'ذَرَاحٌ ذ , applied to milk, i. q. صَيَاحٌ , (AA, K,) i. e. Mixed with water; as also : (TA:) or the latter, milk, and honey, mixed with a larger quantity of water. (K.)', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b6c7214b8ad462a7', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_80185b314bf22825', 'ذرح', 'e7.raw', 17, 2, 'definition', 'en', 'ذَرُوحٌ ذ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2b26b259b36b1a6d', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_81ce06e2622ade9e', 'ذرح', 'e13.raw', 23, 2, 'definition', 'en', 'ذُرَّاحٌ ذ and , (S, A, K,) the latter (respecting which see below) anomalous in form, (TA,) and , (K,) agreeably with analogy, (TA,) and (K) and (Fr) and and (K) and (IO) and (K) and and (ISd) and and (K) and , accord. to some, (TA,) and ذَرَارِحُ ذ and ذَرُّوحٌ and ذُرُّوحٌ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2848109950ddbe91', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_918f83ef231777ed', 'ذرح', 'e12.raw', 22, 2, 'definition', 'en', 'ذَرَّاحٌ ذ : see what next follows.', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1948f4b36a09a9f5', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_9207c8311c774106', 'ذرح', 'e17.raw', 27, 2, 'definition', 'en', 'أَبُو ذَرْيَاحٍ ذ : see ذُرَّاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_348082e85c4e761a', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_9f5a18c8955ea57b', 'ذرح', 'e10.raw', 20, 2, 'definition', 'en', 'أَحْمَرُ ذَرِيحِىٌّ ذ Intensely red; (S, A;) i. e. (TA) i. q. أُرْجُوَانٌ . (K, TA.) -A2- إِبِلٌ ذَرِيحِيَّاتٌ A certain race of camels, so called in relation to a stallion named ذَرِيحٌ . (S, K. *)', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eecaac9aea18f94b', 'lane_lexicon', 're_lane_edc841cae859341c', 'sec_lane_9fe3f24005b848fe', 'ذرح', 'e20.raw', 30, 2, 'definition', 'en', 'مُذَّرَحٌ ذ : see ذَرَاحٌ .', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5e93a0919af4631d', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_01ad35347320d559', 'ذال', 'e2.raw', 12, 2, 'definition', 'en', '6 تذآءل ذ He became vile, base, ignominious, abject, or contemptible; syn. تصاغر . (K.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4b3f4b96dca5740d', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_06c79a0c12835059', 'ذال', 'e5.raw', 15, 2, 'definition', 'en', 'ذَأَلَانٌ ذ The walk, or manner of going, of the wolf: pl. ذَآلِيلُ , with ل : (M, K:) [but ISd says,] I know not how this is. (M. [See also دَآلِيلُ .]) Also [as an inf. n. of 1, q. v.,] A quick walk or manner of going: (M:) or, as some say, a moderate running: or an extraordinary manner, or rate, of going, by reason of briskness, liveliness, or sprightliness. (T.) -A2- See also ذَأْلَانٌ .', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c40a72f72b27f48e', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_475505ff5fd48437', 'ذال', 'e8.raw', 18, 2, 'definition', 'en', 'مِذْأَلٌ ذ Light and quick. (Ibn-''Abbád, TA.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_701f163816cd66ef', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_571fd6ed725d54c6', 'ذال', 'e3.raw', 13, 2, 'definition', 'en', 'ذَأْلَانٌ ذ , (K,) or , (ISk, S, M,) and , (Ibn- ''Abbád, K,) The jackal ( اِبْنُ آوَى ): or the wolf: (K:) or the second word has the latter signification: (ISk, S, M:) and the last word, the former signification: (M:) the pl. of the second word, having the latter signification, is ذَآلِيلُ , with ل . (ISk, S.) [See also دَأْلَانٌ and دَأَلَانٌ : and see ذُؤَالَةٌ , below.]', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5645b30fd1896792', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_cff0b26f473906c0', 'ذال', 'e4.raw', 14, 2, 'definition', 'en', 'ذُوْلَانٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5b6182dd83dcabd1', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_d667b24e4de5311a', 'ذال', 'e6.raw', 16, 2, 'definition', 'en', 'ذَؤُولٌ ذ Anything [or any animal] Quick, or swift. (T.) [See also دَؤُولٌ .]', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_457315f37553c730', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_bf36516622ce3588', 'ذال', 'e7.raw', 17, 2, 'definition', 'en', 'ذُؤَالَةُ ذ The wolf: (T, S, M, K:) so called because of his light walk or manner of going; (A ''Obeyd, T, S;) or because of a lightness in his running: (M:) it is determinate, (S, M, K, TA,) and imperfectly decl., being a proper name and [grammatically] of the fem. gender: (TA:) pl. ذِئْلَانٌ and ذُؤْلَانٌ . (M, K.) One says, خَشِّ ذُؤَالَةَ بَالحِبَالَةِ [ Frighten thou the wolf with the snare ]: (S, Meyd, TA:) a prov., applied to him whose threatening is not regarded: meaning threaten thou other than me; for I know thee: (Meyd, TA:) or, accord. to A''Obeyd, said by him who orders one to menace and threaten. (Meyd.) [See also ذَأْلَانٌ .]', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_49677140a9edfe26', 'lane_lexicon', 're_lane_f1075ae7f446e25e', 'sec_lane_c4f03b28bdf5818c', 'ذال', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَأَلَ ذ , (T, K,) or ذَأَلَتْ , (S,) aor. ذَأََ , inf. n. ذَأَلَانٌ (T, S, K) and ذَأْلٌ or ذَأَلٌ , (accord. to different copies of the S and K, the latter accord. to the TA,) He, (T, K,) or she, i. e. a camel, (S,) walked, or went, lightly: (AZ, T, S:) or quickly: (K:) or lightly, (K,) or quickly, (IF,) and proudly, with an inclining of the body from side to side. (IF, K.) [See also دَأَلَ : and see ذَأَلَانٌ , below.]', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8a9249280f376c4b', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_05dd46a52f9e31b2', 'ذرا', 'e10.raw', 20, 2, 'definition', 'en', 'أَذْرَأُ ذ ; fem. ذَرْآءُ : see 1, last sentence. Applied to a ram, Having whiteness in the head; (M, K;) and so the fem. applied to a ewe: (M:) or having the ears variegated, or speckled, with black and white, and the rest black: (K:) or it has this latter meaning when applied to a horse, and to a kid; and so the fem. applied to a female kid, (S, O,) or to a she-goat: (M:) and is not applied to the sheep-kind. (S, O.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_81ccca8970da1ba4', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_26f2b32fe4e5f502', 'ذرا', 'e6.raw', 16, 2, 'definition', 'en', 'ذَرْآنِىٌّ ذ and ذَرَآنِىٌّ Intensely white salt: (S, M, K:) derived from ذُرْأَةٌ : one should not say أَنْذَرَانِىٌّ ; (S, K;) for this is a vulgarism: some pronounce it with the unpointed د . (TA.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ba91cd42fd27ce51', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_2d2ee4a7551afbe8', 'ذرا', 'e5.raw', 15, 2, 'definition', 'en', 'ذُرْأَةٌ ذ (S, M, K) and , (S,) the latter an inf. n. (M, [see 1,]) the former a simple subst., (S,) Whiteness, or hoariness, in the fore part of the head: (S:) or whiteness intermixed with blackness in the hair of the head: (M:) or whiteness, or hoariness, of the hair: (K:) or the beginning of whiteness or hoariness (M, K) in the fore part of the head, (K,) or in the upper part of each side of the head. (A, TA.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bed8cebf407607f1', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_324e54ed16012fe7', 'ذرا', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرَأَ ذ , (T, S, M, &c.,) aor. ذَرَاَ , (S, M, Msb, K,) inf. n. ذَرْءٌ , (S, M, Msb,) He (God) created, syn. خَلَقَ , (T, S, M, Msb, K,) الخَلْقَ [ the creation; i. e. the things that are created ]. (T, S, M, Msb.) وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ ٱلْجِنِّ وَ ٱلْإِنْسِ , in the Kur [vii. 178], means [ And verily ] we have created [ for Hell many of the jinn, or genii, and of mankind ]. (T.) -b2- He multiplied, or made numerous. (K.) يَذْرَؤُكُمْ فِيهِ , in the Kur [xlii. 9], means He multiplieth you thereby; i. e., by making of you, and of the cattle, pairs, males and females: so says Zj; and Fr says the like; and this is a correct explanation. (T.) -b3- Also, (S, M, K,) and so ذَرَا , (TA,) He sowed land: (S, M, K, TA:) but the latter verb is said to be the more chaste. (MF.) -A2- ذَرَأَ فُوهُ His teeth fell out from his mouth; (K, TA;) as also ذَرَا and ذَرَى , without ء : (TA:) but the most chaste is said to be without ء : ذَرَأَ , with ء , is said to be of weak authority, or a mispronunciation. (MF.) 4 اذرأهُ ذ He angered him; provoked him to anger. (T, M, K.) -b2- اذرأهُ بِصَاحِبِهِ He incited him against his companion. (AZ, T.) And اذرأهُ بِالشَّىْءِ He incited him, or urged him, to do, or attempt, the thing. (M, K.) And اذرأهُ إِلَىكَذَا He constrained him, or compelled him, to have recourse to, or to do, such a thing. (K, * TA.) A ''Obeyd mentions أَذْرَى , without ء ; but ''Alee Ibn-Hamzeh asserts that this is incorrect. (M.) -b3- اذرأ الدَّمْعَ He, or it, made tears to flow. (K, * TA.) -b4- And اذرأه He frightened him. (M, K.) -A2- أَذْرَأَتْ She (a camel) excerned ( أَنْزَلَتْ ) the milk (M, K, TA) from [app. a mistake for into ] her udder: a dial. var. of أَدْرَأَتْ [q. v.]. (TA.) The epithet applied to the she-camel so doing is . (M, K.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f4d9c281b4236981', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_36466c48acbd1b0d', 'ذرا', 'e8.raw', 18, 2, 'definition', 'en', 'ذُرِّيَّةٌ ذ (T, S, M, Mgh, K) and ذِرِّيَّةٌ (M, K) and ذَرِّيَّةٌ , (K,) [or ذَرِيَّةٌ , without a sheddeh to the ر , accord. to the Msb in art. ذر ,] always pronounced by the Arabs without ء : (S:) accord. to some, (TA,) from الذَّرْءُ ; (M, TA;) so says Th; (M;) the measure of the first being فُعُّولَةٌ or فُعِّيلَةٌ ; [so that it is originally ذُرُّوءَةٌ or ذُرِّيْئَةٌ ;] (TA;) but the ء is suppressed because of frequency of usage: (M:) accord. to others, from الذَّرُّ , signifying “ the act of scattering; ” because God scattered the ذرّيّة upon the earth; and the measure is فُعْلِيَّةٌ or فُعُّولَةٌ , [if the latter,] the word being originally ذُرُّورَةٌ , the last ر being changed into ى , in a manner similar to the case of تَقَضَّتِ العُقَابِ [in which تَقَضَّضَت becomes تَقَضَّيَت and then تَقَضَّت ; so that ذُرُّورَةٌ becomes ذُرُّويَةٌ and then ذُرِّيَّةٌ ]: (TA:) Children, or offspring, (T, S, Mgh, K,) of a man, and used as a sing. also, (Mgh,) or of men and of jinn, or genii: (S, K:) pl. [ ذُرِّيَّاتٌ (see art. الذَّارِئُ ذ an epithet applied to God, The Creator. (T.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_13019cc49b1abd17', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_ed17cffab5525d71', 'ذرا', 'e3.raw', 13, 2, 'definition', 'en', 'ذَرْءٌ ذ The act of creating; inf. n. of ذَرَأَ . (S, M, Msb.) -b2- [And used in the sense of the pass. part. n. of that verb; and alike as sing. and pl. because originally an inf. n.] ذَرْءُ النَّارِ , (S, K, TA,) [for ذَرْءٌ لِلنَّارِ ,] related as occurring in a trad. (S, TA) of ''Omar, (TA,) means Created [i. e. destined ] for the fire [ of Hell ]: (S, K, TA:) but as some relate it, the phrase is ذَرْوُ النَّارِ , meaning [either “ the children of the fire, ” agreeably with what next follows, or] “ to be scattered in the fire. ” (S, TA.) -b3- Also The number of [ones] offspring: one says, أَنْمَىٱللّٰهُ ذَرْأَكَ May God increase [ the number of ] thine offspring; as also ذَرْوَكَ . (T.) -A2- Somewhat; (M, K;) as in the saying, بَلَغَنِى ذَرْءٌ مِنْ خَبَرٍ [ Somewhat of news, or information, reached me, or came to my knowledge ]: (K, TA:) or ذَرْءٌ مِنْ خَيْرٍ [ somewhat of good ]: (so in some copies of the K and M:) thus ذرء is written by IAth: in some copies of the K, ذُرْءٌ , with damm: (TA:) or ذَرْءٌ here means a little; and ذَرْوٌ is a dial. var. thereof. (M in art. ذَرَأٌ ذ : see what next follows.', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_35763c55d71ce45f', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_ee3e895e9d807abd', 'ذرا', 'e11.raw', 21, 2, 'definition', 'en', 'مُذْرِئٌ ذ : see 4, last sentence.', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b0a803ca553cad48', 'lane_lexicon', 're_lane_f39fc8b06d51ed7f', 'sec_lane_a75c38175be1d06a', 'ذرا', 'e7.raw', 17, 2, 'definition', 'en', 'ذَرِىْءٌ ذ Sown seed. (S, M, K.)', 'derived_from_raw_tei', 958);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fb92392f814544be', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_099b1f7ce9c4c847', 'ذرف', 'e3.raw', 13, 2, 'definition', 'en', '10 استذرفهُ ذ He desired its (a thing''s) dripping, or flowing. (M.) -b2- And استذرف الضَّرْعُ The udder invited one to milk it; and to desire its dripping, or flowing [with milk]. (M.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f4c39111a2503fe9', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_1f017e75f595fd2d', 'ذرف', 'e5.raw', 15, 2, 'definition', 'en', 'ذَرَفَانٌ ذ [app. in the following sense, as well as in others mentioned above, (see 1,) an inf. n., of which the verb is ذَرَفَ ,] A weak gait or manner of going. (S, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eff17b7c2c11c066', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_1f0a0bd5adebdde1', 'ذرف', 'e4.raw', 14, 2, 'definition', 'en', 'ذَرْفٌ ذ [app. in the following sense, as well as in others mentioned above, (see 1,) an inf. n., of which the verb is ذَرَفَ ,] A certain running of horses, in which the legs are put together and [ then ] the fore legs stretched out with the toes near to the ground. (M.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_94e2a5b246fb5d44', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_358c2c37501e854d', 'ذرف', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرَفَ الدَّمْعُ ذ , (Lth, T, S, M, Msb, K,) aor. ذَرِفَ , inf. n. ذَرْفٌ (Lth, T, S, K) and ذُرُوفٌ (Lth, T, K) and ذَرَفَانٌ (S, K) and ذَرِيفٌ and تَذْرَافٌ , (K,) The tears flowed. (Lth, T, S, M, Msb, K.) And ذَرَفَتْ عَيْنُهُ , (S, Msb, K,) aor. ذَرِفَ , inf. n. ذَرْفٌ , (Msb,) His eye shed tears; (Msb;) tears flowed from his eye. (S, K.) And ذَرَفَتْ عَيْنُهُ دَمْعَهَا , (Lth, T,) or ذَرَفَتِ العَيْنُ دَمْعَهَا (K) or الدَّمْعَ , (M, Msb,) aor. ذَرِفَ , (M,) inf. n. ذَرْفٌ and ذَرَفٌ and ذَرَفَانٌ (Lth, T, M) and ذُرُوفٌ and ذَرِيفٌ and تَذْرَافٌ , and [ISd says,] I think that Lh has mentioned as an inf. n. ذُرَافٌ , but I am not certain of it, (M,) His eye poured forth its tears: (Lth, T:) or the eye made its tears, or the tears, to flow: (M, K:) or let fall tears, or the tears: and , inf. n. تَذْرِيفٌ signifies the same: (M:) [or the latter has a 2 ذَرَّفَ see above, in two places. -A2- ذرّف عَلَيْهِ , (T, S, M, K,) inf. n. تَذْرِيفٌ , (S,) He exceeded it; (T, S, M, K;) namely, a hundred [years], (S, K,) or sixty, (T,) or fifty, or some other number. (M.) -b2- ذرّف فِى حَدِيثِهِ He added, or exaggerated, in his discourse, or narration; as also زلّف . (IDrd and O in art. زلف .) -A3- ذرّفهُ الشَّىْءَ He made him to know the thing: a poet says, لَأُذَرِّفَنْكَ المَوْتَ إِنْ لَمْ تَهْرُبِ i. e. I will assuredly make thee to know death [ if thou flee not ]: (IAar, M:) or ذرّفهُ المَوْتَ signifies he made him to be at the point of death. (T, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_958441cc1a9be9ad', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_372d6bb94b6e246e', 'ذرف', 'e6.raw', 16, 2, 'definition', 'en', 'دَمْعٌ ذَرِيفٌ ذ and Tears shed, or made to flow. (T, M, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d29f2ba272eb5321', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_ceed6f8d6649c4e2', 'ذرف', 'e7.raw', 17, 2, 'definition', 'en', 'ذَرَّافٌ ذ [accord. to Freytag, Largely flowing: but he does not name any authority.] -b2- Quick, or swift; and so زَرَّافٌ . (M.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bb2a6381956f7fc2', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_8d424e28a6aef450', 'ذرف', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَرَفَ الدَّمْعُ ذ , (Lth, T, S, M, Msb, K,) aor. ذَرِفَ , inf. n. ذَرْفٌ (Lth, T, S, K) and ذُرُوفٌ (Lth, T, K) and ذَرَفَانٌ (S, K) and ذَرِيفٌ and تَذْرَافٌ , (K,) The tears flowed. (Lth, T, S, M, Msb, K.) And ذَرَفَتْ عَيْنُهُ , (S, Msb, K,) aor. ذَرِفَ , inf. n. ذَرْفٌ , (Msb,) His eye shed tears; (Msb;) tears flowed from his eye. (S, K.) And ذَرَفَتْ عَيْنُهُ دَمْعَهَا , (Lth, T,) or ذَرَفَتِ العَيْنُ دَمْعَهَا (K) or الدَّمْعَ , (M, Msb,) aor. ذَرِفَ , (M,) inf. n. ذَرْفٌ and ذَرَفٌ and ذَرَفَانٌ (Lth, T, M) and ذُرُوفٌ and ذَرِيفٌ and تَذْرَافٌ , and [ISd says,] I think that Lh has mentioned as an inf. n. ذُرَافٌ , but I am not certain of it, (M,) His eye poured forth its tears: (Lth, T:) or the eye made its tears, or the tears, to flow: (M, K:) or let fall tears, or the tears: and , inf. n. تَذْرِيفٌ signifies the same: (M:) [or the latter has a 2 ذَرَّفَ see above, in two places. -A2- ذرّف عَلَيْهِ , (T, S, M, K,) inf. n. تَذْرِيفٌ , (S,) He exceeded it; (T, S, M, K;) namely, a hundred [years], (S, K,) or sixty, (T,) or fifty, or some other number. (M.) -b2- ذرّف فِى حَدِيثِهِ He added, or exaggerated, in his discourse, or narration; as also زلّف . (IDrd and O in art. زلف .) -A3- ذرّفهُ الشَّىْءَ He made him to know the thing: a poet says, لَأُذَرِّفَنْكَ المَوْتَ إِنْ لَمْ تَهْرُبِ i. e. I will assuredly make thee to know death [ if thou flee not ]: (IAar, M:) or ذرّفهُ المَوْتَ signifies he made him to be at the point of death. (T, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cb9685d00a70cd45', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_8eb23a0961f4cca8', 'ذرف', 'e10.raw', 20, 2, 'definition', 'en', 'مَذْرُوفٌ ذ : see ذَرِيفٌ .', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_56dd84a75af8cfcd', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_af2f3e5d6761c471', 'ذرف', 'e8.raw', 18, 2, 'definition', 'en', 'ذَوَارِفُ ذ , applied to tears ( ذُمُوعٌ ), Flowing. (T.) [And] Running waters. (KL.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ae14a9f3cb83aa8a', 'lane_lexicon', 're_lane_fa00183dc11d6e3f', 'sec_lane_c728f581b68ab087', 'ذرف', 'e9.raw', 19, 2, 'definition', 'en', 'مَذَارِفٌ ذ i. q. مَدَامِعٌ [The channels of the tears; &c.: see مَدْمَعٌ ]. (T, S, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_827061917b26932b', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_01a6b6cfebeb31c9', 'ذالي', 'e5.raw', 15, 2, 'definition', 'en', 'ذَلَوْلًى ذ , [in copies of the K ذَلَولَى ,] applied to a man, i. q. مُذْلَوْلٍ [part. n. of 12, q. v.]: (K, TA: [in some copies of the K مَذْلُولٌ :]) of the measure فَعَوْعَلٌ ; or, as some say, فَعَلْعَلٌ . (TA.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8e85ffcaea077304', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_075a2f8f269fc948', 'ذالي', 'e4.raw', 14, 2, 'definition', 'en', '12 اِذْلَوْلَى ذ , (T, S, M, K,) inf. n. اِذْلِيلَآءٌ , (S,) He went away hiding himself; stole away secretly. (T, S, M, K.) -b2- He hastened, made haste, sped, or went quickly; (TA;) [like ادلولى ;] and (TA) he did so in fear lest a thing should escape him. (T, TA.) And اذلولى فَذَهَبَ He went back, or away, running quickly. (T.) -b3- He was, or became, easy, tractable, submissive, or manageable. (M, K.) [See also 5.] -b4- He (a man) was, or became, broken-hearted. (T, K.) -b5- It (the ذَكَر ) stood in a lax state. (T, K.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8f4b8fbd4e36380b', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_e9711c005fbd56db', 'ذالي', 'e3.raw', 13, 2, 'definition', 'en', '5 تذلّى ذ i. q. تذلّل [ He became lowly, humble, or submissive; or he lowered, humbled, or submitted, himself ]: (T, K:) the latter verb is the original: the former being like تظنّى , originally تظنّن . (T.) [See also the next paragraph.]', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_25fcf47d9f7e2f9b', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_fe5d053c686f0e6b', 'ذالي', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَلَىالرُّطَبَ ذ , like سَعَى , (K,) [i. e.,] aor. ذَاَلَ , inf. n. ذَلْىٌ , (TA,) He gathered the fresh ripe dates: (K:) so in the copies of the K; in which is added, فَٱنْذَلَى مَعَهُ : but what we find in the Tekmileh is this: ظلّ يذلى الرطب اى يجنيه فينذلى معه : and يذلى is written as [the aor. of] a quadriliteral [i. e. as the aor. of اذلى , for it is without a sheddeh]: (TA:) [here, however, فينذلى is evidently, in my opinion, a mistranscription for فَيَتَدَلَّى ; and the right reading and rendering I therefore hold to be as follows: ظَلَّ الرُّطَبَ , or perhaps يَذْلَى , means He continued gathering the fresh ripe dates, they hanging down with him: for the gatherer laying hold upon the raceme, it hangs down with his weight. In the TK, this passage in the TA has been misunderstood and misrepresented, as though it meant that أَذْلَى مَعَهُ signifies “ he gathered with him. ”]', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_239a3fc7d0cbcfe1', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_9966eba8ad82fc63', 'ذالي', 'e6.raw', 16, 2, 'definition', 'en', 'رِشَآءٌ مُذْلَوْلٍ ذ [ A well-rope ] unsteady; or moving about, or to and fro, or from side to side. (T.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_27010427705c9795', 'lane_lexicon', 're_lane_fb42c1fce2d40b24', 'sec_lane_bb9db7cdb8e4941c', 'ذالي', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَلَىالرُّطَبَ ذ , like سَعَى , (K,) [i. e.,] aor. ذَاَلَ , inf. n. ذَلْىٌ , (TA,) He gathered the fresh ripe dates: (K:) so in the copies of the K; in which is added, فَٱنْذَلَى مَعَهُ : but what we find in the Tekmileh is this: ظلّ يذلى الرطب اى يجنيه فينذلى معه : and يذلى is written as [the aor. of] a quadriliteral [i. e. as the aor. of اذلى , for it is without a sheddeh]: (TA:) [here, however, فينذلى is evidently, in my opinion, a mistranscription for فَيَتَدَلَّى ; and the right reading and rendering I therefore hold to be as follows: ظَلَّ الرُّطَبَ , or perhaps يَذْلَى , means He continued gathering the fresh ripe dates, they hanging down with him: for the gatherer laying hold upon the raceme, it hangs down with his weight. In the TK, this passage in the TA has been misunderstood and misrepresented, as though it meant that أَذْلَى مَعَهُ signifies “ he gathered with him. ”]', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_da9384191dbfd16e', 'lane_lexicon', 're_lane_02d19dccba448cfd', 'sec_lane_3944a66719fe4ca9', 'فريج', 'e1.raw', 11, 2, 'definition', 'en', 'Q. 3 اِفْرَنْبَجَ ذ , said of a lamb, (Lth, O,) or of the skin of a lamb, (S, K, [some of the copies of the latter of which have الجَمَل in the place of الحَمَل ,]) and of the skin of a kid, (O,) It was roasted so that the upper parts of it became dried up. (Lth, S, O, K.)', 'derived_from_raw_tei', 2358);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2f5a4c9933010ef0', 'lane_lexicon', 're_lane_02d19dccba448cfd', 'sec_lane_7f7a04a0e278a5e4', 'فريج', 'e2.raw', 12, 2, 'definition', 'en', 'مُفْرَنْبِجٌ ذ [part. n. of the verb above]. A man said, describing a roasted female kid, فَأَكَلْتُ مِنْ مُفْرَنْبِجٍ مِنْ جِلْدِهَا [ And I ate of such as was roasted so that the upper parts were dried up, of its skin ]. (O.)', 'derived_from_raw_tei', 2358);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4cfc1c53346751a1', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_160007f045bfd887', 'ذاب', 'e8.raw', 18, 2, 'definition', 'en', 'ذِئْبٌ ذ , also pronounced ذِيبٌ , without ء , (S, Msb, K,) originally with ء , (T, S,) The wolf, wild dog, or dog of the desert; كَلْبُ البَرِّ : (M, A, K:) applied to the male and the female; (Msb;) and sometimes, also, (Msb,) the female is called ذِئْبَةٌ : (S, M, Msb, K:) pl. (of pauc., S, Msb) أَذْؤُبٌ , and (of mult., S, Msb) ذِئَابٌ , (S, M, Msb, K,) which may also be pronounced ذِيَابٌ , with ى , because of the kesreh, (Msb,) and ذُؤبَانٌ (S, M, Msb, K) and ذِئْبَانٌ . (TA.) -b2- You say, الذِّئْبُ يُكَنَّى أَبَا جَعْدَةَ [ The wolf is surnamed Aboo-Jaadeh ]: i. e. its surname is good, but its actions are foul. (TA. [See art. جعد ; and see also Freytag''s Arab. Prov., i. 449.]) -b3- And الذِّئْبُ يَأْذُو الغَزَالَ [ The wolf lies in wait for the young gazelle ]: a prov. alluding to perfidy. (TA.) -b4- And هُوَ ذِئْبٌ فِى ثَلَّةٍ (tropical:) [ He is a wolf among a flock of sheep ]. (A.) -b5- And ذِئْبَةُ مِعْزًى وَظَلِيمٌ فِى الخُبْرِ [ A she-wolf among the goats, and a heostrich when tried ]: ذِئْبَةٌ ذ fem. of ذِئْبٌ . (S, M, Msb, K.) -b2- Also (assumed tropical:) The [ angular ] intervening space between the دَفَّتَانِ [or two boards ] of the [ kinds of saddle called ] سَرْج and رَحْل (S, K, TA) and غَبِيط , (TA,) beneath the place of juncture of the two curved pieces of wood; (S;) [or] what is beneath the fore part of the place of juncture of the two curved pieces of wood (M, K) of the [ kinds of saddle called ] رَحْل and قَتَب and إِكَاف and the like; (M;) which falls, or lies, upon, (S,) or bites, or compresses, (M, K,) the part called the مَنْسِج (S, M, K) of the beast. (M, K.) A poet says, وَقَتَبٌ ذِئْبَتُهُ كَٱلْمِنْجَلِ [ And a قتب of which the ذئبة is like the reapinghook ]. (M.) [See قَرَبُوسٌ .] Accord. to IAar, the [a coll. gen. n. of which ذِئْبَةٌ ذِئْبَانٌ ذ a pl. of ذِئبٌ . (TA.) -A2- Also, accord. to AA, (S,) The hair upon the neck and lip of the camel: (S, K;) and accord. to Fr, who says that it is a sing. [in this sense], (S,) the remains of the [ fur, or soft hair, called ] وَبَر [ after the greater part has fallen off or been shorn ]. (S, K. [See also ذُوبَانٌ in art. ذوبْ , and ذِيبَانٌ in art. ذيب .])', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5940d21d0856dabd', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_4365072dde547918', 'ذاب', 'e6.raw', 16, 2, 'definition', 'en', '10 استذأب النَّقَدُ ذ The نقد [or ugly sheep ] became like wolves: a prov., applied to low, mean, or ignominious, persons, when they obtain ascendancy. (T, K.)', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_77e52b0494faaffe', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_538ffa9510736885', 'ذاب', 'e7.raw', 17, 2, 'definition', 'en', 'غَرْبٌ ذَأْبٌ ذ (assumed tropical:) A large bucket with which one goes to and fro; thought by As to be from تَذَاؤُبُ الرِّيحِ : (M:) or in much [or quick ] motion, ascending and descending. (M, K.)', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1f8def7fa06cc61a', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_5870010d98011850', 'ذاب', 'e2.raw', 12, 2, 'definition', 'en', '1 ذُئِبَ ذ He (a man, M) was frightened by the wolf; (M, K;) as also ذَئِبَ , aor. ذَأََ ; and ذَؤُبَ , aor. ذَأَُ : (K:) or he (a man) was assailed, fallen upon, come upon, or overtaken, by the wolf. (Ibn-Buzurj, T.) And [hence, in the opinion of ISd, as he says in the M,] (tropical:) He was frightened by anything; (M, K;) and so , (AA, T, S, M, K,) inf. n. إِذْآبٌ ; (TA;) said of a man. (S.) [Hence also,] ذَأَبَهُ , (M, K,) aor. ذَأََ , (K,) [inf. n. ذَأْبٌ ,] (tropical:) He frightened him [ like as does a wolf ]: (M, A, K, TA:) and ذَأَبَتْهُ الجِنُّ (A, TA) and , as also تذعّبتهُ , (T, TA,) (tropical:) The jinn, or genii, frightened him. (T, A, TA.) [And hence, app.,] ذَأَبْتُهُ الرِّيحُ (tropical:) The wind came to him from every side, like the wolf; when guarded against from one direction, coming from another direction: (A:) and 2 ذَأََّ see 1, last sentence but one. -A2- ذأّب الرَّحْلَ , (inf. n. تَذْئِيبٌ , K,) He made, to the رحل [or camel''s saddle ], what is termed a ذِئْبَة , (M, K,) or ذِئْب . (TA.) [See also مُذَأَّبٌ .]', 'derived_from_raw_tei', 948);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e4f7c56fd5051e07', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_59b221cc51cbb076', 'ذاب', 'e11.raw', 21, 2, 'definition', 'en', 'ذُؤَابٌ ذ : see the next paragraph.', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_19994e386ef121e9', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_f2fc32141333883f', 'ذاب', 'e15.raw', 25, 2, 'definition', 'en', 'مَذْؤُوبٌ ذ A man frightened by wolves: (A, TA:) or whose sheep, or goats, have been fallen upon by the wolf. (S, M, A, K.) -b2- [And hence,] (tropical:) Frightened [ as though by a wolf ]. (T, TA.) -A2- Also A horse, (Mgh,) or such as is called بِرْذَوْنٌ , (Lth, T, M, K,) and, accord. to the Tekmileh, an ass, and so مَذْبُوبٌ , as though from ذِيبَةٌ for ذِئْبَةٌ , (Mgh,) Affected with the disease termed ذِئْبَةٌ . (Lth, T, M, Mgh, K.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f6e174861fcf9560', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_6c4b53125a7c8fad', 'ذاب', 'e5.raw', 15, 2, 'definition', 'en', '6 تذآءب لِلنّاقَةِ ذ (S, M, K) and لَهَا (M, K) (assumed tropical:) He disguised himself like a wolf to the she-camel, and, by so frightening her, made her to incline to, or affect, her young one: (S:) or he cloaked, or disguised, himself to the she-camel, making himself to seem like a wolf, in order to cause her to affect a young one that was not her own [ by moving her with pity by the supposed danger of the latter ]. (M, K) -b2- See also 1, in two places. -A2- تذآءب شَيْئًا and (assumed tropical:) He did a thing by turns; syn. تَدَاوَلَهُ : (M, K, TA: [in the CK, erroneously, تَناوَلَهُ :]) from الذِّئْبُ [the wolf], which, when guarded against from one direction, comes from another direction. (M, TA.)', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_39206b2c904b6139', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_6df354fa99635cf8', 'ذاب', 'e16.raw', 26, 2, 'definition', 'en', 'مُتَذَائِبٌ ذ (assumed tropical:) A man in a state of commotion, or fluctuation; from تَذَآءَبَتِ الرِّيحُ . (TA from a trad.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0b1ae301cc6e77ca', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_6ff91a4796b0fb0a', 'ذاب', 'e14.raw', 24, 2, 'definition', 'en', 'مُذَأَّبٌ ذ A boy having a ذُؤَابَة . (T, S, A, K.) -b2- And (assumed tropical:) A [camel''s saddle such as is called] غَبِيط [&c.] having [ a ذُؤَابَة , i. e.] a skin, or piece of skin, hung upon its آخِرَة [or hinder part ]: (S:) or having a ذِئْبَة [q. v.]. (TA.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1b8162c5868049ea', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_7de9b3cdbf06f4da', 'ذاب', 'e12.raw', 22, 2, 'definition', 'en', 'ذُؤَابَةٌ ذ (also pronounced ذُوَابَةٌ , T and K in art. ذوب ,) A portion [or lock ] of hair, (S, A,) hanging down loosely from the middle of the head to the back: (A:) or the hair of the fore part of the head; the hair over the forehead; syn. نَاصِيَةٌ ; (M, K;) so called because, hanging down, it moves to and fro, or from side to side: (M:) or the place whence that hair grows: (M, K:) or the hair that surrounds the دُوَّارَة [or round part ] of the head: (AZ, T:) or plaited hair of the head: and the part of the head which is the place thereof: (Lth, T:) or a plait of hair hanging down: if twisted, it is called عَقِيصَةٌ : (Msb:) and [a horse''s forelock; or] hair (M, K) of the head, (M,) in the upper part of the نَاصِيَة , of the horse: (M, K:) pl. (in all its senses, M, TA) ذَوَائِبُ , (T, S, M, Msb, K,) originally, (S, K,) or regularly, (T,) ذَآئِبُ , changed to render it more easy of pronunciation, (T, S, K,) and ذُؤَابَاتٌ also. (Msb.) Hence, فُتِلَ ذَوَائِبُهُ [ His pendent locks of hair were twisted; ] meaning (tropical:) he was made to abandon, or relinquish, his opinion or idea or أَرْضٌ مَذْأَبَةٌ ذ A land containing, (S,) or abounding with, (M, K,) wolves: (S, M, K:) in the dial. of some of the tribe of Keys, مَذَيْبَةٌ , agreeing with ذِيبٌ . (M.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_72305d0486388177', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_8271714f12267f74', 'ذاب', 'e1.raw', 11, 2, 'definition', 'en', '1 ذُئِبَ ذ He (a man, M) was frightened by the wolf; (M, K;) as also ذَئِبَ , aor. ذَأََ ; and ذَؤُبَ , aor. ذَأَُ : (K:) or he (a man) was assailed, fallen upon, come upon, or overtaken, by the wolf. (Ibn-Buzurj, T.) And [hence, in the opinion of ISd, as he says in the M,] (tropical:) He was frightened by anything; (M, K;) and so , (AA, T, S, M, K,) inf. n. إِذْآبٌ ; (TA;) said of a man. (S.) [Hence also,] ذَأَبَهُ , (M, K,) aor. ذَأََ , (K,) [inf. n. ذَأْبٌ ,] (tropical:) He frightened him [ like as does a wolf ]: (M, A, K, TA:) and ذَأَبَتْهُ الجِنُّ (A, TA) and , as also تذعّبتهُ , (T, TA,) (tropical:) The jinn, or genii, frightened him. (T, A, TA.) [And hence, app.,] ذَأَبْتُهُ الرِّيحُ (tropical:) The wind came to him from every side, like the wolf; when guarded against from one direction, coming from another direction: (A:) and 2 ذَأََّ see 1, last sentence but one. -A2- ذأّب الرَّحْلَ , (inf. n. تَذْئِيبٌ , K,) He made, to the رحل [or camel''s saddle ], what is termed a ذِئْبَة , (M, K,) or ذِئْب . (TA.) [See also مُذَأَّبٌ .]', 'derived_from_raw_tei', 948);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_04e4529e42bfc4fc', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_8749e1ff56582d2b', 'ذاب', 'e3.raw', 13, 2, 'definition', 'en', '4 أَذْأَبَتِ الأَرْضُ ذ (A, TA) The land abounded with wolves. (TA.) -b2- See also 1, in three places.', 'derived_from_raw_tei', 948);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e091ddb90f7de616', 'lane_lexicon', 're_lane_059d8a5b238e98fa', 'sec_lane_96920457dca6ee61', 'ذاب', 'e4.raw', 14, 2, 'definition', 'en', '4 أَذْأَبَتِ الأَرْضُ ذ (A, TA) The land abounded with wolves. (TA.) -b2- See also 1, in three places.', 'derived_from_raw_tei', 949);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cdb863ddf759023e', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_0a89ae90238adb5f', 'ذفر', 'e8.raw', 18, 2, 'definition', 'en', 'ذِفْرَى ذ , without tenween, (S, K,) because the alif [written ى ] is the characteristic of the fem. gender, (S,) and sometimes, (S, K,) more rarely, (Sb,) ذِفْرًى , with tenween, (S, K,) when indeterminate, (S,) the alif in this case being considered as making the word quasi-coordinate to دِرْهَمٌ (S, K,) The place that sweats, in the back of a camel''s neck, behind the ear: (Lth, S:) or, in a man, (M,) and in any animal, the part extending from the مَقَدّ [or part between the two ears, erroneously written in the CK مُقَدَّم ,] to the half of the قَذَال [or entire back of the head ]: or the prominent bone behind the ear: (M, K:) or a bone in the upper part of a man''s neck, on the right and left of the small hollow which is in the middle: (Sh:) or the ذِفْرَيَانِ [which is the dual] are the two protuberances on the right and left of the small hollow in the middle of the back of the neck: (M:) it is from ذَفَرُ العَرَقِ [“ the pungency of the odour of sweat ”], because it is the first part that sweats in a camel: (S:) pl. ذِفْرَيَاتٌ and ذَفَارَى , (S, K,) and some say ذَفَارٍ . (S.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cebe6de5a275f1a9', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_1637204689954586', 'ذفر', 'e11.raw', 21, 2, 'definition', 'en', 'أَذْفَرُ ذ and ذَفْرَآءُ : see ذَفِرٌ , in eight places.', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a3d228ece5e71e09', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_3c8ca6b74205cc1e', 'ذفر', 'e6.raw', 16, 2, 'definition', 'en', 'ذُفْرَةٌ ذ : see ذَفَرٌ .', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8aa53f26fcb4041a', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_555070f3a3244df2', 'ذفر', 'e10.raw', 20, 2, 'definition', 'en', 'ذِفْرَى ذ A camel large in the part called ة : fem. with ة : (AZ, S, K:) or a great camel: (AA:) or (so in the TA; but in the K, “ and ”) hard, or firm, and strong: as also : (K:) but the former ( ذِفِرٌّ ) is of higher authority: also applied to a camel; fem. with ة : and in like manner to an ass: (TA:) or (so in the TA; but in the K, “ and ”) great in make: (K:) also a young man tall, perfect [ in make ], and hardy, strong, or sturdy: (S, K:) and ذِفِرَّةٌ an excellent she-camel, (K,) long-necked: (TA:) and, accord. to the K, a bulky, or thick, ass: but this is at variance with what is found in other lexicons. (TA.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d8ce727c54c61987', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_e76a781d3ba2dbc1', 'ذفر', 'e12.raw', 22, 2, 'definition', 'en', 'رَوْضَةٌ مَذْفُورَةٌ ذ A meadow abounding with ذَفْرَآء . (K.) [See ذَفِرٌ .]', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dca3d30606a964d5', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_e9ccb8192415d2e5', 'ذفر', 'e2.raw', 12, 2, 'definition', 'en', '10 استذفر فِى الأَمْرِ ذ (assumed tropical:) He became very determined, and hardy, [as though he drew forth from himself a pungent odour by sweating,] to do the thing, or affair. (M, TA.) -A2- استذفرت said of a woman, i. q. استثفرت [q. v.]. (TA.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_079315fa814cb4d1', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_f77571e67e0ea290', 'ذفر', 'e9.raw', 19, 2, 'definition', 'en', 'ذِفَرٌّ ذ : see what next follows.', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eb230342b82b7b93', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_721375faaf878103', 'ذفر', 'e3.raw', 13, 2, 'definition', 'en', 'ذَفَرٌ ذ inf. n. of 1. (Msb.) -b2- Pungency, or strength, of odour; (S, A, Mgh, Msb;) or intense pungency or strength thereof; (M, K;) whether sweet or stinking; (S, M, A, Mgh, * Msb;) as also , (K, TA,) or : (so in the TT, as from the M:) a subst. to which it is prefixed, or an epithet by which it is qualified, shows whether it mean sweet or foul: (TA:) or any pungent, or strong, odour; whether sweet or stinking: (T:) or stench of the arm-pit: (Lh, M, K:) or it has this signification as well as the first: (S, M:) or stink, or stench, [absolutely,] (IAar, M, K,) except when relating to musk; not used with reference to any other perfume, or sweet-smelling substance: (IAar, M:) but دَفَرٌ , with the unpointed د , signifies only “ stink, or stench. ” (M.) -b3- The seminal fluid ( مَآء ) of a stallion. (K.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_44059d5de18c34df', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_a1a26f35a32920f7', 'ذفر', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَفِرَ ذ , aor. ذَفَرَ , (S, Msb, K,) inf. n. ذَفَرٌ , (Msb,) He, or it, had, or emitted, a pungent, or strong, odour, or smell; (S, Msb;;) or a very pungent, or very strong, odour, or smell; (M, K;) whether sweet or stinking: (S, M, Msb:) or he had stinking arm-pits; or it (the arm-pit) stank. (Lh, M, K.) [See also ذَفَرٌ , below.] -b2- ذَفِرَ النَّبْتُ The plants became abundant. (AHn. M.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cc3b715aa2d86418', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_a628f43180283200', 'ذفر', 'e7.raw', 17, 2, 'definition', 'en', 'ذَفَرَةٌ ذ : see ذَفَرٌ .', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_535d363608a23a02', 'lane_lexicon', 're_lane_08b2237eeaef2e93', 'sec_lane_b23c8e1e9bce9b55', 'ذفر', 'e4.raw', 14, 2, 'definition', 'en', 'ذَفِرٌ ذ (S, M, A, Msb, K) and (M, K) Having, or emitting, a pungent, or strong, odour, or smell; (S, * Msb;) or having, or emitting, a very pungent, or very strong, odour, or smell; (M, K;) whether sweet or stinking: (S, M, Msb:) or especially, (Lh, M, K,) or also, (S, M, A,) a man having stinking arm-pits, (S, M, A, K,) and a foul smell: (S, M, A:) fem. of the former, ذَفِرَةٌ ; and of the latter, : (M:) or ذَفِرَةٌ signifies a woman having a strong smell; whether sweet, like that of musk, or foul, like that of the arm-pits. (Msb.) You say مِسْكٌ , (S, A, M, K,) and ذَفِرٌ , (M, K,) Pungent, or strongscented, musk: (S, A:) or musk of the utmost excellence. (K.) And فَأْرَةٌ [ A pungent, or strong-scented, or ] sweet-smelling [ follicle, or vesicle, of musk ]: Er-Rá''ee says, speaking of camels that had pastured upon herbage and its flowers, and gone to water, and come back from it with t ذَفرَةٌ ذ A single emission of pungent, or strong, odour. (Msb.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eda905cc49beb44f', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_01796d7fd50039de', 'ذرع', 'e10.raw', 20, 2, 'definition', 'en', 'ذَرِعٌ ذ : see ذَرِيعٌ , in two places. -b2- (assumed tropical:) That journeys by night and by day. (K.) -b3- (assumed tropical:) Longtongued with evil speech. (K.) -A2- (assumed tropical:) Good in social, or familiar, intercourse. (K, TA.)', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e8a82566aab18b4c', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_07b67f354a928534', 'ذرع', 'e4.raw', 14, 2, 'definition', 'en', '4 اذرع ذ , (K,) inf. n. إِذْرَاعٌ : (S:) see 1, first sentence. -b2- (tropical:) He exceeded the due bounds, or just limits, in speech, or talk; (S, K, TA;) he talked much; (S, TA;) as also : (S, Msb, * K, TA:) J says, [in the S,] I am of opinion that it has originated from the stretching forth of the fore arm; for he who talks much sometimes does that; and ISd says the like. (TA.) -b3- أَذْرَعَ ذِرَاعَيْهِ مِنْ تَحْتِ الجُبَّةِ and , He put forth, (K, TA,) and extended, (TA,) his fore arms from beneath the jubbeh: (K, TA:) or أَذْرَعَ ذِرَاعَيْهِ , and , [the latter with the د unpointed,] he drew forth his fore arms from the sleeves of a narrow-sleeved jubbeh: (Mgh:) the latter verb being of the measure اِفْتَعَلَ ; (Mgh, K;) like اِذَّكَرَ , (TA,) or اِدَّكَرَ , (Mgh,) from الذِّكْرُ : (Mgh, TA:) the former accord. to one relation, the latter accord. to another, occurring in a trad. (Mgh, TA.) -b4- اذرع also signif 5 تَذَرَّعَ see 1; first and second sentences: -b2- and see also 4. -b3- تَذَرُّعٌ also signifies The measuring a thing with the fore arm. (S, K.) [See also 1.] A poet says, (S,) namely Keys Ibn-El-Khateem El-Ansáree, (TA,) تَرَى قِصَدَ المُرَّانِ تُلْقَى كَأَنَّهَا تَذَرُّعُ خِرْصَانٍ بِأَيْدِىالشَّوَاطِبِ [ Thou seest the fragments of the hard and pliant spears thrown as though they were what is seen in the measuring, with the fore arm, of rods of palm-sticks in the hands of the females who pare them ]: (S, TA:) or, accord. to As, تَذَرَّعَ فُلَانٌ الجَرِيدَ signifies Such a one put the palm-sticks upon his fore arm, and pared them: and خِرْصَانٌ means, originally, rods of palm-sticks: and شَوَاطِبُ is pl. of شَاطِبَةٌ ; meaning a woman who peels the عَسِيب , and then throws it to the مُنَقِّيَة , who removes all that is upon it with her knife until she has left it slender, when she throws it back to the شاطبة . (TA.) -b4- Also, The splitting ( تَشَقُّق [which is intrans., but I think it is a mistake for تَشْقِيق , which is trans.,]) of a thing into several oblong pieces of the measure of the cubit in length. (Ibn-''Abbád, K.) -b5- تَذَرَّعَتِ المَرْأَةُ The woman split 8 اِذَّرَعَ ذ or إِدَّرَعَ : see 4.', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_96689faba2dab2dc', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_1073c33f3e20c89c', 'ذرع', 'e8.raw', 18, 2, 'definition', 'en', 'ذَرْعٌ ذ , in its primary acceptation, has the signification explained in the first sentence of this article. (S, TA.) -b2- [Hence, it is used in the sense of] (tropical:) Power, or ability; as also ; (TA;) or a man''s reach, or extent of power or ability. (Msb.) And hence the phrases, ضَاقَ بِالأَمْرِ ذَرْعُهُ , and , (K,) and ضَاقَ بِالأَمْرِ ذَرْعًا , (S, Msb, K,) in which the last word is in the accus. case as an explicative, for the original form of the phrase is that first mentioned, (TA,) and sometimes they said , (S, TA,) (tropical:) He was unable to do, or accomplish, the thing, or affair; as though meaning, he stretched forth his arm to it and it did not reach it; (S, TA; *) or these phrases are thus used because he who is short in the fore arm will not reach that which he who is long therein reaches, nor will the power of the former equal that of the latter; therefore they are proverbially applied to him whose power falls short of the attainment, or accomplishment, of an affair: (TA:) or he lacked strength, or power, or ability, to do, or accomplish, the thing, or affair, and found not any wa ذَرَعٌ ذ A coveting; desiring eagerly; or lusting. (S, K.) [Perhaps an inf. n. of which the verb is ذَرِعَ .] -A2- See also ذَرِيعَةٌ .', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_431517008350eeaf', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_21be26741c021251', 'ذرع', 'e18.raw', 28, 2, 'definition', 'en', 'ذُرَيِّعٌ ذ : dims. of ذِرَاعٌ , q. v.', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6474c20143ff706f', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_2864f5f57d9ceea2', 'ذرع', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرْعٌ ذ , [inf. n. of ذَرَعَ ,] in its primary acceptation, signifies The stretching forth, or extending, the arm, or fore leg: (S, TA:) [or rather, when said of a man, the fore arm; and of a beast, the arm; though the whole arm of a man is generally stretched forth with his fore arm, and the whole fore leg of a beast with his arm: and and and signify the same, as will be shown by explanations of their verbs.] You say, ذَرَعَ البَعِيرُ يَدَهُ The camel stretched forth, or extended, his fore leg in going: and البَعِيرُ The camel stretched forth, or extended, his arm ( ذِرَاعَهُ ) in his going. (TA.) -b2- ذَرَعَهُ , (S, Msb, K,) aor. ذَرَعَ , (Msb, K,) inf. n. ذَرْعٌ , (S, Msb,) He measured it with the ذِرَاعٌ [or cubit ]; (Msb, K;) namely, a garment, or piece of cloth, (S, Msb, K,) &c.: (S:) and ذَرَعَهُ بِذِرَاعِهِ 2 ذرّع ذ , (S, K, &c.,) inf. n. تَذْرِيعٌ : (S:) see 1, first sentence. -b2- Also He spread himself out widely, (El-Moheet, L, K,) and stretched forth his fore arms, (El-Moheet, L,) in swimming: (El-Moheet, L, K:) said of a man. (El-Moheet, L.) -b3- He (a man) raised his fore arms; and particularly, in announcing good tidings or in warning: (TA:) or he (an announcer of good tidings) made a sign with his arm, or hand. (S, K.) -b4- ذرّع فِى المَشْىِ He moved about his fore arms in walking, or going along. (S, K.) And ذرّع فى السَّعْىِ , (L, TA,) in the O and Moheet and K, erroneously, فىالسَّقْىِ , (TA,) He helped himself with his arms, and moved them about, (O, El-Moheet, L, K,) in walking, or walking quickly, or running. (L.) -b5- ذرّع لِى شَيْئًا مِنْ خَبَرِهِ (tropical:) He acquainted me with somewhat of his tidings, or case; (K, TA;) [as though he stretched forth his arm with his information;] said by one who has asked another respecting his case. (TA.) -b6- [And hence, app.,] ذرّع بِكَذَا (assumed tropical:) He acknowledged, or confessed, such a thing. (K 3 مُذَارَعَةٌ ذ signifies The selling by measure with the cubit; not by number, and without knowing the measure. (K.) [In the CK, والجُزافُ is put by mistake for والجُزافِ .] You say, بِعْتُهُ الثَّوْبَ مُذَارَعَةٌ I sold to him the garment, or piece of cloth, by measure with the cubit. (TA.) -b2- See also 1, in two places. -b3- ذَرَاعْتُهُ , (TA,) inf. n. مُذَارَعَةٌ , (K, TA,) (assumed tropical:) I mixed with him in familiar, or social, intercourse; or became intimate with him: or I became copartner with him; or shared with him: syn. خَالَطْتُهُ . (K * TA.)', 'derived_from_raw_tei', 960);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3f39357a0b926fa9', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_287a19dd2960617b', 'ذرع', 'e15.raw', 25, 2, 'definition', 'en', 'ذَرِيعٌ ذ Wide in step, (S, K,) and light, or active, in pace, or going; (K;) applied to a horse, (S, K,) and to a camel; as also : (K:) and quick: (S, Msb, K:) [and so ; for] , (S, O, K,) applied to the legs of a quadruped ( قَوَائِمٌ ), (S, TA,) signifies quick, (S, K,) wide in step, taking much of the ground: (O, K:) or, as some say, this last word signifies the legs of a beast, (TA,) like , (S, K,) pl. of مِذْرَاعٌ . (K.) It is said of Mohammad, in a trad., كَانَ ذَرِيعَ المَشْىِ (assumed tropical:) He was quick, and wide of step, in walking. (TA.) And you say, رَجُلٌ ذَرِيعٌ بِالِكِتَابَةِ (assumed tropical:) A man quick in writing. (TA.) And أَكَلَ أَكْلًا ذَرِيعًا (assumed tropical:) He ate quickly and much. (TA.) And قَتْلٌ ذَرِيعٌ (assumed tropical:) ذُرَيْعٌ ذ a dim. of ذِرَاعٌ , q. v.', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8a4bfe0be2130c12', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_35eb1f2f3a71f3c1', 'ذرع', 'e7.raw', 17, 2, 'definition', 'en', '10 استذرع بِهِ ذ He concealed, or protected, himself by it, (namely a thing, TA,) and made it a ذَرِيعَة [q. v.] for him. (Ibn-''Abbád, K.)', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e4b6d98e234de202', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_3c263fa7302239a2', 'ذرع', 'e12.raw', 22, 2, 'definition', 'en', 'ذَرَاعٌ ذ (S, K) and (ISd, K) (assumed tropical:) A woman (S) light, or active, with the hands in spinning: (S, K:) or one who spins much; who has ability to do so. (TA.)', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1c4b9c2563232598', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_4338d86f2f015a82', 'ذرع', 'e25.raw', 35, 2, 'definition', 'en', 'مُذَرَّعٌ ذ , an epithet applied to an ass, and to a mule, meaning Having what are termed رَقْمَتَانِ [q. v.] upon his arms. (L.) -b2- Hence, (L,) (tropical:) A man (TA) whose mother is more noble than his father: (S, L, K:) as though, (K,) or said to be, (S,) so called because of the رَقْمَتَانِ upon the arm [or arms] of the mule, for they come to him from the side of the ass; (S, K;) or so called as being likened to the mule, because he has upon his arms رقمتان like those of the arm of the ass, thereby resembling the ass; and the mother of the mule is more noble than his father. (L.) [See also أَذْرَعُ .] -b3- A lion having upon his arms the blood of his prey. (IAar.) -b4- [A beast] struck in the uppermost part of his breast so that the blood has flowed upon his arms. (K.) -b5- A horse that outstrips: or (originally, TA) that overtakes the wild animal and has his arms smeared by his rider''s piercing the latter so as to make the blood flow forth; (K, TA;) this blood upon his arms being the sign of his having outstripped. (TA,) -b6- A bull having black spots, or black places, upon his shanks. (S, K.) -b7- مُذَرَّعَةٌ A hyena having stripes upon its arms: (K:) an epithet in which the quality of a subst. predominates: or applied to the hyena because of blackness on its arms. (TA مُذَرِّعٌ ذ Rain that sinks into the earth to the depth of a cubit. (S, K.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b46bcc1635e54031', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_d5d7601d47a48a0d', 'ذرع', 'e5.raw', 15, 2, 'definition', 'en', '4 اذرع ذ , (K,) inf. n. إِذْرَاعٌ : (S:) see 1, first sentence. -b2- (tropical:) He exceeded the due bounds, or just limits, in speech, or talk; (S, K, TA;) he talked much; (S, TA;) as also : (S, Msb, * K, TA:) J says, [in the S,] I am of opinion that it has originated from the stretching forth of the fore arm; for he who talks much sometimes does that; and ISd says the like. (TA.) -b3- أَذْرَعَ ذِرَاعَيْهِ مِنْ تَحْتِ الجُبَّةِ and , He put forth, (K, TA,) and extended, (TA,) his fore arms from beneath the jubbeh: (K, TA:) or أَذْرَعَ ذِرَاعَيْهِ , and , [the latter with the د unpointed,] he drew forth his fore arms from the sleeves of a narrow-sleeved jubbeh: (Mgh:) the latter verb being of the measure اِفْتَعَلَ ; (Mgh, K;) like اِذَّكَرَ , (TA,) or اِدَّكَرَ , (Mgh,) from الذِّكْرُ : (Mgh, TA:) the former accord. to one relation, the latter accord. to another, occurring in a trad. (Mgh, TA.) -b4- اذرع also signif 5 تَذَرَّعَ see 1; first and second sentences: -b2- and see also 4. -b3- تَذَرُّعٌ also signifies The measuring a thing with the fore arm. (S, K.) [See also 1.] A poet says, (S,) namely Keys Ibn-El-Khateem El-Ansáree, (TA,) تَرَى قِصَدَ المُرَّانِ تُلْقَى كَأَنَّهَا تَذَرُّعُ خِرْصَانٍ بِأَيْدِىالشَّوَاطِبِ [ Thou seest the fragments of the hard and pliant spears thrown as though they were what is seen in the measuring, with the fore arm, of rods of palm-sticks in the hands of the females who pare them ]: (S, TA:) or, accord. to As, تَذَرَّعَ فُلَانٌ الجَرِيدَ signifies Such a one put the palm-sticks upon his fore arm, and pared them: and خِرْصَانٌ means, originally, rods of palm-sticks: and شَوَاطِبُ is pl. of شَاطِبَةٌ ; meaning a woman who peels the عَسِيب , and then throws it to the مُنَقِّيَة , who removes all that is upon it with her knife until she has left it slender, when she throws it back to the شاطبة . (TA.) -b4- Also, The splitting ( تَشَقُّق [which is intrans., but I think it is a mistake for تَشْقِيق , which is trans.,]) of a thing into several oblong pieces of the measure of the cubit in length. (Ibn-''Abbád, K.) -b5- تَذَرَّعَتِ المَرْأَةُ The woman split 8 اِذَّرَعَ ذ or إِدَّرَعَ : see 4.', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_57a9d289091ff4c7', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_dd64df9983370327', 'ذرع', 'e13.raw', 23, 2, 'definition', 'en', 'ذِرَاعٌ ذ , of a man, (Msb,) [The part ] from the elbow to the extremities of the fingers; (Mgh, Msb;) the fore arm; syn. سَاعِدٌ [q. v.; thus corresponding to the سَاق of the leg]: (Lth, K:) and (tropical:) [the space ] from the extremity of the elbow to the extremity of the middle finger: (M, Mgh, * K: [in the last of which, the space is plainly shown to be meant, like as the part is shown in the Msb to be meant in the explanation cited above from that work and the Mgh: see also جَرِيبٌ :]) in both these senses, sometimes masc., (K,) accord. to Kh: (TA:) J says, (TA,) as relating to the arm, it is masc. and fem.; but Sb says that it is fem.: (S, TA:) [Mtr says,] it is fem.: (Mgh:) [Fei says,] the measure so called is in most instances fem.: accord. to ISk, it is fem.; but some of the Arabs make it masc.: Fr says that it is fem.; but that some of [the tribe named] ''Okl make it masc.: As did not know an instance of its being masc.: and Zj says that such an instance is extr.; not choice: (Msb:) the measure thus called, [i. e. the cubit, ] (Msb,) the ذِرَاعٌ مُكَسَّرَة [or cubit which is divided into fractions ], (Mgh,) is six قَبَضَات [or fists ] (Mgh, Msb) of middling measure; (Msb;) and this is called ذِرَاعُ العَمَامَّةِ [ the cubit of the common people, or the common cubit ], because it wants one ذَرُوعٌ ذ : see what next follows.', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2db952e92f001908', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_def4e7c57fd94cd3', 'ذرع', 'e21.raw', 31, 2, 'definition', 'en', 'ذَارِعٌ ذ [so in a copy of the S and of the K and in the TA: in one copy of S and in one of the K, ذِرَاع : in the CK, ذَرّاع : but the right reading is ذَارِعٌ , as is shown by verses in which it occurs, cited in the TA, and by its pl.,] A small [ skin of the kind called ] زِقّ , which is stripped off from the part next to the ذِرَاع [or arm ], (S, K,) and which is for شَرَاب [or wine ]; (S;) and signifies [the same; or simply] a small زِقّ : (TA:) or, as some say, زِقٌّ ذَارِعٌ signifies a زقّ that takes much water: (TA:) the pl. is ذَوَارِعُ . (S, TA.) -A2- نَاقَةٌ ذَارَعَةٌ An excellent she-camel. (TA.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_af409ed3b6703ff0', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_ebeca0b3b22798cb', 'ذرع', 'e24.raw', 34, 2, 'definition', 'en', 'مِذْرَعٌ ذ : see ذَارِعٌ .', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_58dd49d97e23d7d4', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_f77ef32c571cba9f', 'ذرع', 'e23.raw', 33, 2, 'definition', 'en', 'تَذْرِيعٌ ذ The redundant part of the cord with which the arm [ of a camel ] is bound: [see 2, latter part:] a subst. like [ تَصْدِيرٌ and] تَنْبِيتٌ ; not an inf. n. (TA.)', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_24bdd90678e52d71', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_f7ddbc2ea0375c48', 'ذرع', 'e22.raw', 32, 2, 'definition', 'en', 'أَذْرَعُ ذ [ More, and most, light, or active, and quick, with the arms, or hands, or (assumed tropical:) otherwise ]. It is said in a trad., خَيْرُ كُنَّ أَذْرَعُكُنَّ لِلْغَزْلِ The best of you females is the most light, or active, of hand, of you, in spinning: or, the most able of you to spin. (TA.) And قَتَلُوهُمْ أَذْرَعَ قَتْلٍ (assumed tropical:) They slew them with the quickest slaughter. (S.) -b2- (assumed tropical:) More, and most, chaste in speech. (K.) You say, هُوَ أَذْرَعُ مِنْهُ (assumed tropical:) He is more chaste of speech than he. (TA.) -A2- (assumed tropical:) One whose mother is Arabian but not his father; syn. مُقْرِفٌ : or the son of an Arabian man by an emancipated slavewoman: (K:) the former is the more correct. (TA.) [See also مُذَرَّعٌ .]', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bf15c1b317c4dc8f', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_7c70bb9f7493040d', 'ذرع', 'e20.raw', 30, 2, 'definition', 'en', 'ذَرَّاعٌ ذ A measurer with the ذِرَاع [or cubit ]. (T in art. أبر .) -b2- A he-camel that drives the she-camel with his arm and so makes her lie down that he may cover her. (Ibn-''Abbád, K.)', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_56d79b04a4952ca1', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_abc99422b2c2aced', 'ذرع', 'e11.raw', 21, 2, 'definition', 'en', 'ذُرْعَةٌ ذ : see ذَرِيعَةٌ .', 'derived_from_raw_tei', 961);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_148cdae4732d1458', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_b4e99083db8fd1f7', 'ذرع', 'e17.raw', 27, 2, 'definition', 'en', 'ذَرِيعَةٌ ذ A she-camel by which the archer, or the like, conceals himself from the game, (S, K, TA,) walking by her side, and shooting, or casting, when the object puts itself in his power, having first left the she-camel to roam at pleasure with the wild animals in order that they may become familiar with her; (TA;) like دَرِيْئَةٌ ; (S;) as also : (K:) pl. ذُرُعٌ . (IAar.) -b2- Hence, (tropical:) Anything that brings one near to a thing; (IAar;) a means of access, nearness, intimacy, ingratiation, attachment, or connexion; syn. وَسِيلَةٌ ; (S, Msb, K, TA;) and سَبَبٌ ; and وُصْلَةٌ ; (TA;) as also : (Ibn-''Abbád, K:) pl. ذَرَائِعُ . (S, Msb.) You say, فُلَانٌ ذَرِيعَتِى إِلَيْكَ (tropical:) Such a one is my means of access to thee, and of attachment to thee, or connexion with thee. (TA.) -b3- Also, [like دَرِيْئَةٌ ,] A ring by aiming at which one learns the art of shooting, or casting [ the lance &c. ]. (TA.)', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f7ab751b5fb8153a', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_b80331440742ad82', 'ذرع', 'e27.raw', 37, 2, 'definition', 'en', 'مِذْرَاعٌ ذ sing. of مَذَارِعٌ , [which is contr. to rule,] (S, K,) in a sense pointed out below, (S,) or in all the senses explained below, and of مَذَارِيعٌ , (K,) which is agreeable to rule. (TA.) -b2- مَذَارِعُ signifies The legs of a beast; (S, K;) as also مَذَارِيعُ , and ذَرِعَاتٌ ; see ذَرِيعٌ ; because the beast measures with them the ground: or, as some say, [like the pl. of ذِرَاعٌ ,] the parts of a beast between the knee and the arm-pit. (TA.) -A2- مَذَارِعُ also signifies The towns ( قُرَى , S, or بِلَاد , K) that are between the cultivated land and the desert; (S, K;) such as El-Kádiseeyeh and El-Ambár; (TA;) in this sense, (S,) as in others, (K,) pl. of مِذْرَاعٌ ; (S, K;) as also مَذَارِيعُ ; (K;) syn. with مَزَالِفُ ; (S;) and بَرَاغِيلُ : (TA:) El-Hasan El-Basree speaks of the مَذَارِعُ of El-Yemen. (TA.) [Freytag says, without mentioning his authority, that مَذَارِعُ has the same signification with the inhabitants of Nejd as مَخَالِيفُ with the inhabitants of El-Yemen and مَزَالِفُ in the region of El-Hijáz: but this is at variance with all that I have found, in respect of the term مخاليف .] مَذَارِعُ ذ a pl. [contr. to rule] of مِذْرَاعٌ , q. v.: (S, K:) and of ذِرَاعٌ as signifying (assumed tropical:) A sleeve. (TA.) See the last of these words, near the middle of the paragraph.', 'derived_from_raw_tei', 963);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b9ef7a8efbd53ab4', 'lane_lexicon', 're_lane_0bd2d67c7e7e4bff', 'sec_lane_bf52eb5faac2cf17', 'ذرع', 'e19.raw', 29, 2, 'definition', 'en', 'ذُرَيِّعَةٌ ذ : dims. of ذِرَاعٌ , q. v.', 'derived_from_raw_tei', 962);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_73746d9bdfe618ee', 'lane_lexicon', 're_lane_0db63d743c360a98', 'sec_lane_2e88f8a3d29643e0', 'ذلك', 'e1.raw', 11, 2, 'definition', 'en', 'ذٰلِكَ ذ : see art ذا ; and ك as a particle of allocution.', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e0609b494fd8e7f3', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_0072593e1049fd6f', 'ذكر', 'e27.raw', 37, 2, 'definition', 'en', 'تَذْكِرَةٌ ذ an inf. n. of 2. (A, TA.) -b2- [And hence,] A thing by means of which something that one wants [or desires to remember ] is called to mind; a memorandum. (S, K, TA.) -b3- [ A biographical memoir. -b4- And, in the present day, Any official note; such as a passport; a permit; and the like. ]', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dcfa754baeb4fbf7', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_04e874101d80bc50', 'ذكر', 'e9.raw', 19, 2, 'definition', 'en', 'ذَكْرٌ ذ : see ذِكْرٌ : -A2- and ذَكِيرٌ .', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1213f4b708991c0f', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_194ca6a8716d5c9c', 'ذكر', 'e11.raw', 21, 2, 'definition', 'en', 'ذِكْرٌ ذ (Yoo, A''Obeyd, Yaakoob, S, M, A, Msb, K) and , (Yoo, A''Obeyd, Yaakoob, S, A, Msb, K, TA,) or the latter only in the first of the senses here to be explained, (Fr, Msb, TA,) and the latter only is mentioned in this sense in the Fs, (TA,) and is said by El-Ahmar to be of the dial. of Kureysh, (TA,) [both said in the Msb to be simple substs., though many hold them to be inf. ns.,] and , accord. to one of the expositors of the Fs, but this is strange, (TA,) and (S, M) and (M, TA) and , (S, M, [see 1, first sentence,]) and also دِكْرٌ (S) and دُكْرٌ , mentioned by ISd as of the dial. of Rabee''ah, but held by him to be of weak authority, (TA,) Remembrance; (S, M, A, Msb, K, &c.;) the presence of a thing in the mind: (Er-Rághib:) also termed ذِكْرٌ بِالقَلْبِ , (Msb, TA,) to distinguish it from ذِكْرٌ in another sense, to be explained below: (TA:) he pl. of is ذِكَرٌ , (M,) also said to b ذَكَرٌ ذ [probably originally signifying “ mentioned, ” or “ talked of, ” of the measure فَعَلٌ in the sense of the measure مَفْعُولٌ , like نَفَضٌ in the sense of مَنْفُوضٌ , and خَبَطٌ in the sense of مَخْبُوطٌ , and قَبَضٌ in the sense of مَقْبُوضٌ , &c.; and hence the first, and perhaps most others, of the significations here following:] Male; masculine; of the male, or masculine, sex, or gender; contr. of أُنْثَى : (S, A, Msb, K, &c.:) [the corresponding word in Hebrew ( ) has been supposed to have this signification because a male is much “ mentioned, ” or “ talked of; ” and it is well known that the Arabs make comparatively little account of a female:] pl. ذُكُورٌ (S, A, Msb, K) and ذُكُورَةٌ (A, Msb, K) and ذِكَارٌ (K) and ذِكَارَةٌ and ذُكْرَانٌ (S, A, Msb, K) and ذِكَرَةٌ : (S, K:) [the last, in one copy of the S, I find written , which, if correct, is a pl. of pauc.: and in the TA, in the same phrase in which it occurs in the S, it is written , and expressly said to be with damm, so that it is a quasi-pl. n.:] the pl. form with و and ذَكُرٌ ذ : see ذَكِيرٌ .', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cf7646a25df8e34e', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_306d6efcbbd6423f', 'ذكر', 'e19.raw', 29, 2, 'definition', 'en', 'ذَكَرَةٌ ذ : see مُذَكَّرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_35c1ef1ec5b46a5a', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_32a2022ab33e21ab', 'ذكر', 'e33.raw', 43, 2, 'definition', 'en', 'مَذْكُورٌ ذ [pass. part. n. of 1]. -b2- (assumed tropical:) A man praised, or spoken of well. (TA.) -b3- لَمْ يَكُنْ شَيْئًا مَذْكُورًا , in the Kur [lxxvi. 1], means [accord. to some] When he was not a thing existing by itself, though existing in the knowledge of God. (TA.)', 'derived_from_raw_tei', 971);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7f2420e1d30830b2', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_3979c77774eb38a1', 'ذكر', 'e16.raw', 26, 2, 'definition', 'en', 'ذَكْرَةٌ ذ : see مُذَكَّرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a30e9f99cb980e74', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_3f33d88b17399af9', 'ذكر', 'e8.raw', 18, 2, 'definition', 'en', '8 اِدَّكَرَ ذ and اِذَّكَرَ and اِذْدَكَرَ : see 1, in three places, in the first and second sentences.', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_71ec7ba48dd2c6c4', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_539d2846ca008d5f', 'ذكر', 'e24.raw', 34, 2, 'definition', 'en', 'ذُكَّارَةٌ ذ The males of palm-trees. (K.)', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_92b71501d80a3777', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_59ee0523fc52add6', 'ذكر', 'e15.raw', 25, 2, 'definition', 'en', 'سَيْفٌ ذُو ذُكُرٍ ذ : see ذُكْرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_84718bd95129669c', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_5c2b90d45d0a8daf', 'ذكر', 'e10.raw', 20, 2, 'definition', 'en', 'ذُكْرٌ ذ : see ذِكْرٌ , in six places. -A2- سَيْفٌ ذُو ذُكْرٍ , or , (as in different copies of the S,) and أَذْكِرَةٍ , [which is the pl.,] (A,) (tropical:) A cutting, or sharp, sword. (S, A.) [See ذُكْرَةٌ .]', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_26e17a664e36e7b4', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_d1df3dc007e343d2', 'ذكر', 'e17.raw', 27, 2, 'definition', 'en', 'ذُكْرَةٌ ذ : see ذِكْرٌ , in two places: -A2- and ذَكَرٌ , in two places. -A3- Also (tropical:) A piece of steel that is added [ to the edge of a sword and ] to the head of an axe &c. (K, * TA.) -b2- And (tropical:) Sharpness of a sword: [see also ذُكْرٌ :] and of a man. (S, A, K.) You say, ذَهَبَتْ ذُكْرَةُ السَّيْفِ , and ذُكْرَةُ الرَّجُلِ , (tropical:) The sharpness of the sword, and the sharpness of the man, went. (S, A.)', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d72d8ad3bc2a866f', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_dbecea914cf1a418', 'ذكر', 'e28.raw', 38, 2, 'definition', 'en', 'مَذْكَرٌ ذ A place of remembrance: pl. مَذَاكِرُ : whence المَذَاكِرُ in a trad., app. meaning The black corner or stone [ of the Kaabeh ]. (TA.)', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d0f74dadfbc86f31', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_dc0c3eea6f60507c', 'ذكر', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَكَرَهُ ذ , [aor. ذَكُرَ ,] inf. n. ذِكْرَى , (S, A, Msb,) which is fem., (Msb,) and imperfectly decl., (S,) and ذِكْرٌ (A, K) [and ذُكْرٌ , or, accord. to EtTebreezee, (Ham p. 26,) the latter of these two but not the former, or, as is said in the Msb., both are properly substs., and a distinction is made between them, as will be shown below,] and تَذْكَارٌ , (K,) He preserved it in his memory: (K, * TA:) he remembered it; (S, A;) as also ذَكَرَهُ بِقَلْبِهِ [to distinguish it from ذَكَرَ in a sense afterwards to be explained], (S, Msb,) and ; (S, A;) and (S, K, TA,) originally اِذْتَكَرَهُ (S,) and اِذَّكَرَهُ (TA, and so in the CK,) and اِذْدَكَرَهُ (K,) and , (AZ, K,) signify the same as تذكّرهُ (K) [as explained above]: signifies also he became reminded of it; (Msb;) [and so and its variations: and 2 ذكّرهُ إِيَّاهُ ذ , (S, A, * Msb, K,) and ذكّرهُ بِهِ , (Kur xiv. 5, &c.,) inf. n. تَذْكِرَةٌ (A, TA) and تَذْكِيرٌ , (K, TA,) and quasi-inf. n. imperfectly decl.; (A, * K, * TA;) and ايّاهُ ; (S, Msb, K;) He reminded him of, or caused him to remember, him, or it. (S, Msb, K.) -b2- And ذكّر , (TA,) inf. n. تَذْكِيرٌ (K) [and تَذْكِرَةٌ also, as in the Kur xx. 2], He exhorted; admonished; exhorted to obedience; gave good advice, and reminded of the results of affairs; reminded of what might soften the heart, by the mention of rewards and punishments. (K, TA.) Thus the verb is used in the Kur lxxxviii. 21. (TA.) -A2- Also ذكّرهُ , inf. n. تَذْكِيرُ , He made it (a word) masculine; contr. of أَنَّثَهُ . (S, * Msb, K. *) -b2- In the Kur [ii. 282], فَتُذَكِّرَ إِحْدَاهُمَا الأُخْرَى is said by some to signify (assumed tropical:) That one of them may make the other to be in the legal predicament of a male: [meaning that both of them together shall be as one man:] or, accord. to others, 3 ذاكرهُ ذ , (MA,) inf. n. مُذَاكَرَةٌ , (KL;) He called to mind with him (MA, KL) a story, or discourse, or the like, (MA,) or a thing. (KL.) -b2- [And hence, He conferred with him. ]', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e82513267fbfd1b8', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_e02b4ac978dac341', 'ذكر', 'e23.raw', 33, 2, 'definition', 'en', 'ذِكِّيرٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_92330d3a3b534d22', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_ef3653ff77386b9f', 'ذكر', 'e20.raw', 30, 2, 'definition', 'en', 'ذَكِرَةٌ ذ : see مُذَكَّرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_33313e2474aec149', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_6b266478125a2c4b', 'ذكر', 'e14.raw', 24, 2, 'definition', 'en', 'ذَكِرٌ ذ : see ذَكِيرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f939c421838bc99f', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_74ba08a26cb3d924', 'ذكر', 'e6.raw', 16, 2, 'definition', 'en', '6 تذاكروا ذ They called to mind [a story, or discourse, or the like, or a thing,] one with another. (KL. [See 3.]) -b2- [And hence, They conferred together. ]', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_88a1393581afb24e', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_7733f04d8ba567f0', 'ذكر', 'e18.raw', 28, 2, 'definition', 'en', 'ذِكْرَةٌ ذ : see ذِكْرٌ , in two places: -A2- and ذَكَرٌ , in two places.', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bbb2087df93bf9a8', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_8c5fef9f2f8c217c', 'ذكر', 'e31.raw', 41, 2, 'definition', 'en', 'مُذَكَّرٌ ذ [A masculine word; a word made mas- culine ]. -b2- مُذَكَّرَةٌ A she-camel resembling a hecamel in make and in disposition. (S.) And also, (K, TA,) or , (accord. to the CK,) A woman who makes herself like a male; (K;) as also , (L, and so in a copy of the K,) or , (so in another copy of the K, and in the TA,) or , (so in the CK,) and . (K.) -b3- مُذَكَّرَةُ الثُّنْيَا A she-camel having a large head, (K, TA,) like that of a he-camel: (TA:) because her head is one of the parts that are excepted in the game of chance [called المَيْسِر ] for the man who has sold her: [therefore those parts are termed الثُّنْيَا :] (K:) or resembling the make of the male in [ the largeness of ] the head and legs. (Th, M in art. ثنى .) -b4- And يَوْمٌ مُذَكَّرٌ (t مِذْكَارٌ ذ A woman [or other female] that usually brings forth males. (S, K.) And A man who usually begets male children. (TA.) -b2- Also (tropical:) Land that produces herbs, or leguminous plants, such as are termed ذُكُور : (A, TA: [see مُذْكِرٌ , and ذَكَرٌ :]) or that does not produce [ anything ]: but the former signification is the more common. (TA.) -b3- And فَلَاةٌ مِذْكَارٌ (tropical:) A terrible desert; (As, A, K;) that is not traversed but by strong, courageous, stubborn men. (As, K.)', 'derived_from_raw_tei', 971);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bd874e6ea456bbac', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_8d84682c4df77a8b', 'ذكر', 'e7.raw', 17, 2, 'definition', 'en', '8 اِدَّكَرَ ذ and اِذَّكَرَ and اِذْدَكَرَ : see 1, in three places, in the first and second sentences.', 'derived_from_raw_tei', 969);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ada99e6794b58d40', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_8ee51974e4d4e0d2', 'ذكر', 'e35.raw', 45, 2, 'definition', 'en', 'مُتَذَكّرَةٌ ذ : see مُذَكَّرٌ .', 'derived_from_raw_tei', 971);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_74ed5bac710dcf0f', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_91115c61a75148b8', 'ذكر', 'e22.raw', 32, 2, 'definition', 'en', 'ذَكِيرٌ ذ A man possessing an excellent memory. (S.) -b2- Also, (AZ, K,) and , (accord. to a MS. copy of the K, and so, as is said in the TA, accord. to the method of the author of the K,) or , (accord. to the CK,) and and , (K,) (tropical:) A man possessing ذِكْر , (K,) i. e., fame, or renown: or glory, or boastfulness. (TA.) -A2- See also ذَكَرٌ , in the latter half of the paragraph.', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1a2ae3d35056ea45', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_a580960bad418180', 'ذكر', 'e21.raw', 31, 2, 'definition', 'en', 'ذِكْرَى ذ : see ذِكْرٌ , in three places. -b2- Remembrance with the reception of exhortation: so in the following passage of the Kur [xlvii. 20], فَأَنَّى لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَاهُمْ [ Then how, that is, of what avail, will be to them their remembrance with the reception of exhortation when it (the hour of the resurrection) cometh to them: or] how will it be to them when it (the hour) cometh to them with their remembrance and their reception of exhortation: (K, * TA:) i. e., this will not profit them. (TA.) -b3- Repentance: so in the Kur [lxxxix. 24], وَأَنَّى لَهُ الذِّكْرَى , i. e. And how shall he have repentance? (K, TA.) -b4- A reminding, or causing to remember: so in the Kur viii. 1, and xi. 121, (K,) and li. 55. (Fr.) See 2. -b5- An admonition: so in the Kur xxxviii. 42, and xl. 56. (K.) -b6- A being reminded, or caused to remember: so in the Kur [xxxviii. 46], in the phrase ذِكْرَى الدَّارِ Their being reminded of, or caused to remember, the latter abode, and being made to relinquish worldly things, or not to desire them: (K:) or it may mean their remembering much the latter abode. (B, TA.)', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_248ec8acd5b30cc4', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_a7ba081496846ce7', 'ذكر', 'e25.raw', 35, 2, 'definition', 'en', 'ذَاكِرٌ ذ [act. part. n. of 1]. -b2- مَا حَلَفْتُ بِهِ ذَاكِرًا وَلَا آثِرًا : see art. اثر .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5865837deec84182', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_b6a17bb3c6980f5a', 'ذكر', 'e30.raw', 40, 2, 'definition', 'en', 'مُذْكِرٌ ذ A woman [or other female (see 4)] bringing forth a male: (S, K:) or a woman that brings forth men-children. (TA in art. رجل .) -b2- And (tropical:) A desert that produces herbs, or leguminous plants, of the kind called ذُكُور . (As. [See ذَكَرٌ : and see also مِذْكَارٌ .]) -b3- And (tropical:) A road that is feared. (A, K.) -b4- See also مَذَكَّرٌ , in two places. -b5- And see ذَكَرٌ , in the former half of the paragraph.', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_512db388cbf484f3', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_bda58b901f6c22b0', 'ذكر', 'e34.raw', 44, 2, 'definition', 'en', 'مَذَاكِيرُ ذ said to be an anomalous pl. of ذَكَرٌ in a sense pointed out above: see the latter word. (S, Msb, K. *)', 'derived_from_raw_tei', 971);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3d0fd33357477a12', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_c866fbd0eecee26d', 'ذكر', 'e29.raw', 39, 2, 'definition', 'en', 'مُذْكَرٌ ذ : see its fem., with ة , voce مُذَكَّرٌ .', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1b54925c5d5907e5', 'lane_lexicon', 're_lane_108d191b8ef1b1ed', 'sec_lane_c9cb35bd88c20bba', 'ذكر', 'e26.raw', 36, 2, 'definition', 'en', 'أَذْكَرُ ذ (tropical:) More, and most, sharp, (S, TA,) acute and ardent, vigorous and effective in affairs. (TA.) Mohammad used to go round to his wives in one night, and to perform the ablution termed غُسْل for his visit to every one of them; and being asked wherefore he did so, he answered, إِنَّهُ أَذْكَرُ (tropical:) It is more, or most, sharp [or effective ]; syn. أَحَدُّ . (S, TA, from a trad.) And it was said to Ibn-Ez-Zubeyr, when he was prostrated, وَٱللّٰهِ مَا وَلَدَتِ النِّسَآءُ أَذْكَرَ مِنْكَ (tropical:) By God, women have not brought forth one more acute and ardent and vigorous and effective in affairs than thou. (TA from a trad.)', 'derived_from_raw_tei', 970);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e13390babebfefa7', 'lane_lexicon', 're_lane_10ddfc65578ebc48', 'sec_lane_fc07d48341383a37', 'ذكي', 'e1.raw', 11, 2, 'definition', 'en', 'ذُكْيَةٌ ذ : see ذُكْوَةٌ , in art. ذكو .', 'derived_from_raw_tei', 972);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b57aabf4e1808564', 'lane_lexicon', 're_lane_10ddfc65578ebc48', 'sec_lane_95c8584ed2f384d3', 'ذكي', 'e2.raw', 12, 2, 'definition', 'en', 'ذَكِىٌّ ذ : see art. ذكو ,', 'derived_from_raw_tei', 972);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b7b24f2a67eacef9', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_3141d7752e41671f', 'ذيب', 'e4.raw', 14, 2, 'definition', 'en', 'أَذَيْبُ ذ , [like أَزَيْبُ ,] Much water. (K.) -b2- Fright, or fear. (K.) As mentions the saying, مَرَّ فُلَانٌ وَ لَهُ أَذَيْبُ [as though meaning Such a one passed having fright, or fear ]: and he says, I think that one says أَزَيْبُ , with زاى having the meaning here following. (TA.) -b3- Briskness, liveliness, sprightliness, or agility. (K.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f152483f642fe08d', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_46540566832c9033', 'ذيب', 'e3.raw', 13, 2, 'definition', 'en', 'ذِيبَانٌ ذ : see ذُوبَانٌ , in art. ذوب .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d53c1f13ae4dfb5f', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_4864b7f9c192a329', 'ذيب', 'e2.raw', 12, 2, 'definition', 'en', 'ذِيبٌ ذ : see ذِئْبٌ , in art. ذأب .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4427221d31f5dc96', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_dea4ba3de2a4cefb', 'ذيب', 'e5.raw', 15, 2, 'definition', 'en', 'أَرْضٌ مَذْيَبَةٌ ذ : see مَذْأَبَةٌ , in art. ذأب .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f004f31a78ed26fe', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_727f29bb587ea714', 'ذيب', 'e1.raw', 11, 2, 'definition', 'en', 'ذَيْبٌ ذ , (K,) like ذَابٌ , mentioned in art. ذوب , [and ذَيْمٌ ] and ذَامٌ , (TA,) A vice, fault, defect, or the like. (K.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6d5745245022df15', 'lane_lexicon', 're_lane_17cd6782a43472b1', 'sec_lane_7c826c321d1492b0', 'ذيب', 'e6.raw', 16, 2, 'definition', 'en', 'مَذْيُوبٌ ذ : see مَذْؤُوبٌ , in art. ذأب .', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_858223dc2c695860', 'lane_lexicon', 're_lane_1b7671f5605aafc3', 'sec_lane_34e4f884a63faea9', 'هنف', 'e1.raw', 11, 2, 'definition', 'en', 'يَوْمٌ هِلَّوْفٌ ذ : see أَحَصُّ .', 'derived_from_raw_tei', 3044);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a615beeeb51ed749', 'lane_lexicon', 're_lane_1e7ab6768e159d41', 'sec_lane_1a9d5b4753e96944', 'تقي', 'e1.raw', 11, 2, 'definition', 'en', '1 تَقَى تقى تقي وقى , aor. تَقِىَ (T, S, K, in art. وقى ) and تَقَىَ , (T, TA,) or تَقِىَ , aor. تَقَىَ , (Msb, [but the correctness of this I greatly doubt, unless, as appears to be the case, it is meant to be understood as an intrans. verb,]) inf. n. تَقْىٌ , (S and TA in art. تقى , [which art. I find in only one copy of the S,]) or تُقًى , (K,) or تُقَاةٌ , (Msb, and also mentioned in the TA,) of which تُقًى is pl., or coll. n., (Kzz, IB, Msb,) and تَقِيَّةٌ (K) and تِقَآءٌ ; (Lh, K;) and , (T, S, Msb, K,) inf. n. اِتِّقَآءٌ (Msb) and [quasi-inf. n.] تَقِيَّةٌ and تُقَاةٌ ; (S, art. وقى ;) He feared God: (S and TA in art. تقى : all else that follows is from art. وقى except where reference is made to another art.:) or he was cautious of a thing; guarded, or was on his guard, against it; prepared, prepared himself, or was in a state of preparation, against it; or 4 مَا اَتْقَاهُ لِلّٰهِ ما اتقاه للٰه ما اتقاه للٰة (S, TA) How great is his reverential, or pious, fear of God! (TA.) -b2- ما اتقاهُ is also said of a saddle, as meaning How good is it for not galling the back! (TA.)', 'derived_from_raw_tei', 310);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_676f32e4b1d36ed8', 'lane_lexicon', 're_lane_1e7ab6768e159d41', 'sec_lane_334eac59e56b0a02', 'تقي', 'e4.raw', 14, 2, 'definition', 'en', 'تُقًى تقى تقي وقى : see تَقْوَى .', 'derived_from_raw_tei', 310);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1798e35d753b9b53', 'lane_lexicon', 're_lane_1e7ab6768e159d41', 'sec_lane_3bc51c43d5f1d4cd', 'تقي', 'e5.raw', 15, 2, 'definition', 'en', 'تُقَاةٌ تقاه تقاة تقى : see تَقْوَى , in two places. -b2- In the phrase in the Kur [iii. 27], إِلَّا أَنْ تَتَّقُوا مِنْهُمْ تُقَاةً , it may be an inf. n. [so that the meaning may be Unless ye fear from them with a great fearing (see 1)]: or it may be a pl. [app. of تَقِىٌّ , like as كُمَاةٌ is pl. of كَمِىٌّ , so that the meaning may be unless ye fear from them, being fearful ]: but it is better to regard it as an inf. n. because another reading is تَقِيَّةً . (M, TA.)', 'derived_from_raw_tei', 310);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fe6c691399ce8378', 'lane_lexicon', 're_lane_1e7ab6768e159d41', 'sec_lane_df895d584e004a57', 'تقي', 'e8.raw', 18, 2, 'definition', 'en', 'تَقْوَى أقوى قوى قوي تقو تقوى تقوي , or تَقْوًى , accord. to different readings in the Kur ix. 110, (Bd,) [of which readings the former is the more common,] is originally تَقْيَا , (K,) [or تَقْيًا ,] or [rather وَقْيَا , or وَقْيًا , and then] وَقْوَى , of the measure فَعْلَى , from وَقَيْتُ , (ISd, TA,) or, accord. to MF, the right opinion is that it is [ وَقْوًى ,] of the measure فَعْوَلٌ , (TA,) and is thus transformed in order to make a distinction between the subst. and the epithet such as خَزْيَا and صَدْيَا : (K:) it is a subst. from اِتَّقَى or وَقَى ; (Msb, K;) [and signifies Fear; caution; &c.: (see 1:) and particularly reverential, or pious, fear of God: or simply piety: or the preservation, or guarding, of oneself, accord. to some, exceedingly, or extraordinarily, from sin, either of commission or of omission: or the preservation, or guarding, of oneself from punishment in the world to come, and from acts of disobedience, by righteous conduct: or righteousness, virtue, justice, or honesty: (se هُوَ أَتْقَى مِنْ فُلَانٍ ذ [ He is more fearing, or cautious, &c., than such a one; more reverentially, or piously, fearful of God; or more pious; &c.;] he has more تَقْوَى than such a one. (TA.)', 'derived_from_raw_tei', 310);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_33aa05c382f792f5', 'lane_lexicon', 're_lane_1e7ab6768e159d41', 'sec_lane_e7364312edb3e690', 'تقي', 'e6.raw', 16, 2, 'definition', 'en', 'تَقِىٌّ تقى تقي وقى , applied to a man, (Msb, K, TA,) i. q. وَقِىٌّ (TA) and مُتَّقٍ (S) [ Fearing; cautious; &c.: (see 1:) and particularly having a reverential, or pious, fear of God: or simply pious: or one who preserves, or guards, himself, accord. to some, exceedingly, or extraordinarily, from sin, either of commission or of omission: (see 8 in art. وقى :)] accord. to IDrd, one who preserves, or guards, himself from punishment [ in the world to come ], and from acts of disobedience, by righteous conduct: from وَقَيْتُ نَفْسِى : said by the grammarians to be originally وَقُوىٌ ; then, تَقُوىٌ : or, accord. to Aboo-Bekr, [originally] of the measure فَعِيلٌ , as is indicated by the first of its pls. mentioned below: but he who says that it is [originally] of the measure فَعُولٌ says that it has that pl. because it has become like a word [originally] of the measure فَعِيلٌ : (TA:) or righteous, virtuous, just, or honest; (Msb in art. تقى ;) contr. of فَاجِرٌ : (idem in art. بر :) pl. أَتْقِيَآءُ (Msb in art. تقى , and K) and تَقِيَّةٌ تقي تقيه تقية وقى : see what next follows.', 'derived_from_raw_tei', 310);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_14e2a51f645d0e67', 'lane_lexicon', 're_lane_2411a640870b2d55', 'sec_lane_2e7987aee6e29aa8', 'ذحل', 'e1.raw', 11, 2, 'definition', 'en', 'ذَحْلٌ ذ (S, Mgh, Msb, K) and (Msb) Rancour, malevolence, malice, or spite; or concealment of enmity, and violent hatred, in the heart; or retention of enmity in the heart, with watchfulness for an opportunity to indulge it or exercise it; syn. حِقْدٌ : (S, Mgh, Msb, K:) and [simply] enmity: (S, K:) or blood-revenge; or retaliation of murder or homicide; or a seeking to revenge, or avenge, or retaliate, blood; syn. ثَأْرٌ : or a desire, or seeking, for retaliation of a crime or of enmity: (K:) pl. (of the former) ذُحُولٌ (S, Mgh, Msb, K) and (of the latter, Msb) أَذْحَالٌ . (Mgh, Msb, K.) One says, طَلَبَ بِذَحْلِهِ , meaning بِثَأْرِهِ [i. e. He sought to obtain his bloodrevenge, or retaliation ]. (S, Msb.) And عِنْدَهُ ذَحْلِى [ He owes me my blood-revenge ], meaning he is the slayer of my relation. (A in art. ثأر .) [See also a verse of Lebeed cited as an ex. of the preposition بِ .]', 'derived_from_raw_tei', 956);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3e1270f0fba7e071', 'lane_lexicon', 're_lane_2411a640870b2d55', 'sec_lane_3301b15c57a2d67f', 'ذحل', 'e2.raw', 12, 2, 'definition', 'en', 'ذَحَلٌ ذ : see the preceding paragraph.', 'derived_from_raw_tei', 956);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_055eaf1f85ceb682', 'lane_lexicon', 're_lane_249ddd753c8128f4', 'sec_lane_22baed6ae28e35d7', 'ذين', 'e2.raw', 12, 2, 'definition', 'en', 'ذَيْنٌ ذ , (M, TA,) incorrectly said in the K to be ذِيْنٌ , with kesr, (TA,) A vice, fault, defect, or the like, (M, K, TA;) as also ذَانٌ [which belongs to art. ذون ]. (M.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_595cf53dd868afa8', 'lane_lexicon', 're_lane_249ddd753c8128f4', 'sec_lane_d30497c2a56979ea', 'ذين', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَانَهُ ذ , [aor. يَذِينُ , inf. n., app., ذَيْنٌ ,] He blamed, or found fault with, him, or it; like ذَامَهُ . (IAar, T.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b38ecf340a6ec46e', 'lane_lexicon', 're_lane_249ddd753c8128f4', 'sec_lane_75609221625ee356', 'ذين', 'e3.raw', 13, 2, 'definition', 'en', 'مُذَانٌ ذ a dial. var. of مُذَالٌ . (M.) [See the latter in art. ذيل .]', 'derived_from_raw_tei', 993);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_95013dacfae3fa6f', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_321d7c3e8c2a51e8', 'ذاف', 'e7.raw', 17, 2, 'definition', 'en', 'ذُؤَافٌ ذ Death that despatches quickly; (T, M, K;) as also ذُعَافٌ ; thought by Yaakoob to be an instance of permutation. (M.) -b2- See also ذِئْفَانٌ . -A2- And see ذَأْفٌ .', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_75b03c61f828eb3f', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_3f0df8a241843f58', 'ذاف', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَأَفَ ذ , aor. ذَأََ , inf. n. ذَأَفَانٌ , [in the CK ذَأْفان ,] He died: (Moheet, K, TA:) [or he died quickly: see ذَأْفٌ , which is app. an inf. n, as also, perhaps, ذُؤَافٌ .] -A2- ذَأْفَهُ , and ذَأَفَ عَلَيْهِ , inf. n. ذَأْفٌ and ذَأَفٌ , He despatched him; namely, a wounded man; or hastened and completed his slaughter. (M.) -b2- And يَذْأَفُ is also said of poison [app. as meaning It kills quickly ]. (Lth, T.) -b3- مَرَّ يَذْأَفُهُمْ He passed by driving them away, or pursuing them, or destroying them. (M.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e71cb940ef36bd44', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_465963790a46f99e', 'ذاف', 'e6.raw', 16, 2, 'definition', 'en', 'ذِئْفَانٌ ذ (Lth, T, M, K) Poison that kills quickly ( يَذْأَفُ ): (Lth, T:) or simply poison; (M, K;) as also and , (K, TA,) all with ء (TA,) and ذِيفَانٌ (A ''Obeyd, T, M, K) and ذَيْفَانٌ (A ''Obeyd, T, K) and ذَيَفَانٌ and ذُوفَانٌ , (IDrd, K,) and . (T, K: the last, in the TA, without ء .)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a6b2281126c107ea', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_62631f7f4d22e393', 'ذاف', 'e3.raw', 13, 2, 'definition', 'en', 'ذَأْفٌ ذ Quickness of death; (Lth, T, M, K;) as also . (K.) [See 1, first sentence.] -b2- Also an inf. n. of ذَأَفَهُ . (M.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7f46da71f667a52f', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_9d32abcd6b0d8cbc', 'ذاف', 'e2.raw', 12, 2, 'definition', 'en', '7 انذأف ذ His heart broke ( اِنْقَطَعَ فُؤَادُهُ ). (K.) [See its syn. انذعف .]', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5f4663fc3280958f', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_ad5b85c8b34d9197', 'ذاف', 'e4.raw', 14, 2, 'definition', 'en', 'ذَأْفَانٌ ذ : see ذِئْفَانٌ . -b2- Accord. to the K, it signifies also Death: but the correct word seems to be ذَأَفَانٌ , [see 1, first sentence,] as in the Tekmileh. (TA.)', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_01ce9cce109178a0', 'lane_lexicon', 're_lane_255a589c3cf5216d', 'sec_lane_ae8c5af1058cce70', 'ذاف', 'e5.raw', 15, 2, 'definition', 'en', 'ذُؤْفَانٌ ذ : see what next follows.', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_33bd064f7d5a4e92', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_209e7a032a2c6e02', 'رقس', 'e10.raw', 20, 2, 'definition', 'en', 'أَرْقَشُ ذ ; fem. رَقْشَآءُ ; (S, M, &c.;) pl. رُقْشٌ ; (A;) Variegated with duskiness, or dinginess, and blackness; or the like of those two hues; applied to the [species of locust called] جُنْدَب : (M, TA:) and the fem., applied to a serpent ( حَيَّة ), (S, M, IAth, K,) signifies the same: (M:) or speckled with black and white; (S, K;) and so when applied to a she-goat: (IAar, M:) or, applied to a serpent, it signifies one of the viper-species ( أَفْعًى ); because of the lines and specks upon its back: (IAth:) and أَرْقَشُ الأُذُنَيْنِ having his ears variegated with black and white, and the rest of his hair black; applied to a kid. (S.) -b2- Also the fem., A small creeping thing (M, K) that is found in herbs, a variegated and beautiful worm, (M,) resembling [ another small creeping thing called ] the حُمْطُوط , (M, K,) speckled with red and yellow. (IDrd, TA.) Sgh., or his copyist, has corrupted حمطوط into خُطُوط . (TA.) -b3- Also the fem., The شِقْشِقَة [i. e. the bursa faucium, or faucial bag, ] of the camel: (S, A, K:) or the شقشقة of the camel is sometimes رقشآء , having in it a mixture of colours. أُرَيْقِشُ ذ : see رُقَيْشٌ .', 'derived_from_raw_tei', 1136);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1159e4f30859528b', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_2301be320b6b06d3', 'رقس', 'e2.raw', 12, 2, 'definition', 'en', '2 رقّش ذ , inf. n. تَرْقِيشٌ : see 1, in three places. -b2- He embellished his speech: or embellished it with lies: syn. حَسَّنَ , and زَوَّقَ : (TA:) or زَيَّنَ , (A,) and زَوَّرَ , (S, K,) and زَخْرَفَ . (S, A, K.) -b3- Hence, (A, TA,) (tropical:) He made known, divulged, or told, discourse, or conversation, in a malicious or mischievous manner, so as to occasion discord, dissension, or the like; (S, A, TA;) because he who does so embellishes his speech, or embel-lishes it with lies: (A, TA:) he told a calumny to the object thereof. (M.) -b4- (assumed tropical:) He excited discord, dissension, or animosity. (M.) -b5- (assumed tropical:) He blamed, reproved, or chid; syn. عَاتَبَ . (M, TA.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_55b8d18719a8cddb', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_47cee2a068b5461b', 'رقس', 'e1.raw', 11, 2, 'definition', 'en', '1 رَقَشَ ذ , (A,) aor. رَقُسَ , (TK,) inf. n. رَقْشٌ , (S, M, A, K,) He variegated; coloured with two or more colours; decorated; embellished; syn. نَقَشَ ; (S, * A, K; *) and زَيَّنَ ; as also ; (Har p. 57;) and . (So in a copy of the A: [but I think that this is a mistranscription, for رَقَّشَ .]) -b2- He wrote: (M, TA:) and he pointed, or dotted, (As, M, TA,) characters, and writing: (As, TA:) as also , inf. n. تَرْقِيشٌ ; in both senses: and ↓ the latter, he wrote upon, or in, papers or the like, or books. (M, TA.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6af6f2b02cad3bd1', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_d4703c838f9628b0', 'رقس', 'e4.raw', 14, 2, 'definition', 'en', '8 ارتقشوا ذ (assumed tropical:) They became mixed together in fight. (AA, K.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d986efce181c8b66', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_d53f7573ced9c5ac', 'رقس', 'e3.raw', 13, 2, 'definition', 'en', '5 ترقّش ذ He adorned himself: (A, K:) he displayed his beauty, or goodliness. (A, TA.) -A2- See also 1.', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cde42deddf0de906', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_e3f8a352bfe340e9', 'رقس', 'e5.raw', 15, 2, 'definition', 'en', 'رَقَشٌ ذ A good, or beautiful, خَطّ [i. e. character, or handwriting ]. (TA.) [See also رُقَيْشٌ : and see 1.] -A2- Also Food. (M.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0712d1450a9428b0', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_f4c862b6f464bafc', 'رقس', 'e6.raw', 16, 2, 'definition', 'en', 'رَقَشٌ ذ and A colour in which are [ intermixed ] duskiness, or dinginess, and blackness; and the like of those two hues. (M.) [See أَرْقَشُ .]', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2102d7f13dd92efe', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_827e047fdf1dde87', 'رقس', 'e8.raw', 18, 2, 'definition', 'en', 'رَقَاشٌ ذ The serpent: (A, Sgh, K:) app. because of the رُقْشَة [see رَقَشٌ ] upon his back: (TA:) or a serpent speckled with black and white [like حَيَّةٌ رَقْشَآءُ ]. (A.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d8519fa6f99ada5d', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_b2aaf350c65d4e7e', 'رقس', 'e9.raw', 19, 2, 'definition', 'en', 'رُقَيْشٌ ذ dim. of رَقْشٌ , signifying The pointing, or dotting, of characters and writing: (As, TA:) or of أَرْقَشُ ; as also [so in the TA, but in some copies of the K, أُرَيْقِشٌ ]: (AHát, K:) the latter is allowable. (A Hát.)', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3e1f5c731d83d260', 'lane_lexicon', 're_lane_25dd91a03610c41d', 'sec_lane_c2d4dd3606895c47', 'رقس', 'e7.raw', 17, 2, 'definition', 'en', 'رُقْشَةٌ ذ : see what next precedes.', 'derived_from_raw_tei', 1135);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_87e9dfdc1d7f90e4', 'lane_lexicon', 're_lane_3458ccf2154ef8c7', 'sec_lane_0daa8831f6f1f44d', 'ذعن', 'e2.raw', 12, 2, 'definition', 'en', '4 اذعن لَهُ ذ , (S, Msb, * K, &c.,) inf. n. إِذْعَانٌ , (Msb,) He was, or became, quick in obedience to him, or it: (K:) this is its [proper, or primary,] meaning, accord. to Aboo-Is-hák, in the language of the Arabs: (TA:) and he acknowledged, or confessed, to him: (K:) and he was, or became, lowly, or humble, and abject, to him: (S, K:) and he was, or became, tractable, submissive, or manageable, to him; (S, * Msb, * K, TA;) and easy; (K, * TA;) not disobedient; (Msb;) as also , aor. ذَعَنَ , (K,) inf. n. ذَعَنٌ . (TA.) You say, اذعن لِى بِحَقِّى He obeyed me with respect to that [ right, or due, ] which I sought to obtain from him, and hastened to render it: and he acknowledged, or confessed, to me my right, or due, willingly, not against his will; as also أَمْعَنَ . (TA.) Some have used إِذْعَانٌ as meaning Perception, and understanding: but there is no foundation for this in the language of the Arabs; and its being tropical, as some of the sheykhs have endeavoured to show it to be, is improbable. (MF.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3ef4fe6539b18fcc', 'lane_lexicon', 're_lane_3458ccf2154ef8c7', 'sec_lane_d2a457962b903870', 'ذعن', 'e4.raw', 14, 2, 'definition', 'en', 'مِذْعَانٌ ذ : see what next precedes.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fcf42dd0d737ad58', 'lane_lexicon', 're_lane_3458ccf2154ef8c7', 'sec_lane_d7046403b7e110d9', 'ذعن', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَعِنَ ذ : see what next follows.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2730d856ec14e27b', 'lane_lexicon', 're_lane_3458ccf2154ef8c7', 'sec_lane_774af7d8d0517eeb', 'ذعن', 'e3.raw', 13, 2, 'definition', 'en', 'مُذْعِنٌ ذ [act. part. n. of 4]. وَإِنْ يَكُنْ لَهُمُ ٱلْحَقُّ يَأْتُوا إِلَيْهِ مُذْعِنِينَ , in the Kur [xxiv. 48], means [ But if the right be theirs, ] they come to him quickly obedient: (TA:) or [simply] obedient; not compelled against their will: (Fr, TA:) or acknowledging, or confessing, and lowly, or humble: or tractable, submissive, or manageable, and easy. (TA.) , also, signifies Tractable, submissive, or manageable, (Msb, K,) to her leader, (TA.) and easy in the head; (K;) applied to a she-camel: (Msb, K:) and, applied to a man, tractable, submissive, or manageable. (A, TA.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0b3d765598327bb6', 'lane_lexicon', 're_lane_3458ccf2154ef8c7', 'sec_lane_9d0f8716a6596235', 'ذعن', 'e5.raw', 15, 2, 'definition', 'en', 'رَأَيْتُهُمْ مُذْعَانِّينَ ذ is a mistake for رايتهم مُذْعَابِّينَ , meaning I saw them following one another, or doing so uninterruptedly. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ea37060405e4054c', 'lane_lexicon', 're_lane_3f2cd687e20e5ddd', 'sec_lane_2829a4b5d5600870', 'فردوس', 'e3.raw', 13, 2, 'definition', 'en', 'فِرْدَوْسٌ ذ A garden: (S, Msb:) so in the Greek language [ παράδεισος ]: (M:) or a garden comprising everything that is in gardens: (Zj, M, A, O, K:) such is the proper signification; (Zj, M, O;) and so with the people of every language: (Zj, M:) and containing grape-vines: (Fr, O, K:) or a garden in which are grape-vines: (IAmb, M, Msb:) or a place in which are grape-vines: (TA:) or an ample, beautiful garden: (A:) or a garden comprising grape-vines and palm-trees: (Bd in xviii. 107:) or with the Arabs it signifies a valley abounding with herbage, like a garden: (M:) or a valley, (Zj, Msb,) or valleys, (O, K,) producing various sorts of plants or herbage: (Zj, O, Msb, K:) in the K, for الأَوْدِيَةُ الَّتِى تُنْبِتُ , we should read مِنَ الأَوْدِيَةِ الَّتِى تُنْبِتُ ; (TK;) [or rather, مِنَ الأَوْدِيَةِ مَا يُنْبِتُ , as in the Msb:] or a meadow; syn. رَوْضَةٌ : (Seer, M:) and the greenness of grapes ( أَعْنَاب ), (so in a copy of the M,) or of herbs ( أَعْشَاب ): (so in the TA:) masc. and fem.: (Msb:) sometimes the latter; (K;) as in the Kur xxiii. 11, because, by الفِرْدَوْسَ is there meant الجَنَّةَ : (O, TA:) it is an Arabic word, (S, O, Msb, K,) accord. to Fr, (S, O, Msb,) occurring in a verse cited voce ثَوَابٌ , which is by Hassán Ib فُرْدُوسٌ ذ Increase ( نَزَل , in the CK نُزُل ,) that is in طَعَام [i. e. wheat ]: (O, K:) mentioned by IDrd, as heard from some persons of ElBahreyn. (O.)', 'derived_from_raw_tei', 2365);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ab8a1e2724a65993', 'lane_lexicon', 're_lane_3f2cd687e20e5ddd', 'sec_lane_e0c80028b14f0b66', 'فردوس', 'e1.raw', 11, 2, 'definition', 'en', 'Q. 1 فَرْدَسَهُ ذ , (O, K,) inf. n. فَرْدَسَةٌ , (Kr, M, O,) He threw him down, prostrate, on the ground, (Kr, M, O, K,) in an evil, or abominable, manner: (Kr, M, O:) and flung him upon the ground; lit., smote with him the ground. (O, K.) -b2- And فَرْدَسَ الجُلَّةَ He filled, or stuffed, compactly, the [ receptacle for dates, termed ] جُلَّة . (AA, O, * K.)', 'derived_from_raw_tei', 2365);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d982dabd374242ea', 'lane_lexicon', 're_lane_3f2cd687e20e5ddd', 'sec_lane_f1cecac210fcd2f9', 'فردوس', 'e2.raw', 12, 2, 'definition', 'en', 'فَرْدَسَةٌ ذ Width; amplitude: (M, O, Msb, K:) whence is derived the word فِرْدَوْسٌ , (Msb, K,) accord. to Fr. (Msb.)', 'derived_from_raw_tei', 2365);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0ba8c254cb9b3aa3', 'lane_lexicon', 're_lane_3f2cd687e20e5ddd', 'sec_lane_85acb2156bc3a0eb', 'فردوس', 'e5.raw', 15, 2, 'definition', 'en', 'فُرَادِسٌ ذ A man big in the bones. (Ibn-''Abbád, O, K.)', 'derived_from_raw_tei', 2365);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_aa9305815eda7201', 'lane_lexicon', 're_lane_3f2cd687e20e5ddd', 'sec_lane_b2569100769bd01b', 'فردوس', 'e6.raw', 16, 2, 'definition', 'en', 'مُفَرْدَسٌ ذ A trellised grape-vine; syn. مُعَرَّشٌ . (Lth, S, M.) -b2- A wide breast. (O, K.) -b3- Widebreasted; having a wide breast. (M.) -b4- And [A thing] filled, or stuffed, compactly. (O.)', 'derived_from_raw_tei', 2365);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_22a6c640a345dfde', 'lane_lexicon', 're_lane_41760600e22cf6a1', 'sec_lane_9ae49273c85e8eb3', 'ذاك', 'e1.raw', 11, 2, 'definition', 'en', 'ذَاكَ ذ : see art. ذا ; and ك as a letter of allocution.', 'derived_from_raw_tei', 950);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bf37d9c12e152ede', 'lane_lexicon', 're_lane_4aa162d8bc83f0f7', 'sec_lane_5eff837c3d9a493d', 'نقمه', 'e2.raw', 12, 2, 'definition', 'en', 'نَقاَهَةٌ ذ [ Convalescence; ] the slight degree of health that immediately succeeds sickness. (TA, art. برأ .)', 'derived_from_raw_tei', 3037);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b8c96c8e42695aa2', 'lane_lexicon', 're_lane_4aa162d8bc83f0f7', 'sec_lane_6a3671620fc4878d', 'نقمه', 'e1.raw', 11, 2, 'definition', 'en', '1 نَقَهَ ذ He recovered, but not completely, his health and strength: (TA:) or he became convalescent; or sound, or healthy; at the close of his disease: (S:) or sound, or healthy, but was yet weak. (K.) See بَرِئَ .', 'derived_from_raw_tei', 3037);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bc6e869761711ebd', 'lane_lexicon', 're_lane_4b797dc89ef3fa6d', 'sec_lane_0cd831314eeb2126', 'ذير', 'e3.raw', 13, 2, 'definition', 'en', 'ذِيَارٌ ذ Fresh camels'' or similar dung ( بَعَرَ ), [ mixed with dust, or earth, ] with which a she-camel''s teats are smeared, (T, S, M, *) in order that the young one may not such her, (S, M,) and that the pieces of wood which are bound upon her udder to prevent her young one from sucking may not make any impression upon her; (T, M;) i. q. ذِئَارٌ : or dung ( سِرْقِين ) before mixed with dust or earth is called خُثَّةٌ : and when mixed, : and when the teats are smeared with it, ذِيَارٌ . (Lth, K.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_04e05a49c7fac9c7', 'lane_lexicon', 're_lane_4b797dc89ef3fa6d', 'sec_lane_389df2cdd3c20c7b', 'ذير', 'e1.raw', 11, 2, 'definition', 'en', '2 ذيّر ذ , (K,) inf. n. تَذْيِيرٌ , (S,) He smeared a she-camel''s teats with ذِيَار , (S, K,) in order that the young one might not suck her. (S.) -b2- And ذيّر النَّاقَةَ He bound the she-camel''s udder with a صِرَار [q. v.], in order that the pieces of wood bound upon her udder to prevent her young one from sucking her might not make any impression upon her. (K, * TA.) [But see ذِيَارٌ , which indicates that the true meaning is, He smeared the she-camel''s teats with ذِيَار in order that the pieces of wood above mentioned might not make any impression upon them. ] -b3- ذُيِّرَ فُوهُ , inf. n. تَذْيِيرٌ , His (a man''s, S) teeth became black. (Lth, S, K.)', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2f07604af1c77263', 'lane_lexicon', 're_lane_4b797dc89ef3fa6d', 'sec_lane_e780ed69f7830f38', 'ذير', 'e2.raw', 12, 2, 'definition', 'en', 'ذِيرَةٌ ذ : see ذِيَارٌ .', 'derived_from_raw_tei', 990);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_04899f6b941234b5', 'lane_lexicon', 're_lane_4d04d5ab822f61cf', 'sec_lane_c799788d52fa6f3f', 'ذور', 'e1.raw', 11, 2, 'definition', 'en', 'ذَارَتْ ذ for ذَارَّتْ or ذَآءَرَتْ : see 3 in art. ذر .', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a4d9f20575f5b08d', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_2cac6bb50a7d117f', 'نام', 'e6.raw', 16, 2, 'definition', 'en', 'اِمْرَأَةٌ نَؤُومُ الضُّحَى ذ i. q. رَقُودُ الضحى [which see]. (A, art. رقد .)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3ec11cfd70fd2a2d', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_3f9a8abd423f5617', 'نام', 'e8.raw', 18, 2, 'definition', 'en', 'أَنْوَمُ ذ [ More, or most, prone to sleep ]. (A, art. فهد .)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2b49866d1aeb79eb', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_4e48f0bdd9b69428', 'نام', 'e3.raw', 13, 2, 'definition', 'en', '3 نَاوَمْتُهُ فِى شِعَارٍ وَاحِدٍ ذ [ I slept with him in one under-garment ]. (S, art. شعر .)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f9902a128d6c127e', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_516dafc129a8fa85', 'نام', 'e7.raw', 17, 2, 'definition', 'en', 'نَائِمٌ ذ (tropical:) Lying; as opposed to sitting and standing. (Mgh.)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_32ee8a444675bf1d', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_ed6a7dab817b277e', 'نام', 'e1.raw', 11, 2, 'definition', 'en', '1 نَامَتْ رِجْلُهُ ذ (assumed tropical:) I. q. خَدِرَتْ [ His leg, or foot, became benumbed, or torpid ]. (TA in art. بسر .) -b2- نَامَ (assumed tropical:) It (a woman''s anklet) ceased to sound, by reason of the fulness of the leg: like as one says [in the contr. case], استيقظ . (TA in art. يقظ .) -b3- نَامَ has for its inf. ns. نَوْمٌ and مَنَامٌ . (Msb.) -b4- نَامَ الثَّوْبُ i. q. رَقَدَ [q. v.] (A, art. رقد .) -b5- نَامَتِ السُّوقُ i. q. رَقَدَت [q. v.] (Th, in TA, art. رقد .) -b6- نَامَ (tropical:) He lay; as opposed to he sat and he stood. See نَائِمٌ . -b7- نَامَ عَنْ حَاجَتِهِ He cared not for the object of his want, neglected it. (Msb.)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e41bba9689fca335', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_f1c4335af6a9b94e', 'نام', 'e2.raw', 12, 2, 'definition', 'en', '2 نَوَّمَ ذ and (assumed tropical:) It benumbed, or torpified: see نَامَتْ رِجْلُهُ .', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2413238c987bcf3f', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_72e07bac4940698f', 'نام', 'e5.raw', 15, 2, 'definition', 'en', '10 اِسْتَنَامَ إِليْهِ ذ He trusted to him, and became quiet, or easy, in mind; relied upon him. (S, K.)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7c71cee48490d17a', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_7b9d50246ae52480', 'نام', 'e4.raw', 14, 2, 'definition', 'en', '3 نَاوَمْتُهُ فِى شِعَارٍ وَاحِدٍ ذ [ I slept with him in one under-garment ]. (S, art. شعر .)', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a4a7c7f5e30e70c8', 'lane_lexicon', 're_lane_4d9545ec73e4ba54', 'sec_lane_b73961ec808b569f', 'نام', 'e9.raw', 19, 2, 'definition', 'en', 'مَنَامٌ ذ Time of sleep. (Jel, xxxix. 43.) See also 1.', 'derived_from_raw_tei', 3040);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_420d86be1c4e374a', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_04d595b63a6407a2', 'ذوي', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَوَى ذ , (ISk, T, S, M, Msb, K,) aor. يَذْوِى , (ISk, S, &c.,) inf. n. ذَىٌّ , (T,) or ذُوِىٌّ , (ISk, S, K,) or both; (M, Msb;) and ذَوِىَ , (T, S, M, K,) used by some of the Arabs, but bad, (T,) disallowed by ISk, but said by AO on the authority of Yoo to be a dial. var., (S,) aor. يَذْوَى ; (T, K;) said of a branch, or twig, (T, M, Msb,) or of a herb, or leguminous plant, (S, K,) It withered; lost its moisture; or became thin, or unsubstantial, after being succulent; syn. ذَبَلَ : (S, M, Msb, K:) it dried up: (T, A:) it obtained not moisture sufficient for it, or was marred by the heat, and in consequence withered, and became weak: (T:) in the dial. of the people of Beesheh, ذَأَى . (Lth, T.) -b2- [Hence,] ذَوَتْ سَكِينَتُهُ (assumed tropical:) [ His calmness, or gravity, ] ceased. (Har p. 109.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_37e71ec1df069a0f', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_064f4793e08d8ae6', 'ذوي', 'e2.raw', 12, 2, 'definition', 'en', '4 اذواهُ ذ , said of heat, (S, Msb, K,) or of want of irrigation, (M,) It withered it; caused it to wither, or lose its moisture; (S, M, Msb, K;) namely, a herb, or leguminous plant, (S, K,) or a branch, or twig. (M, Msb.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9a97094fa7b93c92', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_1513366b811c5e64', 'ذوي', 'e5.raw', 15, 2, 'definition', 'en', 'ذَوَاةٌ ذ sing. [or rather n. un.] of ذَوًى [q. v.]', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3f06860cb02d8309', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_2bdffd109c1a153b', 'ذوي', 'e6.raw', 16, 2, 'definition', 'en', 'ذَوَاتٌ ذ pl. of ذَاتٌ , fem. of ذُو , q. v.', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d3ff9b1c1e9203bc', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_572639d7665b02ea', 'ذوي', 'e7.raw', 17, 2, 'definition', 'en', 'ذَاوٍ ذ Withering, or withered; losing, or having lost, its moisture. (S, TA.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d700819e416e724b', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_f2fda8c7423fa001', 'ذوي', 'e4.raw', 14, 2, 'definition', 'en', 'ذِوًى ذ : see what next precedes.', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d825ab57f655aa28', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_63d22b1e772a9f49', 'ذوي', 'e3.raw', 13, 2, 'definition', 'en', 'ذَوًى ذ The skins of grapes: (IAar, T:) a pl. [or rather a coll. gen. n.] of which the sing. [or rather the n. un.] is ذَوَاةٌ : (Kr, M:) [or] this latter signifies the skin, or husk, or rind, of the grape, (AA, T, Kr, M, K,) and of wheat ( الحِنْطَة ), (AA, T, and so in some copies of the K,) or of the colocynth ( الحَنْظَلَة ), (Kr, M, and so in some copies of the K,) and of the melon: (AA, T, Kr, M, K:) and so [ دَوَاةٌ ] with the unpointed د . (TA.) -A2- Also ذَوًى , (IAar, T,) or , (K,) Weak, (IAar, T,) or small, or young, (K,) ewes. (IAar, T, K.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1830897f9baeeeea', 'lane_lexicon', 're_lane_508538c24a0c2f88', 'sec_lane_85d4dfa1f52bbba2', 'ذوي', 'e8.raw', 18, 2, 'definition', 'en', 'ذَائِكَ ذ i. q. ذٰلِكَ : so in the phrase ذَائِكَ الرَّجُلُ [ That man ]: (K, TA:) a dial. var., or a mispronunciation. (TA.)', 'derived_from_raw_tei', 989);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cdd0c9b690024d7a', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_4b3cb464dae294e0', 'ذقن', 'e9.raw', 19, 2, 'definition', 'en', 'ذَقُونٌ ذ A she-camel that relaxes her chin [ so as to make her lower lip hang down ] in going along: (S, K:) or that moves about her head in going along: (JK:) or that stretches her steps, and moves about her head, by reason of strength, and briskness, liveliness, or sprightliness, in going along: (A, TA:) pl. ذُقُنٌ : (TA:) and , applied to a she-camel, signifies the same as ذَقُونٌ . (IAar, TA.) -b2- دَلْوٌ ذَقُونٌ (assumed tropical:) A bucket [ of leather ] which one has sewed in such a manner that its lip inclines on one side: (S, K:) or a large bucket inclining on one side: (Er-Rághib, TA:) and ذَلْوٌ a bucket with an inclining lip: (IB, TA:) and دَلْوٌ a bucket that has had an addition made to one of its two sides, and consequently inclines on one side. (JK.)', 'derived_from_raw_tei', 968);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a0f187041fc41f53', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_dc49dac13ead43f0', 'ذقن', 'e5.raw', 15, 2, 'definition', 'en', 'ذِقْنٌ ذ A decrepit, old and weak, or extremely aged, man. (K.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1862241e932c3edb', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_e1c74c425f15cc4a', 'ذقن', 'e4.raw', 14, 2, 'definition', 'en', '4 اذقن ذ is said by Golius, as on the authority of the KL, to signify Opem tulit in tollenda re: but the word explained in the KL as signifying the doing this is the inf. n. of ازقن , not of اذقن .]', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ee9003be5f0688d4', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_ef43d1b931c3af86', 'ذقن', 'e3.raw', 13, 2, 'definition', 'en', '3 ذاقنهُ ذ He straitened him. (K.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f80e7d291e3b450d', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_7101aa5f12607907', 'ذقن', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَقَنَهُ ذ , (JK, S, A, K,) aor. ذَقُنَ , (JK,) inf. n. ذَقْنٌ , (TK,) He struck his ذَقَن [or chin ]: (JK, S, A, K:) or he struck him on the back of his neck, or on his head at the part next the back of the neck, with the inside of his hand; syn. قَفَدَهُ . (K, TA. [In the CK, erroneously, فَقَدَهُ .]) And He struck him, or beat him, with a staff, or stick. (JK.) -b2- ذَقَنَ عَلَى يَدِهِ , (K,) or على عَصَاهُ , (JK, K,) He put his ذَقَن [or chin ] upon his hand, or upon his staff, or stick, (JK, K, TA,) and leaned [ upon it ]: (TA:) and ذَقَنَ بِسَوْطِهِ [ He leaned his chin upon his whip ]: (TA:) as also . (K.) -A2- ذَقِنَتِ الدَّلْوُ , (JK, S, K,) aor. ذَقَنَ , (JK, K,) inf. n. ذَقَنٌ , (JK,) The bucket was, or became, such as is termed ذَقُونٌ (S, K) or ذَقْنَآءُ . (JK.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2db6719f946d39f7', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_ac9639105ce2d4ef', 'ذقن', 'e10.raw', 20, 2, 'definition', 'en', 'الذَّاقِنَةُ ذ The part beneath the ذَقَن [or chin ]: (K:) or the part, of the breast, that is reached by the ذَقَن : or the ذَقَن [ itself ]: (TA:) or the head of the حُلْقُوم [or windpipe ]: (K:) or the prominent extremity of the حلقوم : (S, K:) thus explained by A''Obeyd and AA in the saying of ''Áïsheh, “ [The Prophet died] between my حَاقِنَة and my ذَاقِنَة : ” (TA: [see الحَاقِنَةُ :]) or the تَرْقُوٓة [ or collar-bone; or it may here mean the fore part of the throat, next the chest; or the uppermost part of the chest ]: (K:) but this, in the M, is an explanation of الحَاقِنَةُ : (TA:) or the lower part of the belly, next the navel: (K:) but this, also, is given as an explanation of الحاقنة , by ISd and by Z: (TA:) or the pit of the uppermost part of the breast, or chest: or the upper part of the belly: (K:) and the stomach: (JK:) pl. ذَوَاقِنُ . (S, TA.) [See also الحَاقِنَةُ .] Hence the prov., لَأُلْحِقَنَّ حَوَاقِنَكَ بَذَوَاقِنِكَ [explained in art. حقن ]: الذَّوَاقِنُ , accord. to Az, means the lower أَذْقَنٌ ذ A man long in the ذَقَن [or chin ]: and so [the fem.] ذَقْنَآءُ applied to a woman. (K.) -b2- And A man having the two sides of the mouth inclining, or wry. (JK.) -b3- And [hence, app.,] ذَقْنَآءُ , (K, TA,) applied to a woman, by way of comparison, (TA,) (tropical:) Having the جَهَاز [or pudendum ] inclining, or wry. (K, TA.) -b4- دَلْوٌ ذَقْنَآءُ : see ذَقُونٌ .', 'derived_from_raw_tei', 968);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_58dc9d76dfd54592', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_acf483c1f9eefc39', 'ذقن', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَقَنَهُ ذ , (JK, S, A, K,) aor. ذَقُنَ , (JK,) inf. n. ذَقْنٌ , (TK,) He struck his ذَقَن [or chin ]: (JK, S, A, K:) or he struck him on the back of his neck, or on his head at the part next the back of the neck, with the inside of his hand; syn. قَفَدَهُ . (K, TA. [In the CK, erroneously, فَقَدَهُ .]) And He struck him, or beat him, with a staff, or stick. (JK.) -b2- ذَقَنَ عَلَى يَدِهِ , (K,) or على عَصَاهُ , (JK, K,) He put his ذَقَن [or chin ] upon his hand, or upon his staff, or stick, (JK, K, TA,) and leaned [ upon it ]: (TA:) and ذَقَنَ بِسَوْطِهِ [ He leaned his chin upon his whip ]: (TA:) as also . (K.) -A2- ذَقِنَتِ الدَّلْوُ , (JK, S, K,) aor. ذَقَنَ , (JK, K,) inf. n. ذَقَنٌ , (JK,) The bucket was, or became, such as is termed ذَقُونٌ (S, K) or ذَقْنَآءُ . (JK.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_539d9588b1b8509c', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_b3351e381d28a4fe', 'ذقن', 'e6.raw', 16, 2, 'definition', 'en', 'ذَقَنٌ ذ [The chin; ] the place where the لَحْيَانٌ [here meaning the two lateral portions of the lower jaw ] combine, (JK, S, Msb, K,) at their lower part: (K:) it is of a man (S, Msb) [and of a beast]: also pronounced with kesr (ISd, K) to the ذ [i. e. ]: (TK:) of the masc. gender, (Lh, K,) only: (Lh, TA:) pl. أَذْقَانٌ , (Msb, K,) a pl. of pauc.; and the pl. of mult. is ذُقُونٌ . (Msb.) Hence, (K,) مُثْقَلٌ ٱسْتَعَانَ بِذَقَنِهِ [ A heavily-burdened, or overburdened, camel sought to help himself to rise by means of his chin ]: (S, M, K:) a prov., applied to a low, base, or mean, and weak man, who seeks to help himself by means of another man like himself; (S;) or to him who seeks to help himself by means of one who has no power of defending, and by means of one more low, base, or mean, and weak, than he: (M:) or to him who seeks to help himself by means of one less than he: (K:) originating from the fact that a camel laden with a heavy load, and unable to rise, bears with his chin upon the ground. (S, K.) You say also, خِرُّوا لِأَذْقَانِهِمْ [ They fell down prostrate, with their chins to the ground: see the Kur xvii. 108 and 109]: and [hence,] عَصَفَتْ رِيحٌ فَخَرَّتِ الأَشْجَارُ لِلْأَذْقَانِ (tropical:) [ A wind blew vio ذِقَنٌ ذ : see the next preceding paragraph, first sentence.', 'derived_from_raw_tei', 968);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e7106ab20841c14b', 'lane_lexicon', 're_lane_50c412e8a32cdd37', 'sec_lane_b8f84a5532a7f8a0', 'ذقن', 'e8.raw', 18, 2, 'definition', 'en', 'ذَقَنَى ذ : see the paragraph next following.', 'derived_from_raw_tei', 968);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_07037701a82ab88e', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_0a085aa151b8963c', 'مراء', 'e3.raw', 13, 2, 'definition', 'en', '5 تمرّأ ذ He affected, or endeavoured to acquire, ( تَكَلَّفَ ,) manliness, مُرُوْءَة : (AZ, S, K:) accord. to some, he became possessed of that quality. (TA.) -b2- تمرّأ بِهِمْ He sought to acquire the character of manliness ( مُرُوْءَة ) by disparaging them and vituperating them. (ISk, S, K.) -b3- لَا يَتَمَرَّأْ أَحَدُكُمْ بِالدُّنْيَا (a trad.) [app., Let not any one of you delight himself in the present world ]: but accord. to one relation, it is لَا يَتَمَرْأَى , from الرُّؤْيَةُ : [see art. رأى ]. (TA.) [See also تَهَنَّأَ .]', 'derived_from_raw_tei', 2702);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7dccac0545d62607', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_11ae4bb2f95da8e1', 'مراء', 'e4.raw', 14, 2, 'definition', 'en', '5 تمرّأ ذ He affected, or endeavoured to acquire, ( تَكَلَّفَ ,) manliness, مُرُوْءَة : (AZ, S, K:) accord. to some, he became possessed of that quality. (TA.) -b2- تمرّأ بِهِمْ He sought to acquire the character of manliness ( مُرُوْءَة ) by disparaging them and vituperating them. (ISk, S, K.) -b3- لَا يَتَمَرَّأْ أَحَدُكُمْ بِالدُّنْيَا (a trad.) [app., Let not any one of you delight himself in the present world ]: but accord. to one relation, it is لَا يَتَمَرْأَى , from الرُّؤْيَةُ : [see art. رأى ]. (TA.) [See also تَهَنَّأَ .]', 'derived_from_raw_tei', 2702);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bb1ecd509b98e0df', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_3c01b90aae737a57', 'مراء', 'e10.raw', 20, 2, 'definition', 'en', 'ٱمْرَأٌ ذ and ٱمْرَأَةٌ &c: see مَرْءٌ .', 'derived_from_raw_tei', 2703);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_beff0d21290c741d', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_61b7069069a40792', 'مراء', 'e9.raw', 19, 2, 'definition', 'en', 'مُرُوْءَةٌ ذ and مُرُوَّةٌ : see مَرُؤَ', 'derived_from_raw_tei', 2703);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_278248392c4148a0', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_d289d12d19cff248', 'مراء', 'e7.raw', 17, 2, 'definition', 'en', 'مَرِىْءٌ ذ [The œsophagus, or gullet of a slaughtered camel, or sheep or goat, (S,) and of a man, (Zj, in his Khalk el-Insán,) the canal through which the food and drink pass; (S, K;) the head of the stomach; (K;) contiguous, (S,) or adherent (K) to the حُلْقُوم [or windpipe ]; (S, K;) through which the food and drink pass, and by which they enter: (TA;) pl. [of pauc.] أَمْرِئَةٌ (K) and [of mult.] مُرُؤٌ . (S, K.) It is also written مَرِىٌّ . (TA.) -b2- يَأْتِينا فِى مِثْلِ مَرِىْءِ النَّعَامِ [ It comes to us as it were through the gullet of the ostrich ]: a proverbial expression, from a trad., alluding to paucity of food; the ostrich being particularized because of the slenderness of its neck, whence is inferred the narrowness of its gullet. (TA.) -b3- Wholesome, &c. (See مَرُؤَ .) -b4- هَنِيْئًا مَرِيْئًا : see art. هنأ and see 1 in the present art. -b5- غَيْثٌ مَرِىْءٌ [ A rain productive of good result ]. (TA.) -b6- كَلَأٌ مَرِىْءٌ Wholesome herbage. (K.) -b7- أَرْضٌ مَرِيْئَةٌ A land salubrious in its air. (K.) -b8- مَرَآءَةٌ ذ : see مَرُؤَ .', 'derived_from_raw_tei', 2703);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d69e3a77253bf4a9', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_edb4fabe24de3e21', 'مراء', 'e1.raw', 11, 2, 'definition', 'en', '1 مَرُؤَ الطَّعَامُ ذ , aor. مَرُاَ , inf. n. مَرَآءَةٌ , epithet مَرِىْءٌ ; and مَرِئَ , (S, K,) and مَرَأَ , aor. مَرَاَ ; (K;) and ; (TA;) The food was, or became, wholesome, or approved in its result: (Z:) or easy to swallow, and wholesome, or approved in its result: (K:) or easy to swallow, not attended by trouble: or quick in digesting. (Z.) It is said in the Keshsháf, on ch. iv., v. 3, of the Kur, that هَنِىْءٌ and مَرِىْءٌ are two epithets from هَنَأَ الطَّعَامُ and مَرَأَ , “ the food was easy to swallow; not attended by trouble: ” or the former epithet signifies “ pleasant, or productive of enjoyment, to the eater; ” and the latter, “ wholesome, or approved in its result: ” or the former, food or drink that is “ not succeeded by harm, even after its digestion; ” and the latter, that which is “ quick in digesting. ” (TA.) In conjunction with هَنَأَنِى , one says مَرَأَنِى ( هنأنى الطَّعَامُ ومرأنى ), (Fr. S, K,) aor. مَرَاَ , inf. n. مَرْءٌ ; (Akh, S;) and in conjunction with هَنِئَنِى , مَرِئَنِى 4 هٰذَا يُمْرِئُ الطَّعَامَ ذ [ This makes the food wholesome, &c. ] (AZ.) (See مَرُؤَ .)', 'derived_from_raw_tei', 2702);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5642ba1c2a410634', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_ff94d34949c78605', 'مراء', 'e5.raw', 15, 2, 'definition', 'en', 'مَرْءٌ ذ and (S, K) and (K) A man, or human being; syn. إِنْسَانٌ : (K:) or a man as opposed to a child or a woman; syn. رَجُلٌ . (S, K.) You say مَرْءٌ in the nom., مَرْءًا in the acc., and مَرْءٍ in the gen., (S,) agreeably with analogy. (TA.) And some say مُرْءٌ in the nom., مَرْءًا in the acc., and مِرْءٍ in the gen.; doubly declining the word. (TA, and some copies of the S.) And is said to be of the dial. of Hudheyl. It is said that no pl. is formed from مرء ; but مَرْؤُونَ occurs as its pl. in the following words of a trad.; أَحْسِنُوا أَمْلَاءَكُمْ أَيُّهَا المُرْؤُونَ [ Amend your manners, O ye men! ]; and in the saying of Ru-beh, أَيْنَ يُرِيدُ المرؤون [ Whither do the men desire to go? ]. (TA.) It forms a dual; مَِرْآنِ : they say هُمَا مِرْآنِ صَالِحَانِ [ They are two just men ] (S) in the dial. of Hudheyl. (TA.) It also forms a dim., مُرَىْءٌ , fem. مُرَيْئَةٌ . (S.) -b2 مَرَأٌ ذ A giving of food on the occasion of building a house, or marrying. (TA.)', 'derived_from_raw_tei', 2703);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_788bf0a648160c65', 'lane_lexicon', 're_lane_587b4f435b6a0d77', 'sec_lane_7a8eb71accc3cab7', 'مراء', 'e11.raw', 21, 2, 'definition', 'en', 'مُمْرِئٌ ذ act. part. n. of 4, Wholesome food. (S.) [See 4, and مَرِىءٌ .]', 'derived_from_raw_tei', 2703);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bade73292c9216b3', 'lane_lexicon', 're_lane_590bff0ff239d616', 'sec_lane_d249035bbe295f00', 'ذلف', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَلِفَ ذ , aor. ذَلَفَ , inf. n. ذَلَفٌ , said of a nose, It was short and small: (M, Msb:) or short in the bone, and small in the tip, or lower portion: or ذَلَفٌ is like خَنَسٌ [inf. n. of خَنِسَ , q. v.]: (M:) or the verb means it was small, and even in the tip, or lower portion: (S, * K:) or small and slender: or thick and even in the lower extremity; (M, K;) or, as some say, it had in it what resembled a pit, or depression; (M;) not being very thick ( لَيْسَ بِجِدِّ غَلِيظٍ ): (M, K: * [in the latter I find لَيْسَ بِحَدٍّ غَلِيظٍ , which I doubt not to be a mistranscription:]) or it was short in the tip, or lower portion, and even in the bone, without prominence. (M.) And said of a man, He had a nose such as is above described. (S, K.)', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_13cddc4f363e1970', 'lane_lexicon', 're_lane_590bff0ff239d616', 'sec_lane_8749219097ccb278', 'ذلف', 'e2.raw', 12, 2, 'definition', 'en', 'أَذْلَفُ ذ A man having a nose such as is described above: (S, Msb, K:) or having a short and slender nose: (Mgh:) fem. ذَلْفَآءُ : (S, Mgh, Msb, K:) pl. ذُلْفٌ . (S, K.) And A nose such as is described above. (K.) -b2- And ذُلْفٌ , applied to sands, (assumed tropical:) Even and compact; as also دُكٌّ . (AHn, M.)', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1d0c5dd0ad78316b', 'lane_lexicon', 're_lane_5a143d87b14580a1', 'sec_lane_4c252be3862790cb', 'كس', 'e1.raw', 11, 2, 'definition', 'en', '1 كَسَأ ذ , aor. كَسَسَ , (S, K,) inf. n. كَسْءٌ , (TA,) He, or it, pursued, or followed, another, (S, K,) as one follows a party which he has put to flight: like كَسَعَ . (S.) -b2- كَسَأَ , (K,) inf. n. كَسْءٌ , (TA,) He urged on a beast of carriage. in the track, or at the heels, of another. (K.) -A2- كَسَأَ , (K,) inf. n. كَسْءٌ , (TA,) He overcame a party in litigation or the like. (K.) -A3- كَسَأَ (perhaps a mistake for كَشَأَ , TA,) He smote a person with a sword. (K.)', 'derived_from_raw_tei', 2608);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_896f84d8691bb0b5', 'lane_lexicon', 're_lane_5a143d87b14580a1', 'sec_lane_567d306c273a1471', 'كس', 'e2.raw', 12, 2, 'definition', 'en', 'كَسْءٌ ذ inf. n. of 1. q. v. -A2- مرَّ كَسْءٌ مِنَ اللَّيْلِ A part of the night passed. (K.)', 'derived_from_raw_tei', 2608);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_db60dd8cfdbca166', 'lane_lexicon', 're_lane_5a143d87b14580a1', 'sec_lane_b530d24d239de788', 'كس', 'e5.raw', 15, 2, 'definition', 'en', 'كُسُوْءٌ ذ : see كُسْءٌ .', 'derived_from_raw_tei', 2608);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fd31232d29a59e95', 'lane_lexicon', 're_lane_5a143d87b14580a1', 'sec_lane_c9ca85446b4453fd', 'كس', 'e3.raw', 13, 2, 'definition', 'en', 'كُسْءٌ ذ and The hinder, or latter, part of anything: pl. أَكْسَاءٌ . (S, K.) -b2- كُسْءٌ الشَّهْرِ , and , The latter part of the month; its last ten days, or about that period. (TA.) -b3- جَاءَ فِى كُسْءِ الشَّهْرِ , and عَلَى كُسْئِهِ , He came in the latter part, or end, of the month. (TA.) -b4- جَاءَ عَلَى كُسْءِ الشَّهْرِ , and على أَكْسَائِهِ , and جِئْتُكَ عَلَى , [in the TA written, app. by a mistake of the transcriber, على كساءه , and فِى كُسَائِهِ , [so in the TA,] He came, and I came to thee, at the end of the month, after the whole month had passed. (TA.) -b5- جِئْتُ فِى أَكْسَآءِ القَوْمِ I came among the latter of the people. (TA.) -b6- مَرُّوا فِى أَكْسَآءِ المُنْهَزِمِينَ , and على أَكْسَائِهِمْ , They went at the heels of the routed party. (TA.) رَكِبَ كُسْأَهُ كُسَآءٌ ذ : see كُسْءٌ .', 'derived_from_raw_tei', 2608);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a2872722e89af3f1', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_1b8c2f6991282d0f', 'ذود', 'e4.raw', 14, 2, 'definition', 'en', 'ذَوْدٌ ذ A number of camels, from three to ten: (Lth, AZ, As, T, S, M, A, Mgh, Msb, K:) this is the meaning that is of best repute: (TA:) [in this explanation in the T from AZ, and in the K, the nouns of number are mase.; and so in the next here following: in the rest, fem.:] or from three to ten: and a little more: (IAar, M:) or from three to nine: (M, L:) or from three to fifteen: or from three to twenty; (M, L, K;) and a little more: (L:) or from three to thirty: (M, L, K:) or from two to nine: (M, Mgh, L, K:) [said to be] applied only to females: (Lth, A''Obeyd, T, M, Mgh, Msb, K:) so in the Bári'': (Msb:) and it is of the fem. gender; (T, S, M, Msb, K;) i. e., the word is fem.: (MF:) but its dim. is [ ,] without ة ; contr. to analogy: (M:) the word ذَوْدٌ is a pl., (M, K,) meaning a quasipl. n., (MF,) having no sing. (S, M, K) of the same root: (S:) or a sing.; (K;) and its pl. is أَذْوَادٌ : (T, S, M, A, Msb, K:) or a sing. and pl.: (M, K:) the Arabs said ثَلَاثُ أَذْوَادٍ and ثَلَاثُ ذَوْدٍ and so with all the inferior ns. of number, making ذَوْد a substitute for أَذْوَاد : and they also said ثَلَاثُ ذَوْدٍ meaning thereby three she-camels. (M, L.) It is said in a trad., لَيْسَ فِيمَا دُونَ خَمْسِ ذُوَيْدٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e4678da3d8f3babf', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_da6aee4a92331314', 'ذود', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَادَ ذ , (M, A,) first pers. ذُدْتُ , (T, S,) aor. يَذُودُ , (T, A,) inf. n. ذَوْدٌ , (T,) or ذِيَادٌ , (S,) or both, (M, A, K,) He drove: (S, M, K:) he drove away: (T, S, M, A, K:) and he repelled. (M, K.) You say, ذَدْتُ الإِبِلَ I drove the camels: (S:) and I drove them away: (T, S:) and [so , for] تَذْوِيدٌ signifies the same as ذِيَادٌ . (S.) And ذاد الإِبَلِ عَنِ المَآءِ , (A, Msb,) aor. يَذُودُ , inf. n. ذَوْدٌ and ذِيَادٌ , He (the pastor) [ drove away, or repelled, or] kept back, or debarred, the camels from the water; or prevented them from coming to it. (Msb.) And ذادهُ عَنْ كَذَا , (A,) and ذُدْتُهُ , (S,) He, and I, drove him away from such a thing. (S, A. [And the like is said in the M.]) And ذاد عَنِ الحَرَمِ He repelled from, or defended, the sacred territory. (L.) And الثَّوْرُ يَذُودُ عَنْ نَفْسِهِ بِمِذْوَدِهِ , i. e. (tropical:) [ The bull repels from, or defends, hims 2 ذَوَّدَ see above.', 'derived_from_raw_tei', 987);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_afa842507e5e8a6e', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_f0a45f65812212fe', 'ذود', 'e9.raw', 19, 2, 'definition', 'en', 'مِذْوَدٌ ذ [ An instrument for driving, driving away, or repelling. -b2- ] (tropical:) A spear, or short spear, with which one repels from, or defends, himself. (A.) -b3- (tropical:) The horn of a bull, (T, A, K,) with which he repels from, or defends, himself. (A.) -b4- (tropical:) The tongue: (S, M, A, K:) because with it a man defends his honour. (M.) Hassán Ibn-Thábit says, لِسَانِى وَسَيْفِى صَارِمَانِ كِلَاهُمَا وَيَبْلُغُ مَا لَا يَبْلُغُ السَّيْفُ مِذْوَدِى (tropical:) [ My tongue and my sword are sharp, both of them; and my tongue reacheth what my sword will not reach ]. (S, TA.) -b5- (tropical:) [A man who defends well, or vigorously; as also :] you say رِجَالٌ مَذَاوِدٌ and مَذَاوِيدُ . (A.) -b6- The manger ( مِعْلَف , T, K, TA, in some copies of the K معتلف , TA) of a horse or similar beast. (T, K. [A manger is thus called in the present day.])', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9bfcb6310ffe7c4c', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_f6e497a6db36c8bd', 'ذود', 'e3.raw', 13, 2, 'definition', 'en', '4 اذادهُ ذ He aided, or assisted, him to drive, or drive away, (T, S, M, A,) his camels. (T, S, A.) [In the K, أَذَدْتُهُ is said to signify أَعَنْتُهُ عَلَى ذِيَادِ أَهْلِهِ : but اهله is app. a mistake for إِبِلِهِ : or عَنْ is omitted before اهله ; and if so, the meaning is I aided, or assisted, him to defend his family; but in this latter case, we should read ذِيَادٍ , which would be less chaste than الذِّيَادِ .]', 'derived_from_raw_tei', 987);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0066c913d4b088cc', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_fcab4c70fb94151a', 'ذود', 'e7.raw', 17, 2, 'definition', 'en', 'ذَائِدٌ ذ Driving: driving away: and repelling: pl. ذُوَّدٌ and ذُوَّادٌ and ذَادَةٌ . (M, K.) -b2- Also, and , [but the latter has an intensive meaning,] (assumed tropical:) A man who is a defender, or protector, of that which, or those whom, it is necessary to defend, or protect: (S, K:) who is wont to repel attacks upon his honour. (S, * TA.)', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bfd511ca89675db5', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_7ee46a24342452b0', 'ذود', 'e8.raw', 18, 2, 'definition', 'en', 'مَذَادٌ ذ A place where beasts pasture at pleasure, where they eat and drink what they please, amid abundance of herbage. (IAar, K.)', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e8c0fadec016c23f', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_931cfaf7d05d760a', 'ذود', 'e10.raw', 20, 2, 'definition', 'en', 'مِذْوَادٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_149e2ddfb62412a0', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_9efec3d61578d38a', 'ذود', 'e6.raw', 16, 2, 'definition', 'en', 'ذَوَّادٌ ذ : see the next following paragraph.', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_968add743b9ffc38', 'lane_lexicon', 're_lane_5feda8cf7f891885', 'sec_lane_baaa36dd1669708a', 'ذود', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَادَ ذ , (M, A,) first pers. ذُدْتُ , (T, S,) aor. يَذُودُ , (T, A,) inf. n. ذَوْدٌ , (T,) or ذِيَادٌ , (S,) or both, (M, A, K,) He drove: (S, M, K:) he drove away: (T, S, M, A, K:) and he repelled. (M, K.) You say, ذَدْتُ الإِبِلَ I drove the camels: (S:) and I drove them away: (T, S:) and [so , for] تَذْوِيدٌ signifies the same as ذِيَادٌ . (S.) And ذاد الإِبَلِ عَنِ المَآءِ , (A, Msb,) aor. يَذُودُ , inf. n. ذَوْدٌ and ذِيَادٌ , He (the pastor) [ drove away, or repelled, or] kept back, or debarred, the camels from the water; or prevented them from coming to it. (Msb.) And ذادهُ عَنْ كَذَا , (A,) and ذُدْتُهُ , (S,) He, and I, drove him away from such a thing. (S, A. [And the like is said in the M.]) And ذاد عَنِ الحَرَمِ He repelled from, or defended, the sacred territory. (L.) And الثَّوْرُ يَذُودُ عَنْ نَفْسِهِ بِمِذْوَدِهِ , i. e. (tropical:) [ The bull repels from, or defends, hims 2 ذَوَّدَ see above.', 'derived_from_raw_tei', 987);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7e28078a02ecdc09', 'lane_lexicon', 're_lane_6799e3b6c74869a8', 'sec_lane_2cfbcad7af074965', 'فلست', 'e1.raw', 11, 2, 'definition', 'en', 'فَلْسَفَةٌ ذ , a foreign word, Science; (M;) [ philosophy; or] love of science: from the word here following. (O and K in art. سوف .)', 'derived_from_raw_tei', 2440);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c527e67dc9905116', 'lane_lexicon', 're_lane_6799e3b6c74869a8', 'sec_lane_6e4e478178c82cb9', 'فلست', 'e2.raw', 12, 2, 'definition', 'en', 'فَيْلَسُوفٌ ذ A man of science; (M;) [ a philosopher; ] a word meaning in Greek a lover of science. (O and K in art. سوف .)', 'derived_from_raw_tei', 2440);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cf725f2dbe79ce88', 'lane_lexicon', 're_lane_68d9dd470bca8506', 'sec_lane_dcee34bd2fc91bdd', 'ذوف', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَافَ ذ , (M, K,) aor. يَذُوفُ , (M,) inf. n. ذَوْفٌ , He walked with short steps, and in a straddling manner. (M, K.) -A2- And ذُفْتُ is a dial. var. of ذُفْتُ , signifying I mixed [medicine &c.] (M.)', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3a97be61629c0223', 'lane_lexicon', 're_lane_68d9dd470bca8506', 'sec_lane_8818e776cb5e4ad2', 'ذوف', 'e2.raw', 12, 2, 'definition', 'en', 'ذُوفَانٌ ذ [like ذُؤْفَانٌ &c.] Poison: (K:) or poison made into a confection: or deadly poison: like ذِيفَانٌ [&c.]. (M.)', 'derived_from_raw_tei', 988);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_621e2d15b5ea7e46', 'lane_lexicon', 're_lane_68e6adeae54f73ea', 'sec_lane_1802bcd4450553f9', 'ذيم', 'e2.raw', 12, 2, 'definition', 'en', 'ذَامٌ ذ : see what next follows, in two places.', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8b3d2b889d3b61fd', 'lane_lexicon', 're_lane_68e6adeae54f73ea', 'sec_lane_2ab7a95209e887ff', 'ذيم', 'e4.raw', 14, 2, 'definition', 'en', 'مَذِيمٌ ذ Blamed, or found fault with; (S, Msb, K;) as also : (S, K:) the former defective, and the latter complete: (S:) applied [app. to a man; (see the dial. var. مَذْؤُومٌ , as used in the Kur vii. 17;) and] to a commodity. (Msb.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_edf95257cbb8c52a', 'lane_lexicon', 're_lane_68e6adeae54f73ea', 'sec_lane_3f771ca8035896f4', 'ذيم', 'e5.raw', 15, 2, 'definition', 'en', 'مَذْيُومٌ ذ : see what next precedes.', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ec195b7593bf743d', 'lane_lexicon', 're_lane_68e6adeae54f73ea', 'sec_lane_ff438ed5d3c112d8', 'ذيم', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَامَهُ ذ , (T, M, Msb, K,) first pers. ذِمْتُهُ , (S,) aor. يَذِيمُ , (T, &c.,) inf. n. ذَيْمٌ and ذَامٌ , (S, M, Msb, K,) He blamed, or found fault with, him, or it, (T, S, M, Msb, K,) namely, a commodity; like ذَأَمَهُ : (Msb:) accord. to Akh, ذِمْتُهُ and ذَأَمْتُهُ and ذَمَمْتُهُ all signify the same. (S.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f3ce0d6c8e76b07a', 'lane_lexicon', 're_lane_68e6adeae54f73ea', 'sec_lane_bc4245b157f058cf', 'ذيم', 'e3.raw', 13, 2, 'definition', 'en', 'ذَيْمٌ ذ and are inf. ns., (S, M, Msb, K,) and are syn. with عَيْبٌ [as such, and also as meaning A vice, fault, defect, or the like; in the latter sense syn. with ذَامٌّ , which belongs to art. ذم ]: (T, S, M, Msb, * K:) or, as some say, syn. with ذَمٌّ [ blame, &c.]. (M.) It is said in a prov., لَاتَعْدَمُ الحَسْنَآءُ [ The beautiful female is not without a defect ]. (S.)', 'derived_from_raw_tei', 991);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bf736ec3f928dc44', 'lane_lexicon', 're_lane_693b0d88f8eab51d', 'sec_lane_9af24fb2212393bf', 'ذه', 'e1.raw', 11, 2, 'definition', 'en', 'ذِهْ ذ and ذِهِى : see art. ذا .', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5bcf186493eaa7e6', 'lane_lexicon', 're_lane_6b081f41e91a26df', 'sec_lane_2fdc882f8cb12ab6', 'كمفطش', 'e1.raw', 11, 2, 'definition', 'en', 'كَمَا فِيْطُوس ذ [ χαμαίπιτυς , the ground-pine ]: see عَرْصَفٌ .', 'derived_from_raw_tei', 3003);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ab55fff4ad5704b6', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_20c5f751a1933a7f', 'ذعر', 'e12.raw', 22, 2, 'definition', 'en', 'مُذْعَرَةٌ ذ : see the next paragraph.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e5780b9988d04ed9', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_238578fa468f8af5', 'ذعر', 'e5.raw', 15, 2, 'definition', 'en', 'ذَعَرٌ ذ A state of stupefaction, (K,) by reason of shame, or pudency. (TA.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ed47dcb5e62f3c80', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_2631fb29052d556d', 'ذعر', 'e3.raw', 13, 2, 'definition', 'en', '1 ذَعَرَهُ ذ , aor. ذَعَرَ ; inf. n. ذَعْرٌ ; (S, A, Msb, K;) and , (TA,) inf. n. إِذْعَارٌ ; (K;) He frightened him; made him afraid. (S, A, Mgh, Msb, K, TA.) Hence, قُمْ فَأْتِ القَوْمَ وَلَا تَذْعَرْهُمْ عَلَىَّ Arise thou, and go to the people, meaning Kureysh, but do not make them to be frightened at me; i. e. do not acquaint them with thyself, but go clandestinely, lest they take fright at thee: said to Hodheyfeh, on the night of the Ahzáb [on the occasion of the war of the Moat]: so in a trad.: and in another trad. is mentioned the fol lowing saying of ''Omar, to some men contending together in throwing colocynths: كَذٰلِكَ لَا تَذْعَرُوا عَلَيْنَا , meaning, Let that suffice you: make not our camels to be frightened at us. (TA.) -b2- ذُعِرَ , (S, K,) inf. n. ذَعْرٌ ; (TA;) and ; (TA;) [and app. ; of which see the act. part. n., below;] He became frightened, or afraid. (S, K, TA.) [You say, ذُعِرَ مِنْهُ He was frightened at him, or it. ]', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8141e7b0f28bb1e1', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_41b6d83a4b0fbc1f', 'ذعر', 'e16.raw', 26, 2, 'definition', 'en', 'مُنْذَعِرٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f37afe982dacfaa2', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_450855fb240838dd', 'ذعر', 'e15.raw', 25, 2, 'definition', 'en', 'مُتَذَعِّرٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_617fe34472a45501', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_525b03b79091daf8', 'ذعر', 'e14.raw', 24, 2, 'definition', 'en', 'مُذَعَّرَةٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4f97864281533d15', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_57a209401b9b0aca', 'ذعر', 'e4.raw', 14, 2, 'definition', 'en', 'ذُعْرٌ ذ Fright. (S, * Mgh, Msb, * K.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f65949aa003b8f2c', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_ca710f5596adb043', 'ذعر', 'e6.raw', 16, 2, 'definition', 'en', 'ذَعِرٌ ذ , a possessive epithet, (T, TA,) or , (K,) A thing feared; a frightful thing. (T, K.) -b2- See also مَذْعُورٌ .', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7169374b233e279a', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_cf85014cf048321d', 'ذعر', 'e11.raw', 21, 2, 'definition', 'en', 'ذَعُورٌ ذ : see مَذْعُورٌ . -b2- Also, [without ة ,] A woman who becomes frightened at a thing that induces suspicion, or evil opinion, (S, A, Msb, K,) and at foul language. (K, TA: or, accord. to the CK and a MS. copy of the K, “ foul language ” is a distinct signification of the word.) A poet says, تَنُولَ بِمَعْرُفِ الحَدِيثِ وَ إِنْ تُرِدْ سِوَى ذَاكَ تُذْعَرْ مِنْكَ وَهْىَ ذَعُورُ [ She will give thee kind discourse; but if thou desire other than that, she will be frightened at thee; for she is one who is frightened at a thing inducing suspicion &c. ]. (TA.) -b3- Also A she-camel which, when her udder is touched, takes fright, and will not yield her milk. (So accord. to two copies of the S. [Expl. by إِذَا مُسَّ ضَرعُهَاغَارَّتْ ; and so in some copies of the K and accord. to the TA: in a copy of the A, عَارَتْ , which has a similar meaning: in some ''copies of the K, غَارَتْ , without teshdeed, i. e., is jealous. ])', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_97135f93039fffb0', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_db51136d73801a30', 'ذعر', 'e10.raw', 20, 2, 'definition', 'en', 'سَنَةٌ ذُعْرِيَّةٌ ذ A severe year. (A, K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_574e5264ba37ecab', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_f1fe9e62a7a9c7b8', 'ذعر', 'e13.raw', 23, 2, 'definition', 'en', 'مَذْعُورٌ ذ Frightened; or that becomes frightened; (S, A, K;) as also (A) and (K) and , (M, TA,) or . (K.) -b2- مَذْعُورَةٌ , and , (K, TA,) or , (so in the CK, and a MS. copy of the K,) A mad she-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_021d1fd443941ea6', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_7a28073a8f2f628a', 'ذعر', 'e8.raw', 18, 2, 'definition', 'en', 'ذَعْرَةٌ ذ A fright. (TA.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7d459d394828c5af', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_94369e009231b7be', 'ذعر', 'e9.raw', 19, 2, 'definition', 'en', 'ذُعَرَةٌ ذ [an intensive epithet, Very fearful. -b2- And hence,] A certain bird, (K,) a small bird, (T,) found in trees, always wagging its tail, (T, K,) never seen otherwise than frightened. (T, TA.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c09b828e66ad9672', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_9e8f7c4b517f7b36', 'ذعر', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَعَرَهُ ذ , aor. ذَعَرَ ; inf. n. ذَعْرٌ ; (S, A, Msb, K;) and , (TA,) inf. n. إِذْعَارٌ ; (K;) He frightened him; made him afraid. (S, A, Mgh, Msb, K, TA.) Hence, قُمْ فَأْتِ القَوْمَ وَلَا تَذْعَرْهُمْ عَلَىَّ Arise thou, and go to the people, meaning Kureysh, but do not make them to be frightened at me; i. e. do not acquaint them with thyself, but go clandestinely, lest they take fright at thee: said to Hodheyfeh, on the night of the Ahzáb [on the occasion of the war of the Moat]: so in a trad.: and in another trad. is mentioned the fol lowing saying of ''Omar, to some men contending together in throwing colocynths: كَذٰلِكَ لَا تَذْعَرُوا عَلَيْنَا , meaning, Let that suffice you: make not our camels to be frightened at us. (TA.) -b2- ذُعِرَ , (S, K,) inf. n. ذَعْرٌ ; (TA;) and ; (TA;) [and app. ; of which see the act. part. n., below;] He became frightened, or afraid. (S, K, TA.) [You say, ذُعِرَ مِنْهُ He was frightened at him, or it. ]', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2f576bc10c75c82f', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_a2d3cc990e5950f1', 'ذعر', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَعَرَهُ ذ , aor. ذَعَرَ ; inf. n. ذَعْرٌ ; (S, A, Msb, K;) and , (TA,) inf. n. إِذْعَارٌ ; (K;) He frightened him; made him afraid. (S, A, Mgh, Msb, K, TA.) Hence, قُمْ فَأْتِ القَوْمَ وَلَا تَذْعَرْهُمْ عَلَىَّ Arise thou, and go to the people, meaning Kureysh, but do not make them to be frightened at me; i. e. do not acquaint them with thyself, but go clandestinely, lest they take fright at thee: said to Hodheyfeh, on the night of the Ahzáb [on the occasion of the war of the Moat]: so in a trad.: and in another trad. is mentioned the fol lowing saying of ''Omar, to some men contending together in throwing colocynths: كَذٰلِكَ لَا تَذْعَرُوا عَلَيْنَا , meaning, Let that suffice you: make not our camels to be frightened at us. (TA.) -b2- ذُعِرَ , (S, K,) inf. n. ذَعْرٌ ; (TA;) and ; (TA;) [and app. ; of which see the act. part. n., below;] He became frightened, or afraid. (S, K, TA.) [You say, ذُعِرَ مِنْهُ He was frightened at him, or it. ]', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f1f86023a1a2cf16', 'lane_lexicon', 're_lane_775acd97e8bf8864', 'sec_lane_b4398222674a466a', 'ذعر', 'e7.raw', 17, 2, 'definition', 'en', 'ذُعَرٌ ذ : see ذَعِرٌ', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_298123e029fbaaed', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_102cdfa4e55de4c9', 'ذرب', 'e6.raw', 16, 2, 'definition', 'en', 'ذِرْبٌ ذ i. q. غُدَّةٌ [i. e. A ganglion; &c.]: (AZ, T:) or so : and both signify a certain thing that is sometimes in the neck of a human being or of a beast, like a pebble: or the former word signifies a certain disease in the liver, (K, TA,) slow of cure: (TA:) the pl. of the former is ذِرَبٌ , (K,) or ذِرَبَةٌ , (AZ, T,) or this latter is pl. of ذِرْبَةٌ . (TA.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c153fb57b7492d80', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_324dd18da88eac06', 'ذرب', 'e19.raw', 29, 2, 'definition', 'en', 'مِذْرَبٌ ذ The tongue: (K:) so called because of its sharpness. (TA.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c250028617ca7703', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_3f2fb511975a74c5', 'ذرب', 'e20.raw', 30, 2, 'definition', 'en', 'مُذَرَّبٌ ذ : see ذَرِبٌ , in two places.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_916ff6bec87ddf83', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_48b3df8c7b2de9a9', 'ذرب', 'e3.raw', 13, 2, 'definition', 'en', '4 اذرب ذ : see 2. -A2- Also (assumed tropical:) He became chaste in speech, after having been barbarous therein. (IAar, T in art. ربذ , and TA.) -b2- And (assumed tropical:) His life became bad, or corrupt. (IAar, T in art. ربد , and TA.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a0df08502d69fc0c', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_5228833558276f01', 'ذرب', 'e5.raw', 15, 2, 'definition', 'en', 'ذُرْبٌ ذ an irreg. pl. of ذَرِبٌ , q. v.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3b83e7aa398370a4', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_cc90200c89ed7680', 'ذرب', 'e16.raw', 26, 2, 'definition', 'en', 'ذُرَابٌ ذ Poison. (Kr, M, A, K.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_99139af4c09bb7ef', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_e7c34ae4c8e1021c', 'ذرب', 'e4.raw', 14, 2, 'definition', 'en', 'ذَرْبٌ ذ , (so in the CK and in a MS copy of the K,) or , (so accord. to the TA, [which is followed by the TK, and so in my MS copy of the K, but altered from ذَرْبٌ , which I incline to think the right reading,]) A shoemaker''s إِزْمِيل [a word well known as signifying his knife, with which he cuts the leather, but here explained in the TA as signifying his إِشْفَى with which he sews ]. (K.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fac70da79a35870e', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_f0ff910adcba54ab', 'ذرب', 'e11.raw', 21, 2, 'definition', 'en', 'ذَرَبَى ذ : see what next follows.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e4ff33f37c0544ef', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_6bc8a07493740b60', 'ذرب', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَرِبَ ذ , aor. ذَرَبَ , inf. n. ذَرَبٌ (M, A, Msb, K) and ذَرَابَةٌ , (S, * M, A, K,) said of a sword, and a spear-head, (A,) or of a thing (M, Msb) of any kind, (M,) It was, or became, sharp, (S, * M, A, Msb, K,) and cutting, or penetrating: (Msb:) or, said of a sword, and of a spear-head, it signifies [or signifies also] it was steeped in, or imbued with, poison. (A.) -b2- ذَرِبَ لِسَانُهُ , aor. as above, [and so the inf. n.], His tongue was, or became, sharp [properly speaking, i. e. sharp in the extremity: (see ذَرِبٌ :) and also tropically, i. e., in a good sense, as meaning (assumed tropical:) chaste, or eloquent; without barbarousness, or vitiousness, or impediment: and in a bad sense, as meaning (assumed tropical:) profuse of speech; or clamorous: bad, or corrupt: foul, unseemly, or obscene ]: he cared not what he said. (TA.) [For] ذَرَبٌ (S, M, A, TA) and ذَرَابَةٌ (S, A, TA) signify Sharpness of the tongue [properly speaking, or, as is said in the A, tropically]: (S, M, A, TA:) and the former, (TA,) or the latter, (Msb,) [or each.] metaphorically, (TA,) (tropical:) 2 ذرّب ذ , (M, K,) inf. n. تَذْرِيبٌ , (S,) He sharpened (M, S, K) an iron instrument [such as a sword and a spear-head &c.]; (M;) as also , (M, Msb, K,) aor. ذَرُبَ , (M, L, Msb, TA,) accord. to the K ذَرَبَ , but this is without any other authority, and contr. to analogy, as neither its third nor its second letter is a faucial, (TA,) inf. n. ذَرْبٌ ; (M, Msb, TA;) and . (KL.) Also, inf. n. as above, He poisoned a sword, i. e. steeped it in poison, and, when it was well steeped, took it forth and sharpened it; and , likewise, is allowable. (T, TA.) -A2- The inf. n. also signifies A woman''s holding her infant in order that it may satisfy its want [ by evacuation, as the words in the explanation ( حَتَّى يَقْضِىَ حَاجَتَهُ ) commonly mean, not, as Freytag supposes, by sucking ]. (T, K.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_35b5f95f2b8a3c2a', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_7a3cdc057700ea93', 'ذرب', 'e10.raw', 20, 2, 'definition', 'en', 'الذَّرِبَة ذ : see what next follows.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4fd73ebcf040bd21', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_87e191f9d2af12cc', 'ذرب', 'e12.raw', 22, 2, 'definition', 'en', 'ذَرَبِىٌّ ذ : see what next follows.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fc518942761b5f01', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_8a8c019d6a4791f1', 'ذرب', 'e14.raw', 24, 2, 'definition', 'en', 'ذَرَبَيَّا ذ (assumed tropical:) A vice, fault, defect, or the like; as also . (K.) -b2- And A calamity, or misfortune; (S, M, K;) from ذَرِبَ الجُرْحُ meaning “ the wound admitted not of cure; ” (S;) as also , (K, TA,) or , (so accord. to the CK,) and [or ذَرَبِيَّةٌ ?]. (TA.) El-Kumeyt says, مَانِى بِالذَّرَبَيَّا meaning (assumed tropical:) [ He smote me, or afflicted me, ,] with calamity, or misfortune: or with evil, or mischief; and discord, or dissension; (T;) as also [in the form of a pl. applied to rational beings, as though denoting personifications], (K, accord. to the TA,) or [in the dual form]; (so in the CK and in my MS copy of the K;) which likewise means with cala ذَرَبَّى ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cc621adacdc81815', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_8ae066700cf08255', 'ذرب', 'e7.raw', 17, 2, 'definition', 'en', 'ذَرَبٌ ذ an inf. n. of ذَرِبَ [q. v. passim]. (T, S, M, &c.) -b2- See also ذَرَبَيَّا : and see there a pl. or a dual form, in three places. -b3- Also (assumed tropical:) An incurable disease: (M, K:) [in the present day applied to diarrhœa; and this is app. meant by what follows:] a disease that attacks the stomach, in consequence of which it does not digest the food; becoming in a bad, or corrupt, state, and not retaining the food. (L.) -b4- And (assumed tropical:) Rust. (S, K.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_97d81458ff3202a9', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_994f43d4918b4e71', 'ذرب', 'e17.raw', 27, 2, 'definition', 'en', 'ذِرْيَبٌ ذ A yellow flower: (K:) or yellow, applied to a flower and to other things. (M.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_180d4e9f1d5ff32a', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_a3275ca2e4f1b599', 'ذرب', 'e13.raw', 23, 2, 'definition', 'en', 'ذَرَبَيَّةٌ ذ : see what next follows.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_026fef8ea9a05d28', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_b05a44066350faca', 'ذرب', 'e8.raw', 18, 2, 'definition', 'en', 'ذَرِبٌ ذ Sharp; (T, S, M, K;) applied to anything, (S, M,) as, for instance, a sword, (S,) or a spearhead; and so : (T:) or this latter, applied to a spear-head [&c.], signifies sharpened; (S;) as also : (T, S:) or ذَرِبٌ (A, TA) and (M, K) and , (T, TA,) applied to a sword (T, M, A, K) and a spearhead, (A, TA,) signify [or signify also] poisoned; (A, K;) i. e. steeped in, or imbued with, poison, (T, M, A, TA,) and then sharpened. (T, M, TA.) And سُمٌّ ذَرِبٌ means Sharp poison. (M, A.) A rájiz says, (referring to cattle, TA,) دَبَّتْ عَلَيْهَا ذَرِبَاتُ الأَنْبَارْ meaning [ Upon which have crept insects resembling ticks, that produce swellings where they creep, ] sharp in stinging. (S.) -b2- لِسَانٌ ذَرِبٌ [properly signifies] A tongue sharp in the extremity. (M, TA.) Tropically, (A,) (tropical:) A sharp tongue; (S, A, TA;) as also ذِرْبَةٌ ذ : see ذِرْبٌ : -b2- and see also ذَرِبٌ , in two places.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6bf4e3ca90e8ac6e', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_c77cddef75592b27', 'ذرب', 'e21.raw', 31, 2, 'definition', 'en', 'مَذْرُوبٌ ذ : see ذَرِبٌ , in four places.', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0c65393c32a4cf3f', 'lane_lexicon', 're_lane_77a078357b82794c', 'sec_lane_c88678d2273eb48e', 'ذرب', 'e18.raw', 28, 2, 'definition', 'en', 'صُوفٌ أَذْرَبِىٌّ ذ Wool of Ádharbeeján or Adharbeeján or Adhrabeeján; for there are different opinions respecting the orthography of this name: (TA:) أَذْرَبِىٌّ is a rel. n. from اذربيجان : (K, TA:) contr. to rule; for by rule it should be أَذَرِىٌّ or أَذْرِىٌّ . (IAth, TA.)', 'derived_from_raw_tei', 959);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b06a216860a36064', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_030fdd1439f737c3', 'ذمر', 'e14.raw', 24, 2, 'definition', 'en', 'ذَيْمُرِىٌّ ذ , (K, TA,) with damm to the م , (TA,) [in the CK ذَيْمَرِىّ ,] A man sharp in temper, who adheres to things and minds them pertinaciously. (K, * TA.) [And so دَيْمُرِىٌّ .]', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_05960ed1d5608b4f', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_050a830b75750a6f', 'ذمر', 'e3.raw', 13, 2, 'definition', 'en', '5 تذمّر ذ , an irreg. quasi-pass. of ذَمَرَهُ , (M,) [or rather a reg. quasi-pass. of ذَمَّرَهُ , which is mentioned in the L, and meaning He excited, incited, urged, or instigated, himself, ] as though he blamed himself for a thing that had escaped him: (S:) or he blamed himself (M, K) for a thing that had escaped him: (K:) or he blamed himself for negligence, in order to inspirit himself, that he might not be negligent a second time: (A:) or he blamed himself for the escape, or loss, of [ what he was bound to preserve and defend, or] what is termed ذِمَارٌ . (TA.) -b2- He became angry. (M, K.) -b3- He disliked a thing, and was angry in consequence thereof. (Har p. 517.) -b4- تذمّر عَلَيْهِ He became changed, or altered, to him, and threatened him with evil. (S, K.) -b5- But in the trad. in which it is said of Moses, كَانَ يَتَذَمَّرُ عَلَى رَبِّهِ , this expression means that He emboldened himself to his Lord, and raised his voice in his expression of disapproval. (TA.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d07c2214b40c773d', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_30147565bfed1933', 'ذمر', 'e15.raw', 25, 2, 'definition', 'en', 'مُذَمَّرٌ ذ The back of the neck: (M, K:) or two bones in the base of the back of the neck: or the part called ذِفْرَى [ behind the ear ]: or the كَاهِل [or upper part of the back, next the neck ]: (M:) or this last-mentioned part with the neck and what surrounds it as far as the ذِفْرَى ; which is what the مُذَمِّر [q. v.] feels: (As, S:) or the place where the head of a camel is set upon the neck. (A.) -b2- بَلَغَ الأَمْرُ المُذمَّرُ (tropical:) The affair, or case, or event, reached a distressing pitch; (A, * K;) like بَلَغَ المُخَنَّقَ . (A.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7e50f6c76dbbb75f', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_3b0ffe03b60efcf3', 'ذمر', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَمَرَ ذ , (S,) inf. n. ذَمْرٌ , (K,) He (a lion) roared. (S, K.) -A2- ذَمَرَهُ , aor. ذَمُرَ , (S, M, A,) inf. n. ذَمْرٌ , (T, S, M, K,) He excited, incited, urged, or instigated, him, (T, S, M, A, K, *) with chiding, or reproof, (T, M, A, K, *) and encouraged him, (L,) عَلَى الأَمْرِ to do the thing; (A;) as also : (L, TA:) and he threatened him; (L, K; *) and was angry with him. (L.) -A3- ذَمَرَهُ , aor. ذَمُرَ ; and , [inf. n. تَذْمِيرٌ ;] He felt his مُذَمَّر [q. v.]. (M.) You say also, ذَمَرَ الرَّاعِى السَّلِيلَ The pastor felt the place where the head of the young camel just born was set upon the neck, to know if it were a male or a female: (A:) [or its inf. n., ذَمْرٌ , signifies the same as] a man''s inserting the hand into the vulva of a she-camel, to discover if her f 2 ذَمَّرَ see 1, in three places. -b2- تَذْمِيرٌ also signifies The determining the quantity, measure, size, or bulk, of a thing; or computing by conjecture the quantity or measure thereof. (K, * TA.)', 'derived_from_raw_tei', 977);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fec998294b9da6d8', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_4dd5a42e565700d6', 'ذمر', 'e13.raw', 23, 2, 'definition', 'en', 'ذُمَائِرُ ذ : see ذِمْرٌ , in two places.', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_69c4b678572111fd', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_fe4ba79252714b8d', 'ذمر', 'e16.raw', 26, 2, 'definition', 'en', 'مُذَمِّرٌ ذ A man who inserts his hand into the vulva of a she-camel, to discover if her fœtus be a male or a female: (S, M, K:) because he feels its مُذَمَّر , and thus knows it: he feels its jaw-bones: if they be thick, it is a male; and if thin, a female. (M.) El-Kumeyt says, وَقَالَ المُذَمِّرُ لِلنَّاتِجِينَ مَتَى ذُمِّرَتْ قَبْلِىَ الأَرْجُلُ [ And he whose business it was to feel the fœtus, for the purpose of discovering if it were male or female, said to those assisting the she-camels in bringing forth, When, before my time, were the legs felt to discover the sex of the fœtus? ]: (S, M:) for it is the head that is felt, as above explained. (M.) The مُذَمِّر is, to camels, as the midwife to human beings. (A.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3dec898306a1d4e0', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_6778cbe99f441452', 'ذمر', 'e8.raw', 18, 2, 'definition', 'en', 'ذَمَارِ ذ a verbal noun, like نَزَالِ ; [signifying Excite thou, or incite, urge, or instigate, thy companions to the fight: or, perhaps, be thou excited, &c.:] from ذَمَرَهُ فِى الحَرْبِ . (R.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c41d52a5af634624', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_69479c480be726e8', 'ذمر', 'e9.raw', 19, 2, 'definition', 'en', 'ذَمَارٌ ذ : see the next paragraph.', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7f6ec8f87e3a8256', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_76a5b4fcd0583069', 'ذمر', 'e7.raw', 17, 2, 'definition', 'en', 'ذِمِرٌّ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_35fe2b8027cbed9d', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_7f06cbc6e02655a3', 'ذمر', 'e12.raw', 22, 2, 'definition', 'en', 'ذَمَارَةٌ ذ Courage: (M, K:) or sagacity, or sagacity and cunning and craftiness, combined with courage [or with strength: see ذِمْرٌ ]: or cleverness, intelligence, and the quality of rendering good assistance. (M.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9bdefd034429a0b7', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_8b2dfae8ded7b99f', 'ذمر', 'e4.raw', 14, 2, 'definition', 'en', '6 تذامروا ذ They excited, incited, urged, or instigated, one another, (S, K,) in war, (S,) or to fight. (K.) -b2- Also, sometimes, They blamed one another for neglecting an opportunity. (TA.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1598695e3d268f2b', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_8dd1a00f993f43b7', 'ذمر', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَمَرَ ذ , (S,) inf. n. ذَمْرٌ , (K,) He (a lion) roared. (S, K.) -A2- ذَمَرَهُ , aor. ذَمُرَ , (S, M, A,) inf. n. ذَمْرٌ , (T, S, M, K,) He excited, incited, urged, or instigated, him, (T, S, M, A, K, *) with chiding, or reproof, (T, M, A, K, *) and encouraged him, (L,) عَلَى الأَمْرِ to do the thing; (A;) as also : (L, TA:) and he threatened him; (L, K; *) and was angry with him. (L.) -A3- ذَمَرَهُ , aor. ذَمُرَ ; and , [inf. n. تَذْمِيرٌ ;] He felt his مُذَمَّر [q. v.]. (M.) You say also, ذَمَرَ الرَّاعِى السَّلِيلَ The pastor felt the place where the head of the young camel just born was set upon the neck, to know if it were a male or a female: (A:) [or its inf. n., ذَمْرٌ , signifies the same as] a man''s inserting the hand into the vulva of a she-camel, to discover if her f 2 ذَمَّرَ see 1, in three places. -b2- تَذْمِيرٌ also signifies The determining the quantity, measure, size, or bulk, of a thing; or computing by conjecture the quantity or measure thereof. (K, * TA.)', 'derived_from_raw_tei', 977);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_51e874e93dd8fa15', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_95697d33c5e24093', 'ذمر', 'e6.raw', 16, 2, 'definition', 'en', 'ذَمِرٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d78d2f538f455d70', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_a64b2b259e8fd2d1', 'ذمر', 'e10.raw', 20, 2, 'definition', 'en', 'ذِمَارٌ ذ Whatever one is obliged, or bound, to preserve and guard and defend or protect, (T, M, K, *) and for the loss or neglect of which one must be blamed: (T:) things that are sacred, or inviolable; a man''s family, and property ( حَوْزَة ), and servants or dependents, and relations: (AA, T:) as also : (TA:) things for which, if he did not defend or protect them, a man would be blamed, and severely reproved: (A:) or what is behind a man, [ as a burden upon him, ] of those things which it is his duty to defend or protect; for they say حَامِىالذِّمَارِ , [see below,] like as they say حَامِى الحَقِيقَةِ ; and those things are termed ذمار because anger ( تَذَمُّرٌ ) on their account is incumbent on him to whom they pertain; and they are termed حقيقة because it is the duty of him to whom they pertain to defend them. (S.) حَامِىالذِّمَارِ signifies The defender, or protector, of those things for which a man is to be blamed, and severely reproved, if he do not defend or protect them: (A:) [or of those things which he is bound to preserve and guard and defend, &c.: see above:] or one who, when he is incited, or ذَمِيرٌ ذ : see ذِمْرٌ . -b2- Also A man goodly, or beautiful, (K, TA,) in make. (TA.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_707f16481ec34af9', 'lane_lexicon', 're_lane_89e1a3bc82bce5f1', 'sec_lane_c8027703abff9e2b', 'ذمر', 'e5.raw', 15, 2, 'definition', 'en', 'ذِمْرٌ ذ and and and A courageous man: (S, * M, K: *) or who combines sagacity, or sagacity and cunning and craftiness, with courage, (M,) or with strength; (T;) and has also this last signification: (TA:) or the four preceding words signify, (M,) or signify also, (K,) clever, intelligent, and a good assistant: (M, K:) pl. of the first (S, M) and second and fourth, (M,) أَذْمَارٌ ; (S, M;) and pl. of the third, ذِمِرُّونَ . (M.) -b2- الذِّمْرُ and are also names of Calamities, or misfortunes. (K.)', 'derived_from_raw_tei', 978);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c9e1878711ee7c25', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_09cc3e1b69caa960', 'ذف', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَفَّ ذ , aor. ذَفِفَ , (S, M, Msb, K,) inf. n. ذَفَافَةٌ , (M,) He, or it, (a thing, Msb,) was quick (S, M, Msb, K) and light, (M,) فِى الأَمْرِ in the affair: (K:) or he was light [or went lightly ] upon the ground. (M.) You say, ذَفَّ عَلَى وَجْهِ الأَرْضِ , and دَفَّ , (IAar, T in the present art. and in art. دف ,) i. e. He went lightly upon the ground. (TA in art. دف .) -b2- Also, aor. as above, said of a pestilence, It was quick; and despatched, or killed, quickly. (K.) And ذَفَّ عَلَيْهِ , (M, K,) inf. n. ذَفٌّ and ذِفَافٌ , (S, K,) or ذَفَفٌ ; (M;) and عليه , (T in art. دف , S, M, Mgh,) or , (K,) inf. n. تَذْفِيفٌ ; (S;) and عليه , (T, M, K, in the CK اذافّ ,) and لَهَ , and 2 ذَفَّفَ see 1, in two places. -b2- You say also, ذَفِّفْ جَهَازَ رَاحِلَتِكَ Lighten thou the travellingapparatus of thy riding-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4033d779e9e8e253', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_1b7f0e58fb99738d', 'ذف', 'e5.raw', 15, 2, 'definition', 'en', '1 ذَفَّ ذ , aor. ذَفِفَ , (S, M, Msb, K,) inf. n. ذَفَافَةٌ , (M,) He, or it, (a thing, Msb,) was quick (S, M, Msb, K) and light, (M,) فِى الأَمْرِ in the affair: (K:) or he was light [or went lightly ] upon the ground. (M.) You say, ذَفَّ عَلَى وَجْهِ الأَرْضِ , and دَفَّ , (IAar, T in the present art. and in art. دف ,) i. e. He went lightly upon the ground. (TA in art. دف .) -b2- Also, aor. as above, said of a pestilence, It was quick; and despatched, or killed, quickly. (K.) And ذَفَّ عَلَيْهِ , (M, K,) inf. n. ذَفٌّ and ذِفَافٌ , (S, K,) or ذَفَفٌ ; (M;) and عليه , (T in art. دف , S, M, Mgh,) or , (K,) inf. n. تَذْفِيفٌ ; (S;) and عليه , (T, M, K, in the CK اذافّ ,) and لَهَ , and 2 ذَفَّفَ see 1, in two places. -b2- You say also, ذَفِّفْ جَهَازَ رَاحِلَتِكَ Lighten thou the travellingapparatus of thy riding-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_433530b2a7003158', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_2f96fab130a1ea3f', 'ذف', 'e8.raw', 18, 2, 'definition', 'en', 'مَآءٌ ذُفٌّ ذ (M, K) and (M) and (T, S, K) and (M, K) A small quantity of water; water little in quantity: (T, S, M, K:) or the last two signify, (K,) or the last but one signifies, (M,) moisture: (M, K:) the pl. [of mult.] (of ذِفَافٌ , T, K, or ذُفَافٌ , K) is ذُفُفٌ (T, K) and [of pauc.] أَذِفَّةٌ . (T, M.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ac2e48c562933b53', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_4f3cf459f490017a', 'ذف', 'e14.raw', 24, 2, 'definition', 'en', 'سَهْمٌ مُذَفَّفٌ ذ A swift and light arrow. (K.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4d89e71e860f63d6', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_616c8b76bac5ec4c', 'ذف', 'e10.raw', 20, 2, 'definition', 'en', 'ذَفَافٌ ذ a subst. from ذَفَّ عَلَيْهِ [and as such signifying The act, or a means, of despatching a wounded man; i. e., hastening and completing his slaughter: and hence, of finishing a thing]. (ElHejeree, M, K.) A poet says, referring to a draught of water, تَكُونُ شِفَآءَ أَوْ ذَفَافًا لِمَا بِيَا [ That may be a cure, or a means of finishing, of what is in me, i. e., of what I am suffering ]. (El-Hejeree, M.) -A2- See also the next paragraph.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_37871619456c466b', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_cbebdf80931532d4', 'ذف', 'e11.raw', 21, 2, 'definition', 'en', 'ذُفَافٌ ذ : see ذَفِيفٌ , in two places: -b2- and ذِفَافٌ : -b3- and ذُفٌّ . -b4- You say also, مَاذُقْتُ ذُفَافًا I tasted not a little thing, or a thing small in quantity: (M:) or مَا ذَاقَ and [like ذَوَاقًا ] He tasted not anything. (K. In the CK ما ذافَ .)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0007de4876f2579b', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_fa924129f523ce02', 'ذف', 'e12.raw', 22, 2, 'definition', 'en', 'ذِفَافٌ ذ [or سَمٌّ ذِفَافٌ ], (AA, T, S,) or , (M,) or both, (K,) Deadly poison: (AA, T, S, M, K:) because it kills quickly him who drinks it. (AA, T.) -b2- You say also, مَا فِيهِ ذِفَافٌ , meaning مُتَعَلَّقٌ يُتَعَلَّقٌ بِهِ [i. e. There is not in it that whereby one may retain life; or a bare sufficiency of the means of subsistence ]. (K.) -b3- See also ذُفٌّ : and ذُفَافٌ .', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_17f96eac2837273c', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_71c57483b9f76c0d', 'ذف', 'e9.raw', 19, 2, 'definition', 'en', 'ذَفَفٌ ذ : see what next precedes.', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_891c1b15a3a4f230', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_74e8e5e339b09783', 'ذف', 'e6.raw', 16, 2, 'definition', 'en', 'R. Q. 1 ذَفْذَفَ ذ : see 1. -A2- Also He walked with an elegant and a proud and self-conceited gait, with an affected inclining of the body from side to side. (IAar, T, K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bd05299473dd55f6', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_8781391b6c5572c9', 'ذف', 'e4.raw', 14, 2, 'definition', 'en', '1 ذَفَّ ذ , aor. ذَفِفَ , (S, M, Msb, K,) inf. n. ذَفَافَةٌ , (M,) He, or it, (a thing, Msb,) was quick (S, M, Msb, K) and light, (M,) فِى الأَمْرِ in the affair: (K:) or he was light [or went lightly ] upon the ground. (M.) You say, ذَفَّ عَلَى وَجْهِ الأَرْضِ , and دَفَّ , (IAar, T in the present art. and in art. دف ,) i. e. He went lightly upon the ground. (TA in art. دف .) -b2- Also, aor. as above, said of a pestilence, It was quick; and despatched, or killed, quickly. (K.) And ذَفَّ عَلَيْهِ , (M, K,) inf. n. ذَفٌّ and ذِفَافٌ , (S, K,) or ذَفَفٌ ; (M;) and عليه , (T in art. دف , S, M, Mgh,) or , (K,) inf. n. تَذْفِيفٌ ; (S;) and عليه , (T, M, K, in the CK اذافّ ,) and لَهَ , and 2 ذَفَّفَ see 1, in two places. -b2- You say also, ذَفِّفْ جَهَازَ رَاحِلَتِكَ Lighten thou the travellingapparatus of thy riding-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a5f604d3ff60d627', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_92949090ddcf2ac8', 'ذف', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَفَّ ذ , aor. ذَفِفَ , (S, M, Msb, K,) inf. n. ذَفَافَةٌ , (M,) He, or it, (a thing, Msb,) was quick (S, M, Msb, K) and light, (M,) فِى الأَمْرِ in the affair: (K:) or he was light [or went lightly ] upon the ground. (M.) You say, ذَفَّ عَلَى وَجْهِ الأَرْضِ , and دَفَّ , (IAar, T in the present art. and in art. دف ,) i. e. He went lightly upon the ground. (TA in art. دف .) -b2- Also, aor. as above, said of a pestilence, It was quick; and despatched, or killed, quickly. (K.) And ذَفَّ عَلَيْهِ , (M, K,) inf. n. ذَفٌّ and ذِفَافٌ , (S, K,) or ذَفَفٌ ; (M;) and عليه , (T in art. دف , S, M, Mgh,) or , (K,) inf. n. تَذْفِيفٌ ; (S;) and عليه , (T, M, K, in the CK اذافّ ,) and لَهَ , and 2 ذَفَّفَ see 1, in two places. -b2- You say also, ذَفِّفْ جَهَازَ رَاحِلَتِكَ Lighten thou the travellingapparatus of thy riding-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a8893df9e3c40cb2', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_9333d0a2f8b8b892', 'ذف', 'e13.raw', 23, 2, 'definition', 'en', 'ذَفِيفٌ ذ Quick: (S, Msb:) or, as also , quick and light: or light, or going lightly, upon the ground. (M, K.) You say also خَفِيفٌ ذَفِيفٌ , (T, S, K,) meaning Quick, (S,) and in like manner خُفَافٌ , (T, K,) in each case using the latter word as an imitative sequent. (K.) -b2- Also A death, (M,) or a pestilence, (K.) that kills quickly. (M, K.) -A2- Also The male قُنْفُذ [or hedge-hog ]. (M.)', 'derived_from_raw_tei', 967);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d0320784c5174a98', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_9f7aa2fba941d773', 'ذف', 'e3.raw', 13, 2, 'definition', 'en', '1 ذَفَّ ذ , aor. ذَفِفَ , (S, M, Msb, K,) inf. n. ذَفَافَةٌ , (M,) He, or it, (a thing, Msb,) was quick (S, M, Msb, K) and light, (M,) فِى الأَمْرِ in the affair: (K:) or he was light [or went lightly ] upon the ground. (M.) You say, ذَفَّ عَلَى وَجْهِ الأَرْضِ , and دَفَّ , (IAar, T in the present art. and in art. دف ,) i. e. He went lightly upon the ground. (TA in art. دف .) -b2- Also, aor. as above, said of a pestilence, It was quick; and despatched, or killed, quickly. (K.) And ذَفَّ عَلَيْهِ , (M, K,) inf. n. ذَفٌّ and ذِفَافٌ , (S, K,) or ذَفَفٌ ; (M;) and عليه , (T in art. دف , S, M, Mgh,) or , (K,) inf. n. تَذْفِيفٌ ; (S;) and عليه , (T, M, K, in the CK اذافّ ,) and لَهَ , and 2 ذَفَّفَ see 1, in two places. -b2- You say also, ذَفِّفْ جَهَازَ رَاحِلَتِكَ Lighten thou the travellingapparatus of thy riding-camel. (K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7cbc3067f6ea5cc4', 'lane_lexicon', 're_lane_8c592569775562d8', 'sec_lane_a8b86d7deed018c7', 'ذف', 'e7.raw', 17, 2, 'definition', 'en', 'ذَفٌّ ذ Sheep or goats. (Kr, M, K.)', 'derived_from_raw_tei', 966);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1a9c500c82b484f4', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_1733993634050383', 'ذل', 'e21.raw', 31, 2, 'definition', 'en', 'مَذَلَّةٌ ذ : see ذُلٌّ . -b2- [Hence,] غَيْرُالمَذَلَّةِ (assumed tropical:) The wooden pin, peg, or stake: (S, K:) because its head is broken [or battered by beating]. (S.) [See عَيْرٌ .]', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_89ce7b4783d58219', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_357c47d049a930a2', 'ذل', 'e5.raw', 15, 2, 'definition', 'en', '10 استذلّهُ ذ He saw him to be ذَلِيل [i. e. low, base, vile, &c.]: (M, K:) or he found him to be so; (TA;) as also . (K.) -b2- See also 4. -b3- استذلّ البَعِيرَ الصَّعْبَ He plucked off the ticks from the refractory camel in order that he might experience pleasure [or relief ], and so become at ease, or tranquil, (M, K,) with him. (K.)', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d0d3dfe5a7305755', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_3f5b565aa4c85091', 'ذل', 'e18.raw', 28, 2, 'definition', 'en', 'ذُلْذُلَانُ النَّاسِ ذ and ذُلَيْذِلَانُهُمْ : see ذُلْذُلٌ .', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_245cda8a4ee9e312', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_563406d1a9b44d0b', 'ذل', 'e17.raw', 27, 2, 'definition', 'en', 'ذِلْذِلَةٌ ذ and ذُلَذِلَةٌ and ذَلَذِلَةٌ and see ذُلْذُلٌ , in eight places.', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7a84c4b4b98bd7ef', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_5d486ce890b0e60b', 'ذل', 'e19.raw', 29, 2, 'definition', 'en', 'أَذَلٌّ ذ [ More, and most, low, base, vile, &c.]: see أَخْنَعُ .', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f7f729176f251456', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_5db6af0de28a59e1', 'ذل', 'e11.raw', 21, 2, 'definition', 'en', 'ذَلُولٌ ذ Easy, tractable, submissive, or manageable; (S, M, Msb, K;) applied to a beast, such as a horse and the like, ( دَابَّة ), (S, M, Msb,) and to a man [&c.]; (M;) and so , applied to a man: (TA, as from the M: [but not found by me in the latter; and I believe that the right reading is ذَلَوْلًى , belonging to art. ذلى , q. v.:]) the former alike masc. and fem.: (M, TA:) pl. ذُلُلٌ (S, M, Msb, K) and أَذِلَّةٌ . (K.) A poet applies the epithet ذُلُل to spear-heads, as meaning Made easy [ to pierce with ] by being sharpened, and made thin and slender. (M.) -b2- See also the next paragraph, in two places.', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bfddf98139ef139e', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_d360ea8c96b1a2ad', 'ذل', 'e12.raw', 22, 2, 'definition', 'en', 'ذَلِيلٌ ذ Low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, lowered, brought low, abased, humbled, and weak; (T, S, M, Msb, K;) applied to a man; (T, S;) and signifies the same, as a sing.; (Ibn- ''Abbád, K:) or this latter is a pl. of the former, (T,) as also أَذِلَّآءُ (S, M, Msb, K) and أَذِلَّةٌ (T, S, Msb, K) and ذِلَالٌ . (M, K.) -b2- [Also Gentle; and merciful. Hence,] أَذِلَّةٍ عَلَى المُؤْمِنِينَ أَعِزَّةٍ عَلَى الكَافِرينَ , in the Kur [v. 59], means Gentle, (Zj, T,) and merciful, (T,) to the believers, rough in behaviour, (Zj, T,) and hard, or severe, (T,) to the unbelievers. (Zj, T.) -b3- Also applied to a road, meaning (assumed tropical:) Made even, or smooth, and easy to be travelled, or to walk or ride upon; as also with ة ; being applied to طَرِيقٌ [which is fem. as well as masc.] ; (M;) and so : (T:) pl. of the latter, (T,) or of the former, (M,) ذُلُلٌ : (T, M:) and [in like manner] ذَلُولِىٌّ ذ Good and easy in respect of natural disposition: pl. ذَلُولِيُّونَ . (Ibn-'' Abbád, K. [In the CK, الخَلْقِ is erroneously put for الخُلُقِ .]) See also ذَلُولٌ .', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b6d92cd44b26168d', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_e5aa5a9504f8c6d0', 'ذل', 'e8.raw', 18, 2, 'definition', 'en', 'ذُلٌّ ذ and and [all mentioned in the M and MA and K as inf. ns.] contr. of عِزٌّ ; (S, M;) [i. e.] Lowness, baseness, vileness, abjectness, meanness, paltriness, contemptibleness, despicableness, ignominiousness, ingloriousness, abasement, humiliation, and weakness. (Msb, K. *) وَ لَمْ يَكُنْ لَهُ وَلِىٌّ مِنَ الذُّلِّ , in the Kur [xvii. last verse], means Nor hath taken to himself any aider to assist Him and league with Him by reason of any lowness of condition in Him, as is the custom of the Arabs to do: (K, TA: [in the CK, يُخالِفُهُ is erroneously put for يُحَالِفُهُ :]) for they used to league, one with another, seeking thereby to become strong and inaccessible. (TA.) See also ذَلِيلٌ . -b2- And see the paragraph here following, in five places.', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5d84a9ec83227580', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_f2049bba84ad5696', 'ذل', 'e7.raw', 17, 2, 'definition', 'en', 'R. Q. 2 تَذَلْذَلَ ذ [app. from ذُلْذُلٌ ] It was, or became, in a state of commotion, or agitation, and lax, slack, or pendulous. (K.)', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8feb48ce1df8cbbf', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_76cca6e8bc9a22c3', 'ذل', 'e6.raw', 16, 2, 'definition', 'en', '[ اذْلَوْلَى ذ , a verb of which one of the significations is mentioned in this art. in the K, belongs to art. ذلى .]', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e128f2c1f5f5e314', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_954255a296954718', 'ذل', 'e20.raw', 30, 2, 'definition', 'en', 'أَذْلَالٌ ذ as a pl. without a sing.: see ذِلٌّ (of which it is also a pl.), in two places: -A2- and see ذُلْذُلٌ , last sentence.', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a9a24992a0a5ad96', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_9a465934f276eb24', 'ذل', 'e15.raw', 25, 2, 'definition', 'en', 'ذُلْذُلٌ ذ is sing. of ذَلَاذِلُ , which signifies The lower, or lowest, parts, (AZ, T, S,) that are next the ground, of a shirt, (S,) or of a long shirt; (AZ, T;) and IAar says that the sing. is , and , also; and they are also called ذَنَاذِنُ , pl. of ذِنْذِنٌ ; (T;) and دَنَادِنُ : (K in art. دن :) or ذُلْذُلٌ and and and and all signify the lower, or lowest, parts of a long shirt (M, K) when it dangles and becomes old and worn out; (M;) as also ذَلَاذِلُ ; (K;) [or rather] this last is pl. of all the foregoing words; (M;) and and [in some copies of the K, erroneously, ذَلْذَل , or ذِلْذِلٌ ذ and ذُلَذِلٌ and ذَلَذِلٌ and see ذُلْذُلٌ , in eight places.', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_11141c197c0f3d9a', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_aacd803826ca42ce', 'ذل', 'e14.raw', 24, 2, 'definition', 'en', 'ذُلَّانٌ ذ : see ذَلِيلٌ .', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_deb8be5766f0836f', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_b57eea08e52b9538', 'ذل', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَلَّ ذ , aor. يَذِلُّ , (M, Msb, K,) inf. n. ذُلٌّ and ذِلَّةٌ and مَذَلَّةٌ , (S, * M, MA, K,) or these three are simple substs., and the inf. n. is ذَلٌّ , (Msb,) and ذَلَالَةٌ (M, K) and ذُلَالَةٌ , (K,) [ contr. of عَزَّ ; (see ذُلٌّ below;) i. e.] He, or it, was or became, low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, abased, humble, and weak; (MA, Msb, K;) syn. هَانَ , (Msb, K,) and ضَعُفَ . (Msb.) -b2- ذَلَّ , (M, K,) and ذَلَّتْ , (M, Msb,) aor. as above, (M, K,) inf. n. ذِلٌّ , (M, Msb, K,) said of a man, (M,) and of a beast, such as a horse and the like, ( دَابَّة , M, Msb,) He, or it, was, or became, easy, tractable, submissive, or manageable; (M, Msb, K;) and اِذْلَوْلَى [which belongs to art. ذلى ] signifies the same as ذَلَّ in this sense. (ISd, TA.) And لَهُ He became lowly, humble, or submissive, [or he lowered, humbled, or submitted, himself, ] 2 ذلّل ذ , (M, Msb,) inf. n. تَذْلِيلٌ , (Msb,) He made, or rendered, (M, Msb,) a man, (M,) and a beast, such as a horse and the like, (M, Msb,) easy, tractable, submissive, or manageable: (M, Msb:) [said of the former, it may be rendered he brought under, or into, subjection; or he subdued: and said of the latter, he broke, or trained: and said of any animal, he tamed. -b2- Hence, (assumed tropical:) He beat, or trod, a road, so as to render it even, or easy to be travelled, or to walk or ride upon: see ذَلِيلٌ .] -b3- And ذلّل لَهُ أَمْرًا (assumed tropical:) He made an affair easy to him; syn. رَوَّضَهُ and سَوَّسَهُ . (TA in art. سوس .) -b4- And ذِلِّلَ الكَرْمُ (assumed tropical:) The bunches of the grape-vine were made to hang down [ so that they might be easily plucked ]: (M, K:) or were evenly disposed [ for the same purpose ]; syn. سُوِّيَتْ : (K:) or, accord. to AHn, التَّذْلِيلُ signifies the disposing evenly the bunches 4 اذلّهُ ذ , (M, Msb, K,) inf. n. إِذْلَالٌ , (TA,) He (God, Msb) lowered, abased, or humbled, him; or rendered him low, base, vile, abject, mean, paltry, contemptible, despicable, ignominious, inglorious, abased, humbled, and weak; (M, * Msb K, TA;) as also and : (K, TA:) all these signify the same. (S.) -b2- See also 10 -A2- اذلّ [as an intrans. verb] He (a man, S, M) became one whose companions were low, base, vile, &c. (S, M, K.) -b2- He became in a state, or condition, that was low, base, vile, &c. (S in art. قهر .)', 'derived_from_raw_tei', 972);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_471c29ae2e181950', 'lane_lexicon', 're_lane_95a68d0b30cb2460', 'sec_lane_b737ed34b1be955e', 'ذل', 'e9.raw', 19, 2, 'definition', 'en', 'ذِلٌّ ذ Easiness, tractableness, submissiveness, or manageableness; (S, M, K, and Ham p. 50; [mentioned in the M and Msb and K as an inf. n.;]) as also . (M, K, and Ham ubi suprà.) Hence the saying, بَعْضُ الذِّلِّ أَبْقَى لِلْأَهْلِ وَالمَالِ [ Somewhat of submissiveness is most preservative of the family and the property ]: (S:) or أَبْقَى لِلْأَهْلِ وَالمَالِ , occurring in a trad. of Ibn-Ez-Zubeyr; meaning that abjectness betiding a man when he bears patiently an injury that has befallen him is most preservative of him and of his family and his property. (TA.) -b2- Also Gentleness; and mercy; and so : thus in the phrase, وَٱخْفِضْ لَهُمَا جَنَاحَ or الذِّلِّ , (M, K,) in the Kur [xvii. 25, lit. And make soft to them (thy two parents) the side of gentleness; meaning treat them with gentleness ]: the former is the common reading: (TA:) or the latter means easiness, tractableness, or submissiveness: (K:) [and so the former, as has been stated above:] Er- ذِلَّةٌ ذ : see ذُلٌّ . -b2- In the following verse, لِيَهْنِئْ تُرَاثِى لِٱمْرِئٍ غَيْرِ ذِلَّةٍ صَنَابِرُ أُحْدَانٌ لِهُنَّ حَفِيفُ [ May my heritage give joy to a man not low, or base; slender arrows, singular of their kind, that have a whizzing sound ], the meaning is, غَيْرِ ذَلِيلٍ , or غَيْرِ ذِى ذِلَّةٍ ; and صنابر is put in the nom. case as a substitute for تراث . (M.)', 'derived_from_raw_tei', 973);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_01a6c0334d475733', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_064733c9261ab034', 'ذلق', 'e16.raw', 26, 2, 'definition', 'en', 'مُذَلَّقٌ ذ Anything sharpened, or pointed, at the extremity: (S:) [like ذَالِقٌ :] or a sharp point. (TA.) -b2- Also Milk mixed with water: (AZ, K:) [like مُذَرَّقٌ :] accord. to Ibn-''Abbád, like نَسْءٌ . (TA.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1b6fbcd9b7ee5fe6', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_1f803cc6f60a3703', 'ذلق', 'e11.raw', 21, 2, 'definition', 'en', 'ذَلِيقٌ ذ : see ذَلِقٌ , in four places. -b2- Also A vehement run or running. (JK, TA.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0c8df814fc245a53', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_29569ded7a233fa6', 'ذلق', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَلِق ذ , aor. ذَلَقَ , (S, K,) inf. n. ذَلَقٌ , (S,) It (a spear-head [and the like]) was, or became, sharp, cutting, or penetrating. (S, K.) -b2- And in like manner, aor. and inf. n. as above, [the inf. n. erroneously written in the CK ذَلْق ,] said of the tongue, (tropical:) It was, or became, sharp and eloquent; as also ذَلُقَ , aor. ذَلُقَ , inf. n. ذَلَاقَةٌ ; and ذَلَقَ , aor. ذَلُقَ : (K, TA:) and i. q. ذَرِبَ [which means it was, or became, sharp properly speaking; and also chaste, or eloquent; and profuse of speech, or clamorous ]. (S in explanation of the first verb, and app. of the second also, i. e. ذَلُقَ , inf. n. ذَلَاقَةٌ ; and K in explanation of the first only.) -b3- Also, i. e. like فَرِحَ , (assumed tropical:) It (a lamp, or lighted wick,) gave light, shone, was bright, or shone brightly: (K:) [or] so ذَلَقَ , inf. n. ذَلْقٌ . (JK.) -A2- Also, i. e 2 ذلّقهُ ذ , inf. n. تَذْلِيقٌ : see 1: -A2- and 4 -A3- ذلّق الفَرَسَ , (JK, K,) inf. n. as above, (K,) i. q. ضَمَّرَهُ [ He made the horse lean, or light of flesh; or prepared him for racing, &c. by feeding him with food barely sufficient to sustain him, after he had become fat, or after he had been fed with fodder so that he had become fat; &c.;] (JK, K;) and took good care of him. (JK.)', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5b9b5a9fe6d7071b', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_2cdefeb97bc8bb22', 'ذلق', 'e14.raw', 24, 2, 'definition', 'en', 'ذَوْلَقِيَّةٌ ذ : see the paragraph next following, in two places.', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_44bc7e56b0909b21', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_dd52c56106d7c191', 'ذلق', 'e6.raw', 16, 2, 'definition', 'en', 'ذَلْقٌ ذ (JK, S, Mgh, K) and and (K) and ذَوْلَقٌ (S, K) The point, extremity, or edge, (JK, S, Mgh, K,) of anything: (JK, S, K:) and the sharpness thereof: (AA, TA:) and the last, [particularly,] the extremity of a spear-head, and (assumed tropical:) of the tongue. (S, K.) -b2- And the first, The slender part of an arrow. (TA.) -b3- And The place in which turns the pin, or pivot, of the sheave of a pulley. (S, TA.) -A2- For the first, also, see ذَلِقٌ , in three places.', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_6258662e9ae37ca2', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_ec3b8318cd3e2c46', 'ذلق', 'e7.raw', 17, 2, 'definition', 'en', 'ذَلَقٌ ذ inf. n. of ذَلِقٌ . (S, K, * TA.) -b2- It may be also pl. of , signifying Sharpened, or pointed, in the iron head or blade: [like مُذَلَّقٌ :] -b3- and it may be used by poetic license for ذَلْقٌ . (L.) -b4- See also the paragraph next following.', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bae625837f5bb215', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_fb1531a7ad6f2673', 'ذلق', 'e12.raw', 22, 2, 'definition', 'en', 'ذَالِقٌ ذ : see ذَلَقٌ .', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3bff3f6eb4b800a8', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_fb78c34759f38387', 'ذلق', 'e13.raw', 23, 2, 'definition', 'en', 'ذَوْلَقٌ ذ : see ذَلْقٌ .', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0198252032a9c2ee', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_891e42574d0a8d7e', 'ذلق', 'e15.raw', 25, 2, 'definition', 'en', 'أَذْلَقُ ذ , and its pl. ذُلْقٌ : see ذَلِقٌ . -b2- الحُرُوفُ الذُّلْقُ The letters [ that are pronounced by means ] of the tip of the tongue and the lip: (S, K:) sing. أَذْلَقُ : they are six; (S;) [comprised in the phrase مُرْ بِنَفْلٍ :] three of these are termed , namely, ر and ل and ن ; and three, شَفَوِيَّةٌ , namely, ب and ف and م : (S, K:) or all of these six letters are termed . (TA voce عَسْجَدٌ .) Every quadriliteral-radical or quinqueliteral-radical word [that is genuine Arabic] contains one or two or three of these six letters: every word of either of these classes that does not contain one of these six letters is to be judged adventitious: all the other letters are termed الحُرُوفُ المُصْمَتَهُ . (IJ.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0272629cf9e1fbc3', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_8f7745656e1e40ea', 'ذلق', 'e8.raw', 18, 2, 'definition', 'en', 'ذَلِقٌ ذ and , applied to a spear-head [and the like], Sharp, cutting, or penetrating: (S, K:) pl. of the latter ذُلْقٌ . (K, * TA.) -b2- And in like manner, both words, applied to the tongue, (tropical:) i. q. ذَرِبٌ [which means Sharp properly speaking; and also chaste, or eloquent; and profuse of speech, or clamorous ]: (S, K:) and and and and , so applied, signify sharp and eloquent. (K.) You say لِسانٌ ذَلِقٌ طَلِقٌ , expl. in art. طلق [q. v.]: (K:) and لِسَانٌ طَلْقٌ and طَلِيقٌ and طُلُقٌ and ذُلَقٌ ذ and ذُلُقٌ : see the next preceding paragraph, each in two places.', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cd252781a842a468', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_a7f4722f6e69fa9d', 'ذلق', 'e5.raw', 15, 2, 'definition', 'en', '10 استذلق الضَّبَّ ذ He sought, or endeavoured, to make the [ lizard called ] ضبّ come forth from its hole. (TA.) One says likewise, المَطَرُ يَسْتَذْلِقُ الحَشَرَاتِ The rain draws forth the reptiles, or small creeping things, or makes them to come forth, from their holes; as also يستدلقها . (TA in art. دلق .) And استذلق السَّيْفَ and استدلقهُ He drew forth the sword, or made it to come forth. (TA ibid.)', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4f311fbbf44ec857', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_b01b3f4d18e08fbb', 'ذلق', 'e17.raw', 27, 2, 'definition', 'en', 'مِذْلَاقَةٌ ذ A quick-paced she-camel. (TA.)', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e2ac9a0f9f388a1d', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_bb0dc43571b9a2b2', 'ذلق', 'e3.raw', 13, 2, 'definition', 'en', '4 اذلقهُ ذ as syn. with ذَلَقَهُ and ذلّقهُ : see 1. -b2- Also, (inf. n. إِذْلَاقٌ , TA,) (assumed tropical:) He made it to give light, shine, become bright, or shine brightly; namely, a lamp, or lighted wick. (JK, K.) -A2- Also He, or it, unsettled, disquieted, disturbed, agitated, flurried, or put into a state of commotion, him, or it. (JK, S, K.) You say, أَتَانِى خَبَرٌ فَأَذْلَقَنِى News came to me, and unsettled me, or disquieted me, &c. (JK.) And it is said in a trad. of Má''iz, لَمَّا أَذْلَقَتْهُ الحِجَارَةُ جَمَزَ , (Mgh, TA,) i. e. When the stones disquieted him, &c.: (TA:) or when the stones hit him, or hurt him, with the point, or edge, [or rather the points, or edges, ] thereof, he ran [or went ] quickly. (Mgh.) See also 1, last sentence but one. You say also, أَذْلَقَنِى قَوْلُكَ Thy saying afflicted me, or distressed me, so that I writhed, or showed that I was hurt. (TA.) And اذلق الضَّبَّ He poured water into the hole of the [ lizard called ] ضبّ in order that he might come 7 انذلق ذ It (a branch) had [or presented to one (for the verb occurs in a trad. cited as an ex. in the TA followed by لِى )] a point, or an extremity, (K, TA,) to be cut off. (TA.)', 'derived_from_raw_tei', 974);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_33aeb4d1fade33ca', 'lane_lexicon', 're_lane_97d5861b12dbc44f', 'sec_lane_c28f0a774fcbf930', 'ذلق', 'e10.raw', 20, 2, 'definition', 'en', 'ذَلْقَةٌ ذ and ذَلَقَةٌ : see ذَلْقٌ .', 'derived_from_raw_tei', 975);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_cf69bfd7f64e928c', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_0075136e36cca6f4', 'ذهب', 'e16.raw', 26, 2, 'definition', 'en', 'مُذْهِبٌ ذ A gilder. (S.) -b2- , explained by Lth as the name of (assumed tropical:) A certain devil, said to be of the offspring of Iblees, who tempts reciters of the Kur-án in the performance of [ the ablution termed ] الوُضُوْء , (K, * TA,) and on other occasions, (TA,) is [said to be] correctly [ المُذْهِبُ ,] with kesr to the ه : (K:) applied to the devil, (TA in art. شيط ,) as meaning (assumed tropical:) he who embellishes, or renders goodly in appearance, acts of disobedience [to God], as also المُهَذِّبُ , (Fr, TA in art. هذب ,) IDrd thinks that it is not [genuine] Arabic. (TA.) And accord. to the S and El-Kurtubee and many others, بِهِ means (assumed tropical:) [ In him is ] a vain suggestion [ of the devil ] respecting the water, and [ respecting ] the using much thereof in the وُضُوْء : [i. e. a vain suggestion that may induce him to think that the water is unfit, or deficient in quantity, or the like:] but accord. to the K, it is correctly المُذْهِبُ . (TA.) Az says th مَذْهَبَةٌ ذ [ A cause, or means, of doing away with, removing, dispelling, or banishing ]. Fasting is said, in a trad., to be مَذْهَبَةٌ لِلْأَشَرِ [i. e. (assumed tropical:) A cause, or means, of dispelling exultation, or excessive exultation, and resting the mind upon things agreeable with natural desire ]. (T and S voce مَحْسَمَةٌ , q. v.)', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ddd05e527186a38a', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_01a5a13980f2ddae', 'ذهب', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَهَبَ ذ , (S, A, &c.,) aor. ذَهَبَ , (A, K,) inf. n. ذَهَابٌ (S, A, Msb, K) and ذِهَابٌ (TA) and ذُهُوبٌ (S, A, K) and مَذْهَبٌ , (A, K,) He (a man, S, [and a beast,]) went [ in any manner, or any pace ]; went, or passed, along; marched; journeyed; proceeded: went, or passed, away; departed: syn. مَشَى , (A,) or سَارَ , (K,) or مَرّ : (S, A, K:) and said of a mark or trace or the like [as meaning it went away ]. (Msb.) [And hence, (assumed tropical:) It wasted away; became consumed, destroyed, exhausted, spent, or expended. ] -b2- ذَهَبَ إِلَيْهِ He went, repaired, betook himself, or had recourse, to him, or it. (TA.) And they say also, ذَهَبَ الشَّأْمَ [ He went to Syria ]; making the verb trans. without a particle; for although الشأم is here a special adv. n., they liken it to a vague locality. (TA.) -b3- ذَهَبَ عَنْهُ He, or it, went from, quitted, relinquished, or left, him, or it. (TA.) -b4- ذَهَبَ فِىالأَرْضِ , (A, Ms 2 ذَهَّبَ see 1, in the former half of the paragraph, in two places: -A2- and see also 4.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ce8f3d3d8afc4215', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_06fc2b5a84acbd0e', 'ذهب', 'e14.raw', 24, 2, 'definition', 'en', 'مَذْهَبٌ ذ is an inf. n.: (JK, A, K:) -b2- and also signifies A place of ذَهَاب [or going, &c.]: and a time thereof. (JK.) -b3- [Also A place to which one goes: see an ex. voce مَحْضَرٌ . -b4- And hence,] (tropical:) A place to which one goes for the purpose of satisfying a want of nature; a privy; (TA;) i. q. مُتَوَضَّأٌ ; (JK, A, K, TA;) in the dial. of the people of El-Hijáz. (JK, A, TA.) -b5- [Also A way by which one goes or goes away. -b6- And hence, as in several exs. in the first paragraph of this art.,] (tropical:) A way, course, mode, or manner, of acting or conduct or the like: (Msb, K, TA:) (tropical:) [ a way that one pursues in respect of doctrines and practices in religion &c.; and particularly a way of believing, opining, thinking, or judging; ] a belief, a creed, a persuasion, a doctrine, an opinion, a tenet, or a body of tenets or articles of belief; (K, TA;) an opinion in, or respecting, religion; and, accord. to Es-Sarakustee, an innovation in religion: (Msb:) and signifi مُذْهَبٌ ذ Gilt, or done over with gold; (S, A, K;) as also (A, K) and . (T, K.) -b2- Also sing. of مَذَاهِبُ , which signifies Skins gilt, (ISk, JK, TA,) i. e. having gilt tines, or stripes, regularly, or uniformly, succeeding one another: (ISk, TA:) or gilt straps or thongs: (S, TA:) and variegated, or figured, [ garments of the kind called ] بُرُود : (JK, TA:) [or it is applied as an epithet to such garments; for] you say بُرْدٌ مُذْهَبٌ . (TA.) The pl. above mentioned is also applied [as an epithet] to swords [app. meaning Adorned with gilding ]. (TA.) -b3- Applied to a horse, Of a red colour tinged over with yellow; (TA;) and so كُمَيْتٌ مُذْهَبٌ [i. e. of a gilded bay colour ]: (S, TA:) fem. with ة : the mare thus termed is of a clearer colour and thinner skin. (TA.) -A2- المُذْهَبُ is also a name of The Kaabeh. (K, TA.) -A3- See also the next paragraph, in three places.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_20cf15eed5e31119', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_20280a3fdbe6b89c', 'ذهب', 'e8.raw', 18, 2, 'definition', 'en', 'ذِهْبَةٌ ذ A rain: (S:) or a weak rain: or a copious rain: (A''Obeyd, K:) pl. ذِهَابٌ . (A''Obeyd, S, K.)', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_690fb0d6de4565e5', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_3035afa999e57a4f', 'ذهب', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَهَبَ ذ , (S, A, &c.,) aor. ذَهَبَ , (A, K,) inf. n. ذَهَابٌ (S, A, Msb, K) and ذِهَابٌ (TA) and ذُهُوبٌ (S, A, K) and مَذْهَبٌ , (A, K,) He (a man, S, [and a beast,]) went [ in any manner, or any pace ]; went, or passed, along; marched; journeyed; proceeded: went, or passed, away; departed: syn. مَشَى , (A,) or سَارَ , (K,) or مَرّ : (S, A, K:) and said of a mark or trace or the like [as meaning it went away ]. (Msb.) [And hence, (assumed tropical:) It wasted away; became consumed, destroyed, exhausted, spent, or expended. ] -b2- ذَهَبَ إِلَيْهِ He went, repaired, betook himself, or had recourse, to him, or it. (TA.) And they say also, ذَهَبَ الشَّأْمَ [ He went to Syria ]; making the verb trans. without a particle; for although الشأم is here a special adv. n., they liken it to a vague locality. (TA.) -b3- ذَهَبَ عَنْهُ He, or it, went from, quitted, relinquished, or left, him, or it. (TA.) -b4- ذَهَبَ فِىالأَرْضِ , (A, Ms 2 ذَهَّبَ see 1, in the former half of the paragraph, in two places: -A2- and see also 4.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_19affa34ef9c5fe5', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_4968b7fbb46cda31', 'ذهب', 'e10.raw', 20, 2, 'definition', 'en', 'ذَهُوبٌ ذ : see ذَاهِبٌ .', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7aba8f34b382c70b', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_54a62cc1fa3c844a', 'ذهب', 'e13.raw', 23, 2, 'definition', 'en', 'ذَاهِبٌ ذ [part. n. of ذَهَبَ ;] Going [ in any manner, or any pace ]; going, or passing, along; marching; journeying; proceeding: going, or passing, away; departing: [&c.:] (A, K:) and signifies the same [in an intensive manner]. (K.) -b2- [ ذَاهِبٌ فِى الطُّولِ means (assumed tropical:) Excessive in length or tallness. ]', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e331d810fff63129', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_f71a199df075e883', 'ذهب', 'e12.raw', 22, 2, 'definition', 'en', 'ذُهَيْبَةٌ ذ : see ذَهَبٌ , first sentence.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_550d1dd72eb075d3', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_673c2645cb6afb45', 'ذهب', 'e4.raw', 14, 2, 'definition', 'en', '[ Q. Q. 2 تَمَذْهَبَ ذ , from مَذْهَبٌ , is used by late writers as meaning (assumed tropical:) He followed, or adopted, a certain religious persuasion or the like. ]', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_739fe1bdcbfb7b2c', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_68dedf6ec5118a3c', 'ذهب', 'e11.raw', 21, 2, 'definition', 'en', 'ذَهِيبٌ ذ : see مُذْهَبٌ , first sentence.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c5a5398218cd5fe8', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_6c9e3cc95f1244ed', 'ذهب', 'e6.raw', 16, 2, 'definition', 'en', 'ذَهَبٌ ذ [ Gold; ] a certain thing well known; (S, Msb, &c.;) accord. to several of the leading lexicologists, (TA,) i. q. تِبْرٌ ; (A, L, K, &c.;) but it seems to have a more general meaning; for تِبْرٌ is specially applied to such [ gold ] as is in the mine, or such as is uncoined and unwrought: (TA:) [it is a coll. gen. n.; and therefore] it is masc. and fem.: (S, * Msb, K, * TA:) or it is fem. in the dial. of El-Hijáz: or, accord. to Az, it is masc., and not to be made fem. unless regarded as pl. of , (Msb, TA,) [or rather as a coll. gen. n., for] ذَهَبَةٌ is the n. un., (K,) signifying a piece of ذَهَب [or gold ]: (S, A, L, TA:) or, accord. to El-Kurtubee, it is fem., and sometimes masc., but more commonly fem.: is the dim. of ذَهَبٌ , the ة being added because the latter word is fem., like as it is in قُوَيْسَةٌ and شُمَيْسَةٌ ; or it is the dim. of ذَهَبَةٌ , and signifies a little piece of ذَهَب [or gold ]: (TA:) the pl. of ذَهَبٌ is أَذْهَابٌ [a pl. of pauc.] (S, A, Msb, K) and ذُهُو ذَهِبٌ ذ : see 1, last sentence.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_dcde90bd0db37dc0', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_88fffd520e77b507', 'ذهب', 'e3.raw', 13, 2, 'definition', 'en', '1 ذَهَبَ ذ , (S, A, &c.,) aor. ذَهَبَ , (A, K,) inf. n. ذَهَابٌ (S, A, Msb, K) and ذِهَابٌ (TA) and ذُهُوبٌ (S, A, K) and مَذْهَبٌ , (A, K,) He (a man, S, [and a beast,]) went [ in any manner, or any pace ]; went, or passed, along; marched; journeyed; proceeded: went, or passed, away; departed: syn. مَشَى , (A,) or سَارَ , (K,) or مَرّ : (S, A, K:) and said of a mark or trace or the like [as meaning it went away ]. (Msb.) [And hence, (assumed tropical:) It wasted away; became consumed, destroyed, exhausted, spent, or expended. ] -b2- ذَهَبَ إِلَيْهِ He went, repaired, betook himself, or had recourse, to him, or it. (TA.) And they say also, ذَهَبَ الشَّأْمَ [ He went to Syria ]; making the verb trans. without a particle; for although الشأم is here a special adv. n., they liken it to a vague locality. (TA.) -b3- ذَهَبَ عَنْهُ He, or it, went from, quitted, relinquished, or left, him, or it. (TA.) -b4- ذَهَبَ فِىالأَرْضِ , (A, Ms 2 ذَهَّبَ see 1, in the former half of the paragraph, in two places: -A2- and see also 4.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0219603abf3ec1d2', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_a132488e48a2f6a0', 'ذهب', 'e5.raw', 15, 2, 'definition', 'en', 'ذَهْبٌ ذ : see مَذْهَبٌ : -A2- and see also the last sentence of the paragraph here following.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5c8e05e3b7875b9d', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_be0b19ab9b7f52b9', 'ذهب', 'e18.raw', 28, 2, 'definition', 'en', 'مُذَهَّبٌ ذ : see مُذْهَبٌ .', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_aee5690ff83b2ef9', 'lane_lexicon', 're_lane_9d82c358d22b50b1', 'sec_lane_be5cbc1e68a89f61', 'ذهب', 'e9.raw', 19, 2, 'definition', 'en', 'ذَهَبَةٌ ذ : see ذَهَبٌ , first sentence.', 'derived_from_raw_tei', 983);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5cb1f19609c27460', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_2c404002e20bbc2a', 'ذهن', 'e4.raw', 14, 2, 'definition', 'en', '1 ذَهِنَ ذ , (MA, TA,) aor. ذَهَنَ , (TA,) inf. n. ذِهْنٌ and ذَهَنٌ , (MA, KL,) He was, or became, intelligent, possessed of understanding, sagacious, acute, skilful, knowing, (MA, KL, PS, TA,) and endowed with a retentive mind. (KL, PS.) You say, اِذْهَنْ إِلَى مَا أَقُولُ Understand thou what I say. (TA.) And هُوَ لَا يَذْهَنُ شَيْئًا He does not understand anything. (TA.) And ذَهِنْتُ كَذَا وَ كَذَا I understood such and such things. (TA) And ذَهِنْتُ عَنْ كَذَا I understood from such a thing. (TA.) -A2- ذَاهَنَنِى فَذَهَنْتُهُ : see 3. -b2- ذَهَنَنِى عَنْهُ , and , and , He, or it, made me to forget it; diverted me from remembering it: (K, * TA:) [like ذَهَلَنِى عَنْهُ , and أَذْهَلَنِى .] And ذُهِنَ Memory, or understanding, escaped him, or left him. (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5e7e61e5a8f18409', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_5058cc1bdd9bad15', 'ذهن', 'e8.raw', 18, 2, 'definition', 'en', '[ ذِهْنِىٌّ ذ Of, or relating to, the ذِهْن , or intellect, &c.; intellectual; subjective; ideal. Hence, الأَمُورُ الذِّهْنِيَّةُ Intellectual things; the things that are conceived in the mind, or considered subjectively; opposed to الأَمُورُ الخَارِجِيَّةُ .]', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_c692d41c16877af1', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_cbdff256e13cee27', 'ذهن', 'e7.raw', 17, 2, 'definition', 'en', 'ذَهِنٌ ذ and Intelligent, possessed of understanding, sagacious, acute, skilful, or knowing, [and endowed with a retentive mind; ] each [said to be] a possessive epithet, [signifying possessing ذِهْن , though the former is agreeable with a general rule as part. n. of ذَهِنَ ,] applied to a man; the latter app. changed [or contracted] from the former. (TA.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eba595d4f989919b', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_cd2df155a994f386', 'ذهن', 'e3.raw', 13, 2, 'definition', 'en', '1 ذَهِنَ ذ , (MA, TA,) aor. ذَهَنَ , (TA,) inf. n. ذِهْنٌ and ذَهَنٌ , (MA, KL,) He was, or became, intelligent, possessed of understanding, sagacious, acute, skilful, knowing, (MA, KL, PS, TA,) and endowed with a retentive mind. (KL, PS.) You say, اِذْهَنْ إِلَى مَا أَقُولُ Understand thou what I say. (TA.) And هُوَ لَا يَذْهَنُ شَيْئًا He does not understand anything. (TA.) And ذَهِنْتُ كَذَا وَ كَذَا I understood such and such things. (TA) And ذَهِنْتُ عَنْ كَذَا I understood from such a thing. (TA.) -A2- ذَاهَنَنِى فَذَهَنْتُهُ : see 3. -b2- ذَهَنَنِى عَنْهُ , and , and , He, or it, made me to forget it; diverted me from remembering it: (K, * TA:) [like ذَهَلَنِى عَنْهُ , and أَذْهَلَنِى .] And ذُهِنَ Memory, or understanding, escaped him, or left him. (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3f20d4b23928fa63', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_e31822206d06052c', 'ذهن', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَهِنَ ذ , (MA, TA,) aor. ذَهَنَ , (TA,) inf. n. ذِهْنٌ and ذَهَنٌ , (MA, KL,) He was, or became, intelligent, possessed of understanding, sagacious, acute, skilful, knowing, (MA, KL, PS, TA,) and endowed with a retentive mind. (KL, PS.) You say, اِذْهَنْ إِلَى مَا أَقُولُ Understand thou what I say. (TA.) And هُوَ لَا يَذْهَنُ شَيْئًا He does not understand anything. (TA.) And ذَهِنْتُ كَذَا وَ كَذَا I understood such and such things. (TA) And ذَهِنْتُ عَنْ كَذَا I understood from such a thing. (TA.) -A2- ذَاهَنَنِى فَذَهَنْتُهُ : see 3. -b2- ذَهَنَنِى عَنْهُ , and , and , He, or it, made me to forget it; diverted me from remembering it: (K, * TA:) [like ذَهَلَنِى عَنْهُ , and أَذْهَلَنِى .] And ذُهِنَ Memory, or understanding, escaped him, or left him. (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_be4b14d12ca90438', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_942b65478e862a54', 'ذهن', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَهِنَ ذ , (MA, TA,) aor. ذَهَنَ , (TA,) inf. n. ذِهْنٌ and ذَهَنٌ , (MA, KL,) He was, or became, intelligent, possessed of understanding, sagacious, acute, skilful, knowing, (MA, KL, PS, TA,) and endowed with a retentive mind. (KL, PS.) You say, اِذْهَنْ إِلَى مَا أَقُولُ Understand thou what I say. (TA.) And هُوَ لَا يَذْهَنُ شَيْئًا He does not understand anything. (TA.) And ذَهِنْتُ كَذَا وَ كَذَا I understood such and such things. (TA) And ذَهِنْتُ عَنْ كَذَا I understood from such a thing. (TA.) -A2- ذَاهَنَنِى فَذَهَنْتُهُ : see 3. -b2- ذَهَنَنِى عَنْهُ , and , and , He, or it, made me to forget it; diverted me from remembering it: (K, * TA:) [like ذَهَلَنِى عَنْهُ , and أَذْهَلَنِى .] And ذُهِنَ Memory, or understanding, escaped him, or left him. (JK.)', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ba8d290bef136e69', 'lane_lexicon', 're_lane_a3beaffc1eee7c72', 'sec_lane_bd6957132f3456c6', 'ذهن', 'e5.raw', 15, 2, 'definition', 'en', 'ذِهْنٌ ذ (JK, S, Msb, K, &c.) and (S, K) Intellect, intelligence, understanding, sagacity, acuteness, skill, or knowledge; syn. عَقْلٌ , (JK, K,) and فَهْمٌ , (K,) and فِطْنَةٌ , (S, Msb, K,) and ذَكَآءٌ ; (Msb;) and retentiveness of mind, or memory: (JK, * S, * K:) or, as some say, a faculty of the soul, provided for the acquisition of the several species of knowledge, including the external and internal senses: strength thereof is termed ذَكَآءٌ : and a good quality thereof for the forming ideas of the things that present themselves to it is termed فِطْنَةٌ : (TA:) pl. أَذْهَانٌ . (Msb, K. *) One says, اِجْعَلْ ذِهْنَكَ إِلَى كَذَا وَكَذَا [ Apply thine intellect, &c., to such and such things ]. (TA.) [Both are also inf. ns.: see 1, first sentence.] -b2- Also, the former, (assumed tropical:) Strength: (JK, S, K:) and fat: (JK, K:) pl. as above. (K.) One says, مَا بِرِجْلَىَّ ذِهْنٌ There is not in my legs any strength to walk. (TA.) And هُوَ مِنْ أَهْلِ الذِّهْنِ and الأَذْهَانِ (tropical:) He is of those endowed with strength [ of body: and also, ذَهَنٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 984);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_129a05e74447e2d5', 'lane_lexicon', 're_lane_a8cc4768152b5890', 'sec_lane_f5ea7b4eb81dd804', 'ذوباج', 'e1.raw', 11, 2, 'definition', 'en', 'ذُوبَاجٌ ذ : see جوذاب , in art. جذب .', 'derived_from_raw_tei', 987);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_eed57222e83cf6cb', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_0051a983b3fa9931', 'ذن', 'e3.raw', 13, 2, 'definition', 'en', '3 هُوَ يُذَانُّهُ عَلَى حَاجَةٍ ذ (assumed tropical:) He seeks, or demands, of him an object of want. (S, L, K. *)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_47a901fe216b2215', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_08fb6b802315e197', 'ذن', 'e2.raw', 12, 2, 'definition', 'en', '1 ذَنَّ ذ , aor. يَذنُّ , inf. n. ذَنِينٌ (S, M, K) and ذنَنُ , (K, [but the latter app. belongs to the verb as said of a man,]) It (what is termed ذَنِين , S, or mucus, TA, or a thing, and likewise the seminal fluid, M,) flowed; (S, M, K, * TA;) [like ذَمَّ , aor. يَذِمُّ ;] as also , inf. n. تَذْنِينٌ , (IAar, T, K,) said of what is termed ذَنِين . (IAar, T.) -b2- And ذَنَّ said of the nose, It flowed [ with what is termed ذَنِين ]; (Lth, T;) like ذَمَّ . (S and K in art. ذم .) -b3- And ذَنَّ said of a man, (MA,) or ذَنِنَ , (K, [but this latter I think doubtful,]) see. pers. ذَنِنْتَ , (A''Obeyd, T, S, M,) aor. يَذَنُّ , (A''Obeyd, T, S,) inf. n. ذَنَنٌ (A''Obeyd, T, S, M, K) and ذَنِينٌ , (K, [but this latter app. belongs to the verb in the senses explained above,]) His nose flowed (A''Obeyd, T, S, M, MA, K *) with what is termed ذَنِين : (A''Obeyd, T, S, M, K: *) and both his nostrils flowed. (M.) -b4- ذَنَنٌ also signifie 2 ذَنَّنَ see 1, first sentence.', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_de1825149bb5274c', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_17988418ed978bc3', 'ذن', 'e6.raw', 16, 2, 'definition', 'en', 'ذَنَنٌ ذ [originally an inf. n.: see 1:] Dirt, or filth; and تفل [i. e. تُفْل or تَفْل , meaning saliva; or froth, or foam, or the like; or perhaps it is a mistranscription for ثُفْل , meaning sediment, settlings, dregs, or lees, &c.]: mentioned by Suh. (TA.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_048b949c2808c2bf', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_18efc82af7fa4278', 'ذن', 'e8.raw', 18, 2, 'definition', 'en', 'ذَنِينٌ ذ (Lh, T, S, M, K) and (Lh, S, M, K) [the former originally an inf. n.: see 1:] Mucus (Lh, T, * S, M, K) of any sort, (Lh, M,) or thin mucus, (M, K,) or a thin fluid, (K,) or any fluid, (Lh, M, K,) that flows from the nose. (Lh, T, S, M, K.) -b2- And the former signifies also The seminal fluid of a stallion, and of an ass, and of a man, (M, TA,) that flows from the penis by reason of excessive appetence. (TA.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_15f8871a9e82b8dc', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_2e76586c1b92d279', 'ذن', 'e11.raw', 21, 2, 'definition', 'en', 'ذُنَيْنَآءُ ذ is mentioned by AHn as being in wheat, but not explained by him, except by his likening it to مُرَيْرَآء , which is taken forth from wheat and thrown away. (M.) [It is perhaps a mistranscription for ذُنَيْبَآءُ , q. v.]', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2b84a838a8b93860', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_5fced1035ef949bb', 'ذن', 'e10.raw', 20, 2, 'definition', 'en', 'ذُنَانَى ذ The mucus of camels: (K:) or [ a fluid ] like mucus, that falls from the noses of camels: or, accord. to Kr, it is ذُنَابَى : [but see this latter word:] or, as is said by some persons in whom confidence is placed, [in the TA, “ in whom confidence is not placed, ”] it is termed زُنَانَى : (M:) or it is a dial var. of زُنَانَى : or it is correctly with ذ . (K.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_f283b207ea1cc1d9', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_e718d47460e76ede', 'ذن', 'e9.raw', 19, 2, 'definition', 'en', 'ذُنَانَةٌ ذ A remainder, or remains, of a thing that is weak, or frail, (S, L, K,) and perishing; (S, L; in both of which is added, شَيْئًا بَعْدَ شَىْءٍ [app. meaning that leaves it portion after portion, by perishing, or passing away, gradually; but this rendering is purely conjectural, for I have not found the verb here used anywhere explained, nor elsewhere even mentioned];) and particularly of a debt, or of a promise: it is distinguished from ذُبَابَةٌ , which signifies a remainder, or remains, of a thing that is sound, or valid, or substantial. (S, L.) -b2- Also An object of want; syn. حَاجَةٌ . (K.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3f6bb9c9dff02d1f', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_635757a1c81bb661', 'ذن', 'e13.raw', 23, 2, 'definition', 'en', 'أَذَنٌّ ذ A man (S, M) whose nose flows with what is termed ذَنِين : (S, M, K:) and one whose nostrils flow: (T, M:) fem. ذَنَّآءُ , (S, M, K,) applied to a woman. (S, M.) -b2- It is also applied to a nose; as in the prov., أَنْفُكَ مِنْكَ وَإِنْ كَانَ أَذَنَّ [ Thy nose is a part of thee though it be flowing with ذَنِين ]. (TA.) -b3- Hence, (TA,) the fem. signifies also (tropical:) A woman whose menstrual discharge ceases not. (S, M, K.) -b4- And قَرْحَةٌ ذَنَّآءُ (assumed tropical:) [ A wound ] that will not be stanched. (TA.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_333817e00a2dc68f', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_7edfabe0810f1dc7', 'ذن', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَنَّ ذ , aor. يَذنُّ , inf. n. ذَنِينٌ (S, M, K) and ذنَنُ , (K, [but the latter app. belongs to the verb as said of a man,]) It (what is termed ذَنِين , S, or mucus, TA, or a thing, and likewise the seminal fluid, M,) flowed; (S, M, K, * TA;) [like ذَمَّ , aor. يَذِمُّ ;] as also , inf. n. تَذْنِينٌ , (IAar, T, K,) said of what is termed ذَنِين . (IAar, T.) -b2- And ذَنَّ said of the nose, It flowed [ with what is termed ذَنِين ]; (Lth, T;) like ذَمَّ . (S and K in art. ذم .) -b3- And ذَنَّ said of a man, (MA,) or ذَنِنَ , (K, [but this latter I think doubtful,]) see. pers. ذَنِنْتَ , (A''Obeyd, T, S, M,) aor. يَذَنُّ , (A''Obeyd, T, S,) inf. n. ذَنَنٌ (A''Obeyd, T, S, M, K) and ذَنِينٌ , (K, [but this latter app. belongs to the verb in the senses explained above,]) His nose flowed (A''Obeyd, T, S, M, MA, K *) with what is termed ذَنِين : (A''Obeyd, T, S, M, K: *) and both his nostrils flowed. (M.) -b4- ذَنَنٌ also signifie 2 ذَنَّنَ see 1, first sentence.', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_479159584ea41b81', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_868079c831b7081b', 'ذن', 'e4.raw', 14, 2, 'definition', 'en', '3 هُوَ يُذَانُّهُ عَلَى حَاجَةٍ ذ (assumed tropical:) He seeks, or demands, of him an object of want. (S, L, K. *)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_a4e54bc8b636ccbc', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_91d3f51c277ece35', 'ذن', 'e5.raw', 15, 2, 'definition', 'en', 'ذَنْ ذ , for إِذَانْ or إِذًا : see إِذًا , in art. اذا .', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e566e596399cc200', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_9d327c697c1d8bc0', 'ذن', 'e7.raw', 17, 2, 'definition', 'en', 'ذُنَانٌ ذ : see what next follows.', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_3679aff15d5800b0', 'lane_lexicon', 're_lane_a9f28ac427fc73eb', 'sec_lane_b2fb1400aeefb9ec', 'ذن', 'e12.raw', 22, 2, 'definition', 'en', 'ذُنْذُنٌ ذ , (S, M,) or ذِنْذِنٌ , (T,) The lower, or lowest, part (T, M) of a shirt, (T,) or of a long shirt; a dial. var. of ذُلْذُلٌ (M) [or ذِلْذِلٌ ]; mentioned by AA: pl. ذَنَاذِنُ : (T:) the ذَنَاذِن of a shirt, (ISk, S,) or of a garment, (K,) are like its ذَلَاذِل : (ISk, S, K:) and some say that the ن of the former is a substitute for the ل of the latter. (TA.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0c22514b08a70fe7', 'lane_lexicon', 're_lane_ab8e9b4b3608f319', 'sec_lane_c166b0dcc34833e9', 'ذ', 'e1.raw', 11, 2, 'definition', 'en', 'alphabetical letter ذ ذ The ninth letter of the alphabet; called ذَالٌ : it is one of the letters termed مَجْهُورَة [or vocal, i. e. pronounced with the voice, and not with the breath only]: and of the letters termed لِثَوِيَّة [or gingival], which are ث and ذ and ظ ; wherefore it is substituted for ث in تَلَعْذَمَ for تَلَعْثَمَ ; and it is said to be substituted for the unpointed د in فَشَرِّذْ بِهِمْ , [as some read] in the Kur [viii. 59, for فَشَرِّدْ بهم ]. (TA.) -A2- [As a numeral, it denotes Seven hundred. ]', 'derived_from_raw_tei', 947);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7f5ad7fdf76e0007', 'lane_lexicon', 're_lane_abf2adb1bd2d5a12', 'sec_lane_2df6cad6a7a253bf', 'ذعب', 'e2.raw', 12, 2, 'definition', 'en', '7 انذعب ذ , (K,) as also انثعب , the latter thought by Az to be the original word, (TA,) It (water) flowed, ran, streamed, or poured: it flowed in a continuous stream. (K.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_daf0b0578647190d', 'lane_lexicon', 're_lane_abf2adb1bd2d5a12', 'sec_lane_749507da2c964ac2', 'ذعب', 'e4.raw', 14, 2, 'definition', 'en', 'رَأَيْتُهُمْ مُذْعَابِّينَ كَأَنَّهُمْ عُرْفُ ضِبْعَانٍ ذ , (K,) and مُثْعَابِّينَ , (TA,) I saw them following one another as though they were the mane of a male hyena. (As, K.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_49eaaea730375268', 'lane_lexicon', 're_lane_abf2adb1bd2d5a12', 'sec_lane_7b26df1bfb6a7556', 'ذعب', 'e1.raw', 11, 2, 'definition', 'en', '5 تَذَعَّبَتْهُ الجِنُّ ذ , (K,) as also تَذَأَّبَتْهُ , (TA,) The jinn frightened him, or terrified him. (K.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b0125fdf2cfef376', 'lane_lexicon', 're_lane_abf2adb1bd2d5a12', 'sec_lane_bfd234ea539dd686', 'ذعب', 'e3.raw', 13, 2, 'definition', 'en', 'ذُعْبَانٌ ذ A young wolf. (K.)', 'derived_from_raw_tei', 965);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9d92809f8371bd76', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_01825959c29f89b9', 'ذنب', 'e24.raw', 34, 2, 'definition', 'en', 'تَذْنُوبٌ ذ and تُذْنُوبٌ , and with ة : see 2.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_1acc2376990beb4f', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_0713943d89e3bf36', 'ذنب', 'e11.raw', 21, 2, 'definition', 'en', 'ذَنَبَانٌ ذ A certain plant, (T, S,) well known, called by some of the Arabs ذَنَبُ الثَّعْلَبِ : (T:) a certain plant having long branches, somewhat dust-coloured (M, TA) in its leaves, growing in plain, or soft, land, upon the ground, not rising high, approved as pasture, (TA,) and not growing except in fruitful years: (M, TA:) or a certain herb, or plant, like ذُرَة [or millet ]; (K;) or a certain herb having ears at its extremities like the ears of ذُرَة , (M, TA, *) and having reeds, ( قصب [i. e. قَصَب ], M,) or twigs, ( قضب [i. e. قُضُب ], TA,) and leaves, growing in every place except in unmixed sand, [for حُرَّ الرَّمْلِ in the TA, I find in the M حَوَّ الرُملِ ,] and growing upon one stem and two stems: (M, TA:) or, accord. to AHn, a certain herb, having a جزرة [app. meaning rhizoma like the carrot ], which is not eaten, and twigs bearing a fruit from the bottom thereof to the top thereof, having leaves like those of the طُرْخُون , agreeing well with the pasturing cattle, and having a small dust-coloured blossom upon which bees feed; (M, TA;) rising about the height of a man, (TA,) or half the height ذُنُبَّى ذ and ذِنِبَّى : see ذَنَبٌ , first sentence.', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0d56073738d6fa09', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_0e1a4665356d750b', 'ذنب', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَنَبَهُ ذ , (M, K,) aor. ذَنُبَ (S, M, A, K) and ذَنِبَ , (M, K,) inf. n. ذَنْبٌ ; (TK;) and ; (M, K;) [properly signifies] He followed his tail, not quitting his track: (M:) [and hence, tropically,] (assumed tropical:) he followed him [ in any case ], not quitting his track. (K.) You say, ذَنَبَ الإِبِلَ and He followed the camels. (A: there mentioned among proper significations.) ElKilábee says, وَجَآءَتِ الخَيْلُ جَمِيعَا تَذْنُبُهْ [ And the horses, or horsemen, came all together, following him ]. (S [in which the meaning is indicated by the context; but whether it be proper or tropical in this instance is not shown].) And Ru-beh says, مِثْلُ الأَجِيرِ الرَّوَاحِلَا [ Like the hired man, ] he was at the tails of the ridden camels. (T, S.) ذَنَبَتِ القَوْمُ , and [ ذَنَبَتِ ] الطَّرِيقُ , and الأَمْرُ [ ذَنَبَ ], and السَحَابُ يَذْنُبُ بَعْضُهُ 2 ذنّب ذ , (T, M, A,) inf. n. تَذْنِيبٌ , (T, A,) said of the locust, It stuck its tail into the ground to lay its eggs: (A:) or, said of the [lizard called] ضبّ , (Lth, T, M,) and of the locust, (M,) and of the [locust in the stage in which it is termed] فَرَاش , (Lth, T, M,) and the like, (Lth, T,) it desired to copulate, (Lth, T, M,) or to lay eggs, and therefore stuck its tail into the ground: (M:) or, said of the ضَبّ , it signifies only it struck with its tail a hunter or serpent desiring to catch it: (T:) or, said of the ضَبّ , it signifies also it put forth its tail (M, A) from the nearest part of its hole, having its head within it, as it does in hot weather, (M,) or when an attempt was made to catch it: (A:) [or it put its tail foremost in coming forth from its hole; contr. of رَأَّسَ .] -b2- ذَنَّبَتِ البُسْرَةُ , (T, S, M, K,) or ذَنَّبَ البُسْرُ , (As, A, Mgh,) or الرُّطَبُ , (Msb,) inf. n. تَذْنِيبٌ , (Msb, K,) (tropical:) [ The full-grown unripe date or dates, or the ripening dates, ] began to ripen, (Mgh, and so in a copy of the S,) or showed ripening, (Msb, and so in a copy of the S,) or became speckled by reason of ripening, (As, T, M, K,) or 3 ذَانَبَتْ ذ , (AO, T, K,) written by Sgh, with his own hand, with ء , but by others without, (MF,) said of a mare [in parturition], She was in such a state that her fœtus came to her قُحْقُح [or ischium (here described by MF as the place of meeting of the two hips )], and the سِقْى [q. v. (here explained by MF as a skin containing yellow water ]) was near to coming forth, (AO, T, K,) and the root of her tail rose, and the part thereof that is bare of hair, and she did not [or could not ] lower it. (AO, T.) In this case, she is said to be , (AO, T, K.)', 'derived_from_raw_tei', 979);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4e79bea57bb6fe7f', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_13266aefedc40e7b', 'ذنب', 'e4.raw', 14, 2, 'definition', 'en', '4 اذنب ذ He committed a sin, crime, fault, misdemeanour, &c.; (S, * M, * A, * MA, K; *) he became chargeable with a ذَنْب [or sin, &c.]: (Msb:) it is an instance, among others, of a verb of which no proper inf. n. has been heard; [ ذَنْبٌ being used instead of such, as a quasi-inf. n.;] for إِذْنَابٌ , like إِكْرَامٌ , [though mentioned in the KL, as signifying the committing of a sin or the like, and also in the TK,] has not been heard. (MF.)', 'derived_from_raw_tei', 980);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_065bfdfc82c4bc6a', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_1cbcbb498119a60d', 'ذنب', 'e19.raw', 29, 2, 'definition', 'en', 'ذُنَابَى ذ : see ذَنَبٌ , in three places. -b2- It is also applied to Four [ feathers ] in the wing of a bird, after what are called الخَوَفِى . (S.) -b3- It is said in a trad., مَنْ مَاتَ عَلَى ذُنَابَى طَرِيقٍ فَهُوَ مِنْ أَهْلِهِ , meaning [ (assumed tropical:) Whosoever dies ] purposing to pursue a way leading to some particular end, [ he is to be reckoned as one of the people thereof. ] (TA.) -A2- Accord. to Fr and the S, it signifies also A fluid like mucus that falls from the noses of camels: but this is a mistake: the right word, as stated by IB and others, is ذُنَانَى . (L, MF, TA.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_ce7cfd6bf1ed6edf', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_22ebf27a2847a011', 'ذنب', 'e29.raw', 39, 2, 'definition', 'en', 'مَذْنُوبٌ ذ (tropical:) A man followed [ by dependants ]. (A.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2ad67d0449cd45ba', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_266de38a26e0b029', 'ذنب', 'e15.raw', 25, 2, 'definition', 'en', 'ذَنُوبٌ ذ A horse (T, S, &c.) having a long tail: (T, S:) or having a full, or an ample, tail. (M, A, K.) [See also أَذْنَبٌ .] -b2- Hence applied to a day: see ذَنَبٌ , in the latter half of the paragraph. -b3- Also A great دَلْو [or bucket ]: (Fr, T, Msb:) or one that has a [or tail ]: (TA:) or one that is full (S, M, Msb, K) of water; (S, Msb;) not applied to one that is empty: (S, TA:) or one that is nearly full of water: (ISk, S:) or one containing less than fills it: or one containing water: or a دَلْو (M, K) in any case: (M:) or a bucketful of water: (A:) masc. and fem.; (Fr, Lh, T, S, M, Msb;) sometimes the latter: (Lh, M:) pl. (of pauc., S) أَذْنِبَةٌ and (of mult., S) ذَنَائِبُ (S, M, K) and ذِنَابٌ . (M, A, * Msb, K.) Fr. cites as an ex., لَنَا ذَنُوبٌ وَلَكُمْ ذَنُوبُ فَإِنْ أَبَيْتُمْ فَلَنَا القَلِيبُ [as meaning For you shall be a great bucket, and for us a great bucket: or, if ye refuse this, for us shall be the well ]. (T.) [Accord. to the K, it also signifies A grave: but this is ev ذُنَيْبٌ ذ [dim. of ذَنَبٌ : -A2- and] i. q. ذُنَيْبِىٌّ , q. v. (TA.)', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e88cae5ab0451733', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_29a64ebc75f99337', 'ذنب', 'e30.raw', 40, 2, 'definition', 'en', 'مُذَانِبٌ ذ A camel that is at the rear of other camels; (K;) as also . (TA.) -b2- See also 3.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_373b4921e5b11c2c', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_32a858bea376017e', 'ذنب', 'e7.raw', 17, 2, 'definition', 'en', 'ذَنْبٌ ذ A sin, a crime, a fault, a misdemeanour, a misdeed, an unlawful deed, an offence, a transgression, or an act of disobedience; syn. إِثْمٌ , (T, M, A, Msb,) or جُرْمٌ , (S,) or both, (TA,) and مَعْصِيَةٌ : (T, TA:) or it differs from إِثْمٌ in being either intentional or committed through inadvertence; whereas the اثم is peculiarly intentional: (Kull p. 13:) or a thing that precludes one from [ the favour of ] God: or a thing for which he is blamable who does it intentionally: (KT:) pl. ذُنُوبٌ (M, Msb, K) and pl. pl. ذُنُوبَاتٌ . (M, K.) وَلَهُمْ عَلَىَّ ذَنْبٌ [in the Kur xxvi. 13, said by Moses, meaning And they have a crime to charge against me, ] refers to the speaker''s slaughter of him whom he struck, who was of the family of Pharaoh. (M.)', 'derived_from_raw_tei', 980);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_4049fefbefd50711', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_385a4a5ca3656607', 'ذنب', 'e22.raw', 32, 2, 'definition', 'en', 'ذَانِبٌ ذ (tropical:) Following in the track of a thing. (TA.) See also ذَنَبٌ , in the latter half of the paragraph.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_480e29bb159e7af3', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_cadefb10d0e02aff', 'ذنب', 'e23.raw', 33, 2, 'definition', 'en', 'أَذْنَبُ ذ A [lizard of the kind called] ضَبّ having a long tail. (T, L.) [See also ذَنُوبٌ .]', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e4d236c5a4f7b703', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_ccc9ca2161a7e13a', 'ذنب', 'e28.raw', 38, 2, 'definition', 'en', 'مُذَنِّبٌ ذ [app. applied to a she-camel, accord. to the K, or perhaps to a lizard of the kind called ضَبّ , as seems to be indicated in the TA,] Finding difficulty in parturition, and therefore stretching out her tail: (K:) [but accord. to Az,] it is applied to a ضَبّ only when he is striking with his tail a hunter or a serpent desiring to catch him. (T.) See also مِذْنَبٌ . -b2- See also 2, in two places.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_0d9ebd4cb2098c2a', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_da620a8871653b69', 'ذنب', 'e31.raw', 41, 2, 'definition', 'en', 'سَحَابٌ مُتَذَانِبٌ ذ (tropical:) Clouds following one another. (A.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9f176508d0c04cad', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_e34c80fb937a7e93', 'ذنب', 'e6.raw', 16, 2, 'definition', 'en', '10 استذنبهُ ذ He found him to be committing [or to have committed ] a sin, crime, fault, misdemeanour, or the like: and he attributed, or imputed, to him a sin, &c. (Har p. 450.) -A2- See also 1, in three places. -A3- استذنب الأَمْرُ (assumed tropical:) The affair was, or became, complete, [as though it assumed a tail,] and in a right state. (K, * TA.)', 'derived_from_raw_tei', 980);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_57dda3e8b5d07f69', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_e76ea59cef1b6e24', 'ذنب', 'e20.raw', 30, 2, 'definition', 'en', 'ذُنَيْبَآءُ ذ A certain grain that is found in wheat, whereof the latter is cleared [ by winnowing or other means ]. (M, K.) [See also ذُنَيْنَآءُ , in art. ذن .]', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_b707f69764ca65c5', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_6c3c6bb915d01255', 'ذنب', 'e25.raw', 35, 2, 'definition', 'en', 'مَذْنَبٌ ذ : see the next paragraph.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7862daaea908372a', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_6c75d001639ad566', 'ذنب', 'e18.raw', 28, 2, 'definition', 'en', 'ذِنَابَةٌ ذ : see ذَنَبٌ , in six places: -b2- and see مِذْنَبٌ , in two places. -b3- ذِنَابَةٌ الطَّرِيقِ (assumed tropical:) The point, or place, to which the way, or road, leads; syn. وَجْهُهُ . (IAar, M, K.) So in the saying of Abu-l-Jarráh, to a certain man, إِنَّكَ لَمْ تَرْشَدْ ذِنَابَةَ الطَّرِيقِ [ (assumed tropical:) Verily thou didst not follow a right course in respect of the point, or place, to which the way that thou tookest leads ]. (IAar, M.) -A2- Also (assumed tropical:) Relationship; nearness with respect to kindred; or near relationship. (K.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_bed64cc569689381', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_73b600a1a9dd140d', 'ذنب', 'e8.raw', 18, 2, 'definition', 'en', 'ذَنَبٌ ذ and (T, S, M, A, Msb, K) and and (El-Hejeree, M, K) signify the same; (T, S, M, &c.;) i. e. The tail; syn. ذَيْلٌ : (TA: [in the CK, الذِّنْبِىُّ is erroneously put for الذِّنْبِىَّ :]) but accord. to Fr, one uses the first of these words in relation to the horse, and the second in relation to the bird: (T:) or the first is used in relation to the horse (S, A) and the ass [and the like] (S) more commonly than the second; (S, A; *) and the second is used in relation to a bird (S, M, A, Msb) more commonly than the first, (S, M, *) or more chastely: (M, * Msb:) or the second is [properly] of a winged creature; and the first is of any other; but the second is sometimes, metaphorically, of the horse: (Er-Riyáshee, TA:) or, as some say, the second signifies the place of growth of the ذَنَب [or tail ]: (M:) the pl. of ذَنَبٌ is أَذْنَابٌ . (S, M, A, Msb, K.) [Hence the following phrases &c.] -b2- رَكِبَ ذَنَبَ البَعِيرِ [lit. He rode on the tail of the camel, meaning] (tropical:) he was content with a deficient lot. (T, A, K.) -b3- ضَرَبَ بِذَنِبِهِ [lit. ذَنَبَةٌ ذ , and its pl. ذَنَبَاتٌ : see the next preceding paragraph, in three places.', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_49524c2683760625', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_7726ff3fd467ba81', 'ذنب', 'e14.raw', 24, 2, 'definition', 'en', 'ذِنَابٌ ذ : see ذَنَبٌ , in five places: -b2- and see also مِذْنَبٌ . -b3- Also A small cord with which a camel''s tail is tied to his hind girth, lest he should swing about his tail and so dirt his rider. (M, K.)', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_8bcce82bc39ab84e', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_7d349ba82f8ed98a', 'ذنب', 'e5.raw', 15, 2, 'definition', 'en', '5 تذنّب عَلَى فُلَانٍ ذ He accused such a one of a sin, crime, fault, misdemeanour, or the like, which he had not committed, or though he had not committed any. (A, TA.) -A2- See also 2, near the end of the paragraph. -b2- تَذَنَّبْتُ الوَادِىَ (tropical:) I came to the valley from the direction of its ذَنَب [q. v.]. (A.) And تذنّب الطَّرِيقَ (tropical:) He took the road; (K, TA;) as though he took its ذِنَابَة , or came to it from [the direction of] its ذَنَب . (TA.)', 'derived_from_raw_tei', 980);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d0fcceb6811b2263', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_848fd2db4e2e11fa', 'ذنب', 'e17.raw', 27, 2, 'definition', 'en', 'دُنَابَةٌ ذ The أَلْف [i. e. toe, or foremost extremity, also called the أَسَلَة ,] of a sandal. (K.) -b2- See also ذَنَبٌ , in six places. -b3- And see مِذْنَبٌ .', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_95673d41bae0dc95', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_91a018aedd684491', 'ذنب', 'e26.raw', 36, 2, 'definition', 'en', 'مِذْنَبٌ ذ A long tail. (IAar, T, K.) -b2- And [hence, app. for ذُو مِذْنَبٍ ], (T,) or , (TA, [but see this latter below,]) A [ lizard of the kind called ] ضَبّ . (T, TA.) -b3- Also, (S, K,) or , like مَقْعَدٌ , (A,) and , (M, TA,) (assumed tropical:) A ladle; (S, M, A, K;) because it has a tail, or what resembles a tail: (M:) pl. مَذَانِبُ . (S, M.) -b4- And (assumed tropical:) A water-course, or channel of a torrent, in a tract at the foot of a mountain; (Lth, T, S, M, A, K;) not wide; (A;) or not very wide; (M;) or not very long and wide; (Lth, T;) as also : (S:) the تَلْعَة is in the lower part of a mountain (Lth, T, A) or in an acclivity: (Lth, T, S, A:) also a water-course or channel of a torrent, between what are termed تَلْعَتَانِ ; (TA; [see تَلْعَةٌ مِذْنَبَةٌ ذ : see the next preceding paragraph.', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_5201563a373eae80', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_a01c9534e1a862ab', 'ذنب', 'e13.raw', 23, 2, 'definition', 'en', 'ذُنَابٌ ذ : see ذَنَبٌ , in two places.', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_9a128bf28b9f4158', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_b28b4b302fb83276', 'ذنب', 'e10.raw', 20, 2, 'definition', 'en', 'ذُنُبَاتٌ ذ : see ذَنَبٌ , in the latter half of the paragraph.', 'derived_from_raw_tei', 981);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_2a7d2e54cfa880f3', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_c558663c5538105e', 'ذنب', 'e32.raw', 42, 2, 'definition', 'en', 'مُسْتَذْنِبٌ ذ : see مُذَانِبٌ . -b2- Also One who is at the tails of camels, (S, TA,) not quitting their track. (TA.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_7225043ef4259b5c', 'lane_lexicon', 're_lane_abf7a087ec673aaf', 'sec_lane_c7635454a90d9269', 'ذنب', 'e21.raw', 31, 2, 'definition', 'en', 'ذُنَيْبِىٌّ ذ (assumed tropical:) A certain kind of [ the striped garments called ] بُرُود [pl. of بُرْدٌ ]; (AHeyth, K;) as also . (TA.)', 'derived_from_raw_tei', 982);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_fa52dafaef6d4e79', 'lane_lexicon', 're_lane_aeab8270f5544fb8', 'sec_lane_2397e6c58e148e57', 'ذام', 'e3.raw', 13, 2, 'definition', 'en', 'ذَأْمٌ ذ i. q. عَيْبٌ [as a subst., meaning A vice, fault, defect, or the like; like ذَامٌ , without ء , and ذَيْمٌ ; as well as an inf. n. of 1, q. v.]: with and without ء (S.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_e2673e44236c69e6', 'lane_lexicon', 're_lane_aeab8270f5544fb8', 'sec_lane_2993825e3a8561f6', 'ذام', 'e1.raw', 11, 2, 'definition', 'en', '1 ذَأَمَهُ ذ , (T, S, M, Msb, K,) aor. ذَأََ , (S, M, Msb, K,) inf. n. ذَأْمٌ , (S, * M,) He blamed, or found fault with, him, or it; (T, S, Msb;) namely, a man, (T, [in which it is said that ذَأَمْتُهُ in the sense of عِبْتُهُ is more common than ذَمَمْتُهُ , ” though the contr. seems to be manifestly the case,]) or a commodity; (Msb;) and he despised him; like ذَأَبَهُ : (S:) and he despised him and beat him: (T:) and he despised him and blamed him: (T, M, K:) or he despised him and drove him away; like ذَأَبَهُ : (M:) and simply he drove him away: (M, K:) or he drove him away and beat him; like ذَأَبَهُ : (M and TA in art. ذأب :) and he repaid him, or requited him; syn. جَزَاهُ : (T and M:) or he overcame him in abasing; syn. خَزَاهُ . (K and TA. [So in my MS. copy of the K and in the CK: but I doubt not that جَزَاهُ is the right reading.])', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_926363cfd216d429', 'lane_lexicon', 're_lane_aeab8270f5544fb8', 'sec_lane_d9403a7cc3470d36', 'ذام', 'e4.raw', 14, 2, 'definition', 'en', 'ذَأْمَةٌ ذ A word: so in the saying, مَا سَمِعْتُ لَهُ ذَأْمَةً [ I heard not a word that he had to utter]. (K.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_d4bb078a7439fa6a', 'lane_lexicon', 're_lane_aeab8270f5544fb8', 'sec_lane_a45a216a9953959f', 'ذام', 'e2.raw', 12, 2, 'definition', 'en', '4 اذأمهُ ذ , (TA,) inf. n. إِذْآمٌ , (K, TA,) He frightened him, or terrified him; syn. of the inf. n. رُعْبٌ . (K, TA.) -b2- أَذْأَمْتَنِى عَلَى كَذَا Thou compelledst me against my will to do such a thing. (Fr, S.)', 'derived_from_raw_tei', 951);
INSERT OR IGNORE INTO ar_ling_lexicon_block (id, source_slug, root_entry_id, section_id, root_norm, block_path, block_seq, depth, block_type, lang, text_plain, origin, printed_page) VALUES ('blk_lane_raw_851c799c4e9bd459', 'lane_lexicon', 're_lane_aeab8270f5544fb8', 'sec_lane_c8effea79efbe996', 'ذام', 'e5.raw', 15, 2, 'definition', 'en', 'مَذْؤُومٌ ذ pass. part. n. of 1. (S, Msb.) مَذْؤُومًا in the Kur [vii. 17] means Blamed: (TA:) or driven away: (M, TA:) or, accord. to Lh and Mujáhid, banished. (T, TA. *)', 'derived_from_raw_tei', 951);

